import type {
  AgentMessage,
  AssistantMessage,
  ToolResultMessage,
  ToolTextContent,
  UserMessage,
} from "./agent/types";

export type ToolCallStatus = "pending" | "running" | "complete" | "error";

export type MessagePart =
  | { type: "text"; text: string }
  | { type: "thinking"; thinking: string }
  | {
      type: "toolCall";
      id: string;
      name: string;
      args: Record<string, unknown>;
      status: ToolCallStatus;
      result?: string;
      statusText?: string;
    };

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  parts: MessagePart[];
  timestamp: number;
}

export type WarningLevel = "ok" | "warning" | "critical";

export interface SessionStats {
  inputTokens: number;
  outputTokens: number;
  cacheRead: number;
  cacheWrite: number;
  contextWindow: number;
  lastInputTokens: number;
  /** Estimated total tokens in context (including history, system prompt, tools) */
  estimatedTokens: number;
  /** Warning level based on context usage */
  warningLevel: WarningLevel;
}

const LLM_WIKI_SKILL_PATH = "/home/skills/llm-wiki/SKILL.md";
const LLM_WIKI_ROOT = "/home/user/uploads/wiki";
const INTERNAL_ATTACHMENT_PREFIXES = ["wiki/"];
const INTERNAL_ATTACHMENT_NAMES = new Set([
  ".officeai-workflow-progress.md",
]);
const SPREADSHEET_ATTACHMENT_PATTERN = /\.(csv|tsv|xlsx|xls|xlsm|xlsb|ods)$/i;

interface AttachmentEnrichmentOptions {
  includeLlmWiki?: boolean;
}

function normalizeAttachmentName(name: string): string {
  return name.replace(/\\/g, "/").replace(/^\/+/, "").trim();
}

function isInternalAttachment(name: string): boolean {
  const normalized = normalizeAttachmentName(name).toLowerCase();
  if (!normalized) {
    return false;
  }

  if (INTERNAL_ATTACHMENT_NAMES.has(normalized)) {
    return true;
  }

  return INTERNAL_ATTACHMENT_PREFIXES.some((prefix) =>
    normalized.startsWith(prefix),
  );
}

function isSpreadsheetAttachment(name: string): boolean {
  return SPREADSHEET_ATTACHMENT_PATTERN.test(normalizeAttachmentName(name));
}

export function shouldActivateLlmWiki(attachments?: string[]): boolean {
  if (!attachments || attachments.length === 0) {
    return false;
  }

  if (attachments.length >= 2) {
    return true;
  }

  return attachments.some((name) => isSpreadsheetAttachment(name));
}

export function resolveAttachmentNames(
  requestedAttachments?: string[],
  liveUploads?: string[],
): string[] | undefined {
  const merged = new Set<string>();

  for (const name of requestedAttachments ?? []) {
    const normalized = normalizeAttachmentName(name);
    if (normalized.length > 0 && !isInternalAttachment(normalized)) {
      merged.add(normalized);
    }
  }

  for (const name of liveUploads ?? []) {
    const normalized = normalizeAttachmentName(name);
    if (normalized.length > 0 && !isInternalAttachment(normalized)) {
      merged.add(normalized);
    }
  }

  return merged.size > 0 ? [...merged] : undefined;
}

export function buildAttachmentsEnrichment(
  attachments?: string[],
  options?: AttachmentEnrichmentOptions,
): string {
  if (!attachments || attachments.length === 0) {
    return "";
  }

  const filteredAttachments = attachments
    .map((name) => normalizeAttachmentName(name))
    .filter((name) => name.length > 0 && !isInternalAttachment(name));

  if (filteredAttachments.length === 0) {
    return "";
  }

  const includeLlmWiki = options?.includeLlmWiki ?? true;
  const attachmentPaths = filteredAttachments
    .map((name) => `/home/user/uploads/${name}`)
    .join("\n");

  const attachmentsBlock = `<attachments>\n${attachmentPaths}\n</attachments>\n\n`;

  if (!includeLlmWiki || !shouldActivateLlmWiki(filteredAttachments)) {
    return attachmentsBlock;
  }

  const spreadsheetCount = filteredAttachments.filter((name) =>
    isSpreadsheetAttachment(name),
  ).length;
  const activationReason =
    spreadsheetCount > 0
      ? "spreadsheet_analysis_coverage"
      : "multiple_uploaded_files";

  const llmWikiBlock = `<llm_wiki>\nactivate: true\nreason: ${activationReason}\nfileCount: ${filteredAttachments.length}\nspreadsheetCount: ${spreadsheetCount}\nskill: ${LLM_WIKI_SKILL_PATH}\nwikiRoot: ${LLM_WIKI_ROOT}\n</llm_wiki>\n\n`;

  return `${llmWikiBlock}${attachmentsBlock}`;
}

export function stripEnrichment(
  content: string | { type: string; text?: string }[],
): string {
  let text: string;
  if (typeof content === "string") {
    text = content;
  } else {
    text = content
      .filter((c) => c.type === "text")
      .map((c) => c.text ?? "")
      .join("\n");
  }
  text = text.replace(/^<llm_wiki>\n[\s\S]*?\n<\/llm_wiki>\n\n/, "");
  text = text.replace(/^<attachments>\n[\s\S]*?\n<\/attachments>\n\n/, "");
  text = text.replace(/^<wb_context>\n[\s\S]*?\n<\/wb_context>\n\n/, "");
  return text;
}

export function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function extractPartsFromAssistantMessage(
  message: AgentMessage,
  existingParts: MessagePart[] = [],
): MessagePart[] {
  if (message.role !== "assistant") return existingParts;

  const assistantMsg = message as AssistantMessage;
  const existingToolCalls = new Map<string, MessagePart>();
  for (const part of existingParts) {
    if (part.type === "toolCall") {
      existingToolCalls.set(part.id, part);
    }
  }

  return assistantMsg.content.map((block): MessagePart => {
    if (block.type === "text") {
      return { type: "text", text: block.text };
    }
    if (block.type === "thinking") {
      return { type: "thinking", thinking: block.thinking };
    }
    const existing = existingToolCalls.get(block.id);
    return {
      type: "toolCall",
      id: block.id,
      name: block.name,
      args: block.arguments as Record<string, unknown>,
      status: existing?.type === "toolCall" ? existing.status : "pending",
      result: existing?.type === "toolCall" ? existing.result : undefined,
      statusText:
        existing?.type === "toolCall" ? existing.statusText : undefined,
    };
  });
}

export function agentMessagesToChatMessages(
  agentMessages: AgentMessage[],
): ChatMessage[] {
  const result: ChatMessage[] = [];
  for (const msg of agentMessages) {
    if (msg.role === "user") {
      const text = stripEnrichment((msg as UserMessage).content);
      result.push({
        id: generateId(),
        role: "user",
        parts: [{ type: "text", text }],
        timestamp: msg.timestamp,
      });
    } else if (msg.role === "assistant") {
      const parts = extractPartsFromAssistantMessage(msg);
      result.push({
        id: generateId(),
        role: "assistant",
        parts,
        timestamp: msg.timestamp,
      });
    } else if (msg.role === "tool") {
      const toolResult = msg as ToolResultMessage;
      for (let i = result.length - 1; i >= 0; i--) {
        const chatMsg = result[i];
        if (chatMsg.role !== "assistant") continue;
        const partIdx = chatMsg.parts.findIndex(
          (p) => p.type === "toolCall" && p.id === toolResult.toolCallId,
        );
        if (partIdx !== -1) {
          const part = chatMsg.parts[partIdx];
          if (part.type === "toolCall") {
            const resultText = toolResult.content
              .filter((c): c is ToolTextContent => c.type === "text")
              .map((c) => c.text)
              .join("\n");
            chatMsg.parts[partIdx] = {
              ...part,
              status: toolResult.isError ? "error" : "complete",
              result: resultText,
              statusText: undefined,
            };
          }
          break;
        }
      }
    }
  }
  return result;
}

export function deriveStats(
  agentMessages: AgentMessage[],
  estimatedTokens = 0,
): Omit<SessionStats, "contextWindow"> {
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheRead = 0;
  let cacheWrite = 0;
  let lastInputTokens = 0;
  for (const msg of agentMessages) {
    if (msg.role === "assistant") {
      const u = (msg as AssistantMessage).usage;
      if (u) {
        inputTokens += u.input;
        outputTokens += u.output;
        cacheRead += u.cacheRead;
        cacheWrite += u.cacheWrite;
        lastInputTokens = u.input + u.cacheRead + u.cacheWrite;
      }
    }
  }

  // Determine warning level based on estimated tokens vs last input tokens
  let warningLevel: WarningLevel = "ok";
  if (estimatedTokens > 0) {
    const contextWindow =
      lastInputTokens > 0 ? lastInputTokens * 2 : estimatedTokens;
    const usageRatio = estimatedTokens / contextWindow;
    if (usageRatio > 0.9) warningLevel = "critical";
    else if (usageRatio > 0.75) warningLevel = "warning";
  } else if (lastInputTokens > 0) {
    // Fallback: estimate based on last input
    const estimatedTotal = inputTokens + outputTokens + lastInputTokens * 0.5;
    const usageRatio = estimatedTotal / (lastInputTokens * 1.5);
    if (usageRatio > 0.9) warningLevel = "critical";
    else if (usageRatio > 0.75) warningLevel = "warning";
  }

  return {
    inputTokens,
    outputTokens,
    cacheRead,
    cacheWrite,
    lastInputTokens,
    estimatedTokens,
    warningLevel,
  };
}
