import { Type } from "@sinclair/typebox";
import type { ToolResult } from "../agent/types";
import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  formatSize,
  truncateHead,
} from "../truncate";
import {
  fileExists,
  getFileType,
  listUploads,
  readFileBuffer,
  toBase64,
} from "../vfs";
import { defineTool, toolError, toolSuccess, toolText } from "./types";

export const readTool = defineTool({
  name: "read",
  label: "Read",
  description:
    "Read a file from the virtual filesystem. Files are uploaded to /home/user/uploads/. " +
    "For images (png, jpg, gif, webp), returns the image for visual analysis. " +
    "For documents, you can read either the original or the parsed (.parsed.txt) version. " +
    "Use 'bash ls /home/user/uploads' to see all available files and versions.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file. Can be absolute (starting with /) or relative to /home/user/uploads/. Example: 'image.png' or '/home/user/uploads/data.csv'",
    }),
    offset: Type.Optional(
      Type.Number({
        description: "Line number to start reading from (1-indexed)",
      }),
    ),
    limit: Type.Optional(
      Type.Number({
        description: "Maximum number of lines to read",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const path = params.path;
      const fullPath = path.startsWith("/")
        ? path
        : `/home/user/uploads/${path}`;

      // Check if file exists
      if (!(await fileExists(fullPath))) {
        // List available files to help the user
        const uploads = await listUploads();

        // Check if they might be looking for a parsed version
        const baseName = fullPath.split("/").pop() || "";
        const parsedVersion = uploads.find(
          (u) =>
            u === `${baseName}.parsed.txt` || baseName === `${u}.parsed.txt`,
        );

        let hint: string;
        if (uploads.length === 0) {
          hint = "No files uploaded yet.";
        } else if (parsedVersion) {
          hint = `Did you mean '${parsedVersion}'? Available files: ${uploads.join(", ")}`;
        } else {
          hint = `Available files: ${uploads.join(", ")}`;
        }
        return toolError(`File not found: ${fullPath}. ${hint}`);
      }

      const filename = fullPath.split("/").pop() || "";
      const { isImage, mimeType } = getFileType(filename);

      if (isImage) {
        // Return image as base64 for vision models
        const data = await readFileBuffer(fullPath);
        const base64 = toBase64(data);
        // Return ToolResult-compatible result with image content
        const result: {
          content: Array<
            | { type: "text"; text: string }
            | { type: "image"; data: string; mimeType: string }
          >;
          details?: unknown;
        } = {
          content: [
            {
              type: "text" as const,
              text: `Read image file: ${filename} [${mimeType}]`,
            },
            { type: "image" as const, data: base64, mimeType },
          ],
          details: { filename, mimeType },
        };
        return result as ToolResult;
      }

      // For text files, apply truncation
      const data = await readFileBuffer(fullPath);
      const decoder = new TextDecoder();
      const text = decoder.decode(data);

      const allLines = text.split("\n");
      const totalFileLines = allLines.length;

      // Apply offset (1-indexed to 0-indexed)
      const startLine = params.offset ? Math.max(0, params.offset - 1) : 0;
      const startLineDisplay = startLine + 1;

      if (startLine >= allLines.length) {
        return toolError(
          `Offset ${params.offset} is beyond end of file (${allLines.length} lines total)`,
        );
      }

      // Apply limit param if specified
      let selectedContent: string;
      let userLimitedLines: number | undefined;

      if (params.limit !== undefined) {
        const endLine = Math.min(startLine + params.limit, allLines.length);
        selectedContent = allLines.slice(startLine, endLine).join("\n");
        userLimitedLines = endLine - startLine;
      } else {
        selectedContent = allLines.slice(startLine).join("\n");
      }

      // Apply truncation
      const truncation = truncateHead(selectedContent);
      let outputText: string;

      if (truncation.truncated) {
        const endLineDisplay = startLineDisplay + truncation.outputLines - 1;
        const nextOffset = endLineDisplay + 1;
        outputText = truncation.content;

        if (truncation.truncatedBy === "lines") {
          outputText += `\n\n[Showing lines ${startLineDisplay}-${endLineDisplay} of ${totalFileLines}. Use offset=${nextOffset} to continue.]`;
        } else {
          outputText += `\n\n[Showing lines ${startLineDisplay}-${endLineDisplay} of ${totalFileLines} (${formatSize(DEFAULT_MAX_BYTES)} limit). Use offset=${nextOffset} to continue.]`;
        }
      } else if (
        userLimitedLines !== undefined &&
        startLine + userLimitedLines < allLines.length
      ) {
        const remaining = allLines.length - (startLine + userLimitedLines);
        const nextOffset = startLine + userLimitedLines + 1;
        outputText = truncation.content;
        outputText += `\n\n[${remaining} more lines in file. Use offset=${nextOffset} to continue.]`;
      } else {
        outputText = truncation.content;
      }

      return toolText(outputText);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error reading file";
      return toolError(message);
    }
  },
});
