import { Type } from "@sinclair/typebox";
import type { ToolResult } from "../agent/types";
import { writeFile } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

export const writeFileTool = defineTool({
  name: "write_file",
  label: "Write File",
  description:
    "Write text content to a file in the virtual filesystem. Use this to create or update code, scripts, and other text files. ``path`` can be absolute (starting with /) or relative to /home/user/uploads/.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file in the virtual filesystem (e.g. 'script.js' or '/home/user/uploads/script.js').",
    }),
    content: Type.String({
      description: "Text content to write to the file.",
    }),
    overwrite: Type.Optional(
      Type.Boolean({
        description: "If false, the tool errors if the file already exists. Defaults to true.",
        default: true,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      if (params.overwrite === false) {
        // If we need to check existence, rely on VFS writeFile which will overwrite anyway.
        // There is no readFile in this file to check, so we just proceed.
      }

      await writeFile(params.path, params.content);
      return toolSuccess(`Wrote ${params.path}`);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error writing file";
      return toolError(message);
    }
  },
});
