import type { ProviderConfig } from "../provider-config";
import { writeFile } from "../vfs";

export interface DocumentIntelligenceConfig {
  endpoint: string;
  apiKey: string;
}

export interface ParsedDocument {
  content: string;
  pages: number;
  tables: number;
}

// Type definitions for the REST API response
interface AnalyzeResult {
  pages?: Array<{
    lines?: Array<{ content?: string }>;
  }>;
  tables?: Array<{
    cells?: Array<{
      rowIndex?: number;
      content?: string;
    }>;
  }>;
  paragraphs?: Array<{ content?: string }>;
}

async function analyzeDocumentWithRest(
  fileData: Uint8Array,
  config: DocumentIntelligenceConfig,
): Promise<ParsedDocument> {
  // Normalize endpoint - remove trailing slash
  const baseUrl = config.endpoint.replace(/\/$/, "");
  const url = `${baseUrl}/documentintelligence/documentModels/prebuilt-layout:analyze?api-version=2024-11-30`;

  // Convert Uint8Array to ArrayBuffer for fetch
  const arrayBuffer = fileData.buffer.slice(
    fileData.byteOffset,
    fileData.byteOffset + fileData.byteLength,
  ) as ArrayBuffer;

  // Start the analysis
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Ocp-Apim-Subscription-Key": config.apiKey,
      "Content-Type": "application/octet-stream",
    },
    body: arrayBuffer,
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Document Intelligence error: ${errorText}`);
  }

  const operationLocation = response.headers.get("operation-location");
  if (!operationLocation) {
    throw new Error("No operation-location header in response");
  }

  // Poll for results
  const result = await pollForResult(operationLocation, config.apiKey);
  return extractContentFromResult(result.analyzeResult);
}

async function pollForResult(
  operationUrl: string,
  apiKey: string,
  options?: { intervalMs?: number; maxAttempts?: number },
): Promise<{ analyzeResult: AnalyzeResult }> {
  const intervalMs = options?.intervalMs ?? 1000;
  const maxAttempts = options?.maxAttempts ?? 60;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, intervalMs));

    const statusResponse = await fetch(operationUrl, {
      headers: {
        "Ocp-Apim-Subscription-Key": apiKey,
      },
    });

    if (!statusResponse.ok) {
      const errorText = await statusResponse.text();
      throw new Error(`Failed to check status: ${errorText}`);
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const statusBody: any = await statusResponse.json();
    const status = statusBody.status?.toLowerCase();

    if (status === "succeeded") {
      return { analyzeResult: statusBody.analyzeResult as AnalyzeResult };
    }
    if (status === "failed") {
      throw new Error(
        `Document analysis failed: ${statusBody.error?.message ?? "Unknown error"}`,
      );
    }
    // Otherwise continue polling (status is "running" or "notStarted")
  }

  throw new Error(`Document analysis timed out after ${maxAttempts} attempts`);
}

function extractContentFromResult(result: AnalyzeResult): ParsedDocument {
  let content = "";
  let tableCount = 0;

  if (result.pages) {
    for (const page of result.pages) {
      if (page.lines) {
        for (const line of page.lines) {
          content += `${line.content ?? ""}\n`;
        }
      }
      content += "\n";
    }
  }

  if (result.tables) {
    tableCount = result.tables.length;
    for (const table of result.tables) {
      content += "\n--- TABLE ---\n";
      if (table.cells) {
        const rows = new Map<number, string[]>();
        for (const cell of table.cells) {
          const rowIdx = cell.rowIndex ?? 0;
          if (!rows.has(rowIdx)) {
            rows.set(rowIdx, []);
          }
          rows.get(rowIdx)!.push(cell.content ?? "");
        }
        for (let i = 0; i < rows.size; i++) {
          const row = rows.get(i);
          if (row) {
            content += `${row.join("\t")}\n`;
          }
        }
      }
      content += "--- END TABLE ---\n";
    }
  }

  if (result.paragraphs) {
    for (const para of result.paragraphs) {
      if (para.content) {
        content += `${para.content}\n\n`;
      }
    }
  }

  return {
    content: content.trim(),
    pages: result.pages?.length ?? 0,
    tables: tableCount,
  };
}

export async function processDocumentWithIntelligence(
  file: File,
  fileData: Uint8Array,
  config: DocumentIntelligenceConfig,
): Promise<{
  originalPath: string;
  parsedPath: string | null;
  parsedDocument: ParsedDocument | null;
}> {
  const originalPath = `/home/user/uploads/${file.name}`;
  const fileExt = file.name.toLowerCase().slice(file.name.lastIndexOf("."));

  // List of supported document/image formats for Document Intelligence
  const supportedExtensions = [
    ".pdf",
    ".docx",
    ".doc",
    ".xlsx",
    ".xls",
    ".pptx",
    ".ppt",
    ".png",
    ".jpg",
    ".jpeg",
    ".tiff",
    ".bmp",
  ];

  // Always write the original file first
  await writeFile(file.name, fileData);

  if (!supportedExtensions.includes(fileExt)) {
    return { originalPath, parsedPath: null, parsedDocument: null };
  }

  try {
    const parsedDocument = await analyzeDocumentWithRest(fileData, config);

    if (parsedDocument.content) {
      const parsedFileName = `${file.name}.parsed.txt`;
      await writeFile(parsedFileName, parsedDocument.content);
      return {
        originalPath,
        parsedPath: `/home/user/uploads/${parsedFileName}`,
        parsedDocument,
      };
    }
  } catch (error) {
    console.error("[DocumentIntelligence] Failed to analyze document:", error);
  }

  await writeFile(file.name, fileData);
  return { originalPath, parsedPath: null, parsedDocument: null };
}

export function getDocumentIntelligenceConfig(
  providerConfig: ProviderConfig,
): DocumentIntelligenceConfig | null {
  if (
    providerConfig.documentIntelligenceEndpoint &&
    providerConfig.documentIntelligenceKey
  ) {
    return {
      endpoint: providerConfig.documentIntelligenceEndpoint,
      apiKey: providerConfig.documentIntelligenceKey,
    };
  }
  return null;
}
