import type { Static, TObject } from "@sinclair/typebox";
import type { Tool, ToolResult } from "../agent/types";
import { AIRGAP_CONFIG } from "../airgap-config";
import type { DirtyRange } from "../dirty-tracker";
import { truncateToolResult } from "../token-manager";

export type { Tool, ToolResult };
export { truncateToolResult };

export interface DirtyTrackingConfig<T> {
  /** Derive dirty ranges from params and optionally the result (for success only) */
  getRanges: (params: T, result?: unknown) => DirtyRange[];
}

interface ToolConfig<T extends TObject> {
  name: string;
  label: string;
  description: string;
  parameters: T;
  execute: (
    toolCallId: string,
    params: Static<T>,
    signal?: AbortSignal,
  ) => Promise<ToolResult>;
  dirtyTracking?: DirtyTrackingConfig<Static<T>>;
}

export function defineTool<T extends TObject>(config: ToolConfig<T>): Tool {
  if (!config.dirtyTracking) {
    return config as unknown as Tool;
  }

  const { dirtyTracking, execute, ...rest } = config;

  const wrappedExecute = async (
    toolCallId: string,
    params: Static<T>,
    signal?: AbortSignal,
  ): Promise<ToolResult> => {
    const result = await execute(toolCallId, params, signal);
    const first = result.content[0];
    if (!first || first.type !== "text") return result;
    const text = first.text;

    try {
      const parsed = JSON.parse(text);
      if (parsed.error) return result; // Don't track errors

      const dirtyRanges = dirtyTracking.getRanges(params, parsed);
      if (dirtyRanges.length > 0) {
        parsed._dirtyRanges = dirtyRanges;
        return {
          content: [{ type: "text", text: JSON.stringify(parsed) }],
          details: undefined,
        };
      }
    } catch {
      // Invalid JSON, return as-is
    }
    return result;
  };

  return { ...rest, execute: wrappedExecute } as unknown as Tool;
}

export function toolSuccess(data: unknown): ToolResult {
  const result =
    typeof data === "object" && data !== null ? { ...data } : { result: data };
  let resultText = JSON.stringify(result);

  // Truncate large results for air-gapped environments with token limits
  resultText = truncateToolResult(
    resultText,
    AIRGAP_CONFIG.tokens.maxToolResultTokens,
  );

  return {
    content: [{ type: "text", text: resultText }],
    details: undefined,
  };
}

export function toolError(message: string): ToolResult {
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify({ success: false, error: message }),
      },
    ],
    details: undefined,
  };
}

export function toolText(text: string): ToolResult {
  return {
    content: [{ type: "text", text }],
    details: undefined,
  };
}
