import { AIRGAP_CONFIG } from "../airgap-config";
import {
  MAX_CONTEXT_TOKENS,
  MAX_INPUT_TOKENS,
  estimateTokens,
  type TokenCount,
  prepareMessagesForApi,
  truncateToolResult,
} from "../token-manager";
import { type WorkflowManager, createWorkflowManager } from "../workflow";

import type {
  AgentEvent,
  AgentEventHandler,
  AgentMessage,
  AgentState,
  AssistantContentBlock,
  AssistantMessage,
  OpenAICompatibleClient,
  ThinkingLevel,
  Tool,
  ToolCallContentBlock,
  ToolResult,
  ToolResultMessage,
  UsageInfo,
  UserMessage,
} from "./types";

export interface OpenAIAgentConfig {
  /** OpenAI API key */
  apiKey: string;
  /** OpenAI model to use (e.g., gpt-4o, gpt-4o-mini) */
  model: string;
  /** OpenAI base URL - defaults to https://api.openai.com/v1 */
  baseUrl?: string;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  tools: Tool[];
  messages?: AgentMessage[];
  /** Delay between tool execution rounds to avoid rate limits (ms). Default: 1000 */
  rateLimitDelayMs?: number;
  /** Max retries for rate-limited requests. Default: 3 */
  maxRetries?: number;
  /** Max tokens for context window. Default: 128000 */
  maxContextTokens?: number;
  /** Max tokens generated per assistant response. Default: 4096 */
  maxOutputTokens?: number;
  /** Enable circuit breaker for failing requests. Default: true */
  enableCircuitBreaker?: boolean;
  /** Use workflow manager for rate limiting. Default: true */
  useWorkflowManager?: boolean;
  /** Custom workflow manager instance */
  workflowManager?: WorkflowManager;
  /** Workflow rate limit in requests per minute. Default: 50 */
  workflowMaxRequestsPerMinute?: number;
  /** Workflow queue concurrency. Default: 2 */
  workflowMaxConcurrent?: number;
  /** Agent execution behavior model */
  executionModel?: "standard" | "planner";
}

interface ToolCallInProgress {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  accumulatedArgs?: string;
}

interface CircuitBreakerState {
  failures: number;
  lastFailure: number;
  isOpen: boolean;
}

interface RecentToolExecution {
  toolCallId: string;
  completedAt: number;
}

const NON_IDEMPOTENT_TOOL_NAMES = new Set([
  "email_create",
  "email_reply",
  "email_forward",
]);

const NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS = 120000;
const WORKFLOW_PROGRESS_FILE_PATH = "/home/user/uploads/.officeai-workflow-progress.md";

export class OpenAIAgent {
  private client: OpenAICompatibleClient | null = null;
  private config: OpenAIAgentConfig;
  private eventHandlers: AgentEventHandler[] = [];
  private abortController: AbortController | null = null;
  private internalState: AgentState;
  private circuitBreaker: CircuitBreakerState;
  private tokenCount: TokenCount;
  private toolsJson: string;
  private workflowManager: WorkflowManager;
  private ownsWorkflowManager = false;
  private recentToolExecutions = new Map<string, RecentToolExecution>();

  get state(): AgentState {
    return { ...this.internalState };
  }

  get currentTokenCount(): TokenCount {
    return { ...this.tokenCount };
  }

  constructor(config: OpenAIAgentConfig) {
    this.config = {
      rateLimitDelayMs: 1000,
      maxRetries: 3,
      maxContextTokens: MAX_CONTEXT_TOKENS,
      maxOutputTokens: 4096,
      enableCircuitBreaker: true,
      baseUrl: "https://api.openai.com/v1",
      useWorkflowManager: true,
      executionModel: "planner",
      ...config,
    };
    this.internalState = {
      messages: config.messages ?? [],
      systemPrompt: config.systemPrompt,
      thinkingLevel: config.thinkingLevel,
      tools: config.tools,
    };
    this.circuitBreaker = { failures: 0, lastFailure: 0, isOpen: false };
    this.toolsJson = JSON.stringify(this.convertToolsToOpenAIFormat());
    this.tokenCount = { total: 0, system: 0, messages: 0, tools: 0 };

    // Initialize workflow manager
    if (this.config.workflowManager) {
      this.workflowManager = this.config.workflowManager;
      this.ownsWorkflowManager = false;
    } else if (this.config.useWorkflowManager) {
      this.workflowManager = createWorkflowManager("openai", {
        rateLimit: {
          maxRequests: this.config.workflowMaxRequestsPerMinute ?? 50,
          windowMs: 60000,
          adaptiveLimiting: true,
        },
        queue: {
          maxConcurrent: this.config.workflowMaxConcurrent ?? 2,
          maxQueueSize: 50,
          defaultTimeoutMs: 60000,
          enableDeduplication: true,
          dedupWindowMs: 5000,
        },
      });
      this.ownsWorkflowManager = true;
    } else {
      // Create a no-op workflow manager when disabled
      this.workflowManager = createWorkflowManager("openai");
      this.workflowManager.updateRateLimitConfig({ maxRequests: 10000, windowMs: 1000 });
      this.ownsWorkflowManager = true;
    }

    this.initClient();
    this.updateTokenCount();
  }

  private updateTokenCount(): void {
    const { total, system, messages, tools } = prepareMessagesForApi(
      this.internalState.messages,
      this.internalState.systemPrompt,
      this.toolsJson,
      this.config.maxContextTokens,
    ).tokenCount;
    this.tokenCount = { total, system, messages, tools };
  }

  private checkCircuitBreaker(): boolean {
    if (!this.config.enableCircuitBreaker) return false;

    const now = Date.now();
    const cooldownPeriod = 60000; // 1 minute

    if (this.circuitBreaker.isOpen) {
      if (now - this.circuitBreaker.lastFailure > cooldownPeriod) {
        this.circuitBreaker.isOpen = false;
        this.circuitBreaker.failures = 0;
        return false;
      }
      return true;
    }

    return false;
  }

  private recordFailure(): void {
    if (!this.config.enableCircuitBreaker) return;

    this.circuitBreaker.failures++;
    this.circuitBreaker.lastFailure = Date.now();

    if (this.circuitBreaker.failures >= 5) {
      this.circuitBreaker.isOpen = true;
      console.warn(
        "[OpenAIAgent] Circuit breaker opened due to repeated failures",
      );
    }
  }

  private recordSuccess(): void {
    if (!this.config.enableCircuitBreaker) return;
    this.circuitBreaker.failures = Math.max(
      0,
      this.circuitBreaker.failures - 1,
    );
  }

  private getBaseUrl(): string {
    return (this.config.baseUrl || "https://api.openai.com/v1").replace(
      /\/+$/,
      "",
    );
  }

  private initClient(): void {
    const { apiKey, model } = this.config;
    const baseUrl = this.getBaseUrl();
    const maxAttempts = this.config.maxRetries ?? 3;
    const requestTimeoutMs = AIRGAP_CONFIG.timeouts.requestTimeoutMs;

    // Capture reference to workflow manager for rate limiting
    const workflowManager = this.workflowManager;

    const fetchWithTimeout = async (
      url: string,
      init: RequestInit,
      signal?: AbortSignal,
    ): Promise<Response> => {
      const timeoutController = new AbortController();
      const onAbort = () => timeoutController.abort();

      if (signal) {
        if (signal.aborted) {
          timeoutController.abort();
        } else {
          signal.addEventListener("abort", onAbort, { once: true });
        }
      }

      const timeoutId = setTimeout(() => {
        timeoutController.abort();
      }, requestTimeoutMs);

      try {
        return await fetch(url, {
          ...init,
          signal: timeoutController.signal,
        });
      } finally {
        clearTimeout(timeoutId);
        if (signal) {
          signal.removeEventListener("abort", onAbort);
        }
      }
    };

    this.client = {
      streamChatCompletions: async function* (
        _deploymentName: string, // Ignored for OpenAI, uses model instead
        messages: unknown[],
        options?: Record<string, unknown>,
        requestOptions?: { abortSignal?: AbortSignal },
      ): AsyncIterableIterator<{
        choices?: Array<{
          delta?: {
            content?: string;
            reasoning_content?: string;
            tool_calls?: Array<{
              id?: string;
              function?: { name?: string; arguments?: string };
            }>;
          };
          finish_reason?: string | null;
        }>;
        usage?: {
          prompt_tokens?: number;
          completion_tokens?: number;
          total_tokens?: number;
        };
      }> {
        const url = `${baseUrl}/chat/completions`;

        const headers: Record<string, string> = {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        };

        const body = JSON.stringify({
          model,
          messages,
          stream: true,
          ...options,
        });

        // Retry logic with exponential backoff
        let lastError: Error | undefined;

        for (let attempt = 0; attempt < maxAttempts; attempt++) {
          // Wait for rate limit token before making request
          if (attempt === 0) {
            const rateLimitResult = await workflowManager.acquireRateLimitToken(30000);
            if (!rateLimitResult.allowed) {
              throw new Error(`Rate limit exceeded. Retry after ${rateLimitResult.retryAfterMs}ms`);
            }
          }

          if (attempt > 0) {
            const baseDelay = Math.min(2000 * 2 ** (attempt - 1), 30000);
            const jitter = baseDelay * 0.2 * (Math.random() * 2 - 1);
            const delay = Math.max(500, Math.floor(baseDelay + jitter));
            console.log(
              `[OpenAI] Retrying in ${delay}ms (attempt ${attempt + 1}/${maxAttempts})...`,
            );
            await new Promise((resolve) => setTimeout(resolve, delay));
          }

          const response = await fetchWithTimeout(
            url,
            {
            method: "POST",
            headers,
            body,
            },
            requestOptions?.abortSignal,
          );

          if (response.status === 400) {
            workflowManager.reportRecoverableHttpError(400);
          }

          if (response.status === 429) {
            // Report rate limit hit to workflow manager for adaptive throttling
            const retryAfter = response.headers.get("retry-after");
            const retryAfterMs = retryAfter ? Number.parseInt(retryAfter, 10) * 1000 : undefined;
            workflowManager.reportRecoverableHttpError(429, retryAfterMs);

            if (retryAfter) {
              const delayMs = Number.parseInt(retryAfter, 10) * 1000;
              console.log(`[OpenAI] Server requested Retry-After: ${retryAfter}s`);
              await new Promise((resolve) => setTimeout(resolve, delayMs));
              continue;
            }
            lastError = new Error(await response.text());
            continue;
          }

          if (
            response.status >= 500 &&
            response.status < 600 &&
            attempt < maxAttempts - 1
          ) {
            console.warn(`[OpenAI] Server error ${response.status}, will retry...`);
            lastError = new Error(`Server error: ${response.status}`);
            continue;
          }

          if (response.status === 408 || response.status === 524) {
            console.warn("[OpenAI] Request timeout, will retry...");
            lastError = new Error(`Timeout: ${response.status}`);
            continue;
          }

          if (!response.ok) {
            const errorText = await response.text();
            throw new Error(
              `OpenAI API error (${response.status}): ${errorText}`,
            );
          }

          if (!response.body) {
            throw new Error("No response body from OpenAI API");
          }

          // Success - report to workflow manager
          workflowManager.reportSuccess();

          // Stream the response
          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = "";

          try {
            while (true) {
              if (requestOptions?.abortSignal?.aborted) {
                break;
              }

              const { done, value } = await reader.read();
              if (done) break;

              buffer += decoder.decode(value, { stream: true });

              const lines = buffer.split("\n");
              buffer = lines.pop() ?? "";

              for (const line of lines) {
                const trimmed = line.trim();
                if (!trimmed || !trimmed.startsWith("data: ")) continue;

                const data = trimmed.slice(6);

                if (data === "[DONE]") {
                  return;
                }

                try {
                  const parsed = JSON.parse(data);
                  yield parsed;
                } catch {
                  // Invalid JSON, skip this chunk
                }
              }
            }

            if (buffer.trim()) {
              const trimmed = buffer.trim();
              if (trimmed.startsWith("data: ")) {
                const data = trimmed.slice(6);
                if (data && data !== "[DONE]") {
                  try {
                    const parsed = JSON.parse(data);
                    yield parsed;
                  } catch {
                    // Invalid JSON
                  }
                }
              }
            }
          } finally {
            reader.releaseLock();
          }

          return; // Success, exit retry loop
        }

        throw lastError ?? new Error("Max retries exceeded for OpenAI API");
      },
    };
  }

  subscribe(handler: AgentEventHandler): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emit(event: AgentEvent): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error("[OpenAIAgent] Event handler error:", err);
      }
    }
  }

  private createUserMessage(content: string): UserMessage {
    return {
      role: "user",
      content,
      timestamp: Date.now(),
    };
  }

  private createAssistantMessage(
    content: AssistantContentBlock[],
    stopReason: AssistantMessage["stopReason"] = "complete",
    usage?: UsageInfo,
  ): AssistantMessage {
    return {
      role: "assistant",
      content,
      timestamp: Date.now(),
      stopReason,
      usage,
    };
  }

  private createToolResultMessage(
    toolCallId: string,
    content: ToolResult,
    isError: boolean,
  ): ToolResultMessage {
    return {
      role: "tool",
      toolCallId,
      content: content.content,
      isError,
      timestamp: Date.now(),
    };
  }

  private stringifyToolArguments(args: unknown): string {
    try {
      return JSON.stringify(args ?? {});
    } catch {
      return "{}";
    }
  }

  private createToolExecutionFingerprint(
    toolName: string,
    args: Record<string, unknown>,
  ): string {
    const normalizedArgs = Object.keys(args)
      .sort()
      .reduce<Record<string, unknown>>((acc, key) => {
        acc[key] = args[key];
        return acc;
      }, {});

    return `${toolName}:${JSON.stringify(normalizedArgs)}`;
  }

  private pruneRecentToolExecutions(now = Date.now()): void {
    for (const [fingerprint, execution] of this.recentToolExecutions) {
      if (now - execution.completedAt > NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS) {
        this.recentToolExecutions.delete(fingerprint);
      }
    }
  }

  private isNonIdempotentTool(toolName: string): boolean {
    return NON_IDEMPOTENT_TOOL_NAMES.has(toolName);
  }

  private normalizeTextContent(value: unknown): string {
    if (typeof value !== "string") {
      return "";
    }

    return value.trim();
  }

  private getLastUserMessageText(): string {
    for (let i = this.internalState.messages.length - 1; i >= 0; i--) {
      const msg = this.internalState.messages[i];
      if (msg.role === "user") {
        return this.normalizeTextContent((msg as UserMessage).content).toLowerCase();
      }
    }
    return "";
  }

  private isGreetingOrSmallTalk(text: string): boolean {
    if (!text) {
      return false;
    }

    const compact = text.trim().toLowerCase();
    if (!compact) {
      return false;
    }

    if (compact.length > 64) {
      return false;
    }

    return /^(hi|hello|hey|yo|sup|howdy|good\s+(morning|afternoon|evening)|how are you|thanks|thank you|thx|nice to meet you)([!.?,\s].*)?$/.test(
      compact,
    );
  }

  private shouldForcePlannerExecution(lastUserText: string): boolean {
    if (!this.isPlannerMode()) {
      return false;
    }
    return !this.isGreetingOrSmallTalk(lastUserText);
  }

  private hasToolNamed(toolName: string): boolean {
    return this.internalState.tools.some((tool) => tool.name === toolName);
  }

  private shouldUseComplexWorkflowMode(lastUserText: string): boolean {
    if (!this.shouldForcePlannerExecution(lastUserText)) {
      return false;
    }

    const complexSignals = [
      /\bplan\b/i,
      /\bworkflow\b/i,
      /\bcomplex\b/i,
      /\bmulti[-\s]?step\b/i,
      /\bend[-\s]?to[-\s]?end\b/i,
      /\bimplement\b/i,
      /\bexecute\b/i,
      /\bvalidate\b/i,
      /\bquality\b/i,
      /\bcheck\b/i,
      /\bverify\b/i,
      /\baudit\b/i,
    ];

    return (
      lastUserText.length > 220 ||
      complexSignals.some((pattern) => pattern.test(lastUserText))
    );
  }

  private shouldNudgeForActionWithoutTools(
    hasToolCalls: boolean,
    contentBlocks: AssistantContentBlock[],
  ): boolean {
    if (hasToolCalls || this.internalState.tools.length === 0) {
      return false;
    }

    const lastUserText = this.getLastUserMessageText();
    if (!lastUserText) {
      return false;
    }

    const shortAffirmativeReplies = new Set([
      "all",
      "yes",
      "y",
      "ok",
      "okay",
      "sure",
      "go ahead",
      "do it",
      "please do",
      "continue",
      "proceed",
      "a",
      "b",
      "c",
      "d",
      "a+d",
    ]);

    const isShortAffirmative =
      shortAffirmativeReplies.has(lastUserText) ||
      (lastUserText.length <= 24 && /^(yes|all|ok|sure|go ahead|do it|proceed)\b/.test(lastUserText));

    if (!isShortAffirmative) {
      return false;
    }

    const combinedText = contentBlocks
      .filter((b): b is Extract<AssistantContentBlock, { type: "text" }> => b.type === "text")
      .map((b) => b.text)
      .join(" ")
      .toLowerCase();

    return combinedText.length > 0;
  }

  private isPlannerMode(): boolean {
    return this.config.executionModel === "planner";
  }

  private buildPlannerExecutionPrompt(
    hasExecutedToolsInRun: boolean,
    options?: {
      complexMode?: boolean;
      forceCompaction?: boolean;
      executedToolCalls?: number;
    },
  ): string {
    const complexMode = options?.complexMode ?? false;
    const forceCompaction = options?.forceCompaction ?? false;
    const executedToolCalls = options?.executedToolCalls ?? 0;

    if (complexMode) {
      const canUseVfsProgressFile =
        this.hasToolNamed("write_file") && this.hasToolNamed("read");
      const progressFileInstructions = canUseVfsProgressFile
        ? `Context freshness + compaction (required): Use ${WORKFLOW_PROGRESS_FILE_PATH} as your run log in markdown.\n- During PLAN phase: create/update this markdown with sections: Objective, Assumptions, Plan Checklist, Evidence Log, Open Risks, Quality Checks.\n- During EXECUTION phase: update checklist and evidence after meaningful progress.\n- During QUALITY CHECK phase: write pass/fail checks and remediation if needed.\n- Only rewrite this file when content materially changes; avoid redundant read/write loops.\n- When context grows, compact by writing a concise snapshot to this file and continue from the snapshot instead of repeating verbose history.`
        : "Context freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history.";

      const compactionInstruction = forceCompaction
        ? "Compaction checkpoint: perform a compaction update now before further execution."
        : "";

      if (!hasExecutedToolsInRun) {
        return `Planner mode (complex workload): follow three phases and execute now.\nPhase 1 - PLAN: create a short actionable checklist tied to the user request.\nPhase 2 - EXECUTION: immediately start executing checklist items with tools.\nPhase 3 - QUALITY CHECK: before final answer, verify outcomes against requirements and run at least one concrete validation/read-back step.\n${progressFileInstructions}\n${compactionInstruction}\nDo not stop at planning text, do not ask for confirmation, and do not ask the user to paste prior planner output.`;
      }

      return `Planner mode (complex workload): continue execution until complete, then run QUALITY CHECK before final answer.\nExecution status: ${executedToolCalls} tool call(s) executed in this run.\nIf prior planner state is missing, reconstruct remaining steps from tool results, conversation history, and workspace state.\nRequired QUALITY CHECK before final answer:\n- Confirm each user requirement is satisfied.\n- Run concrete verification using available tools (for example read-back, search, or inspection).\n- Report residual risk or gaps explicitly.\n${progressFileInstructions}\n${compactionInstruction}\nDo not ask the user for old checklists/planner output. Only provide a final answer when execution and quality checks are complete.`;
    }

    if (!hasExecutedToolsInRun) {
      return "Planner mode: create a short execution plan from the current request and available conversation context, then immediately call the required tools now. If any prior checklist is missing, infer the next best steps from the repo/files and continue execution. Do not stop at planning text, do not ask for confirmation, and do not ask the user to paste prior planner output.";
    }
    return "Planner mode: continue executing remaining tool steps until complete. If prior planner state is missing, reconstruct the remaining steps from tool results, conversation history, and current workspace state, then keep executing. Do not ask the user for the old checklist or planner output. Only provide a final answer when tool execution is done.";
  }

  private convertMessagesToOpenAIFormat(messages: AgentMessage[]): unknown[] {
    const openaiMessages: unknown[] = [];
    const announcedToolCalls = new Set<string>();
    let skippedOrphanToolMessages = 0;
    let skippedInvalidAssistantMessages = 0;

    const systemPrompt = this.normalizeTextContent(this.internalState.systemPrompt);
    if (systemPrompt) {
      openaiMessages.push({
        role: "system",
        content: systemPrompt,
      });
    }

    for (const msg of messages) {
      if (msg.role === "user") {
        const content = this.normalizeTextContent((msg as UserMessage).content);
        if (!content) {
          continue;
        }

        openaiMessages.push({
          role: "user",
          content,
        });
      } else if (msg.role === "assistant") {
        const assistantMsg = msg as AssistantMessage;
        const textParts: string[] = [];
        const toolCalls: Array<{
          id: string;
          type: string;
          function: { name: string; arguments: string };
        }> = [];

        for (const block of assistantMsg.content) {
          if (block.type === "text") {
            const normalized = this.normalizeTextContent(block.text);
            if (normalized) {
              textParts.push(normalized);
            }
          } else if (block.type === "thinking") {
            const normalized = this.normalizeTextContent(block.thinking);
            if (normalized) {
              textParts.push(`[Thinking: ${normalized}]`);
            }
          } else if (block.type === "tool_call") {
            const id = this.normalizeTextContent(block.id);
            const name = this.normalizeTextContent(block.name);
            if (!id || !name) {
              continue;
            }

            announcedToolCalls.add(id);
            toolCalls.push({
              id,
              type: "function",
              function: {
                name,
                arguments: this.stringifyToolArguments(block.arguments),
              },
            });
          }
        }

        const openaiMsg: Record<string, unknown> = {
          role: "assistant",
        };

        const contentText = textParts.join("\n");
        if (contentText) {
          openaiMsg.content = contentText;
        }

        if (toolCalls.length > 0) {
          openaiMsg.tool_calls = toolCalls;
        }

        if (!("content" in openaiMsg) && !("tool_calls" in openaiMsg)) {
          skippedInvalidAssistantMessages++;
          continue;
        }

        openaiMessages.push(openaiMsg);
      } else if (msg.role === "tool") {
        const toolMsg = msg as ToolResultMessage;
        const toolCallId = this.normalizeTextContent(toolMsg.toolCallId);
        if (!toolCallId || !announcedToolCalls.has(toolCallId)) {
          skippedOrphanToolMessages++;
          continue;
        }

        const text = toolMsg.content
          .filter((c) => c.type === "text")
          .map((c) => (c as { type: "text"; text: string }).text)
          .map((t) => this.normalizeTextContent(t))
          .filter(Boolean)
          .join("\n");

        openaiMessages.push({
          role: "tool",
          tool_call_id: toolCallId,
          content: text || "[Tool result with images]",
        });
      }
    }

    if (skippedOrphanToolMessages > 0) {
      console.warn(
        `[OpenAIAgent] Skipped ${skippedOrphanToolMessages} orphan tool message(s) to avoid OpenAI API errors`,
      );
    }
    if (skippedInvalidAssistantMessages > 0) {
      console.warn(
        `[OpenAIAgent] Skipped ${skippedInvalidAssistantMessages} invalid assistant message(s) with no content/tool_calls`,
      );
    }

    return openaiMessages;
  }

  private convertToolsToOpenAIFormat(): unknown[] {
    return this.internalState.tools.map((tool) => ({
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      },
    }));
  }

  async prompt(content: string): Promise<void> {
    if (!this.client) {
      throw new Error("Agent client not initialized");
    }

    const inputTokens = estimateTokens(content);
    if (inputTokens > MAX_INPUT_TOKENS) {
      throw new Error(
        `Input too large (${inputTokens} estimated tokens). Maximum allowed is ${MAX_INPUT_TOKENS}.`,
      );
    }

    this.abortController = new AbortController();
    const signal = this.abortController.signal;
    this.recentToolExecutions.clear();

    try {
      const userMessage = this.createUserMessage(content);
      this.internalState.messages.push(userMessage);
      await this.runAgentLoop(signal);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error";
      console.error("[OpenAIAgent] Prompt error:", error);

      const errorAssistant: AssistantMessage = {
        role: "assistant",
        content: [{ type: "text", text: `Error: ${errorMessage}` }],
        timestamp: Date.now(),
        stopReason: "error",
        errorMessage: errorMessage,
      };

      this.emit({ type: "message_start", message: errorAssistant });
      this.emit({ type: "message_end", message: errorAssistant });
      this.emit({ type: "agent_end" });
    } finally {
      this.abortController = null;
    }
  }

  private async runAgentLoop(signal: AbortSignal): Promise<void> {
    if (!this.client) return;

    if (this.checkCircuitBreaker()) {
      throw new Error(
        "Circuit breaker is open due to repeated failures. Please wait a minute before retrying.",
      );
    }

    const maxIterations = 50;
    let iterations = 0;
    let actionNudgeUsed = false;
    let plannerNudgesUsed = 0;
    let hasExecutedToolsInRun = false;
    let executedToolCallsInRun = 0;
    let grantedPostToolFinalizationPass = false;
    let plannerDirectiveInjected = false;
    let lastPlannerCompactionCheckpoint = 0;
    const lastUserText = this.getLastUserMessageText();
    const shouldUsePlannerExecution = this.shouldForcePlannerExecution(lastUserText);
    const useComplexWorkflowMode = this.shouldUseComplexWorkflowMode(lastUserText);

    while (iterations < maxIterations && !signal.aborted) {
      iterations++;

      const maxTokens = this.config.maxContextTokens ?? MAX_CONTEXT_TOKENS;

      const { preparedMessages, tokenCount, wasTruncated } =
        prepareMessagesForApi(
          this.internalState.messages,
          this.internalState.systemPrompt,
          this.toolsJson,
          maxTokens,
        );

      this.tokenCount = tokenCount;

      if (wasTruncated) {
        console.log(
          `[OpenAIAgent] Message history truncated for token limit (${tokenCount.total}/${maxTokens})`,
        );
        this.emit({
          type: "message_update",
          message: {
            role: "assistant",
            content: [
              {
                type: "text",
                text: "[Context summary: Earlier messages compressed to stay within token limits.]",
              },
            ],
            timestamp: Date.now(),
          },
        });
      }

      try {
        const shouldForceCompaction =
          useComplexWorkflowMode &&
          hasExecutedToolsInRun &&
          executedToolCallsInRun > 0 &&
          executedToolCallsInRun % 4 === 0;

        const shouldReinjectForCompaction =
          shouldForceCompaction &&
          executedToolCallsInRun > lastPlannerCompactionCheckpoint;

        const plannerInstruction =
          shouldUsePlannerExecution &&
          (!plannerDirectiveInjected || shouldReinjectForCompaction)
            ? this.createUserMessage(
                this.buildPlannerExecutionPrompt(hasExecutedToolsInRun, {
                  complexMode: useComplexWorkflowMode,
                  forceCompaction: shouldForceCompaction,
                  executedToolCalls: executedToolCallsInRun,
                }),
              )
            : null;

        if (plannerInstruction) {
          plannerDirectiveInjected = true;
          if (shouldReinjectForCompaction) {
            lastPlannerCompactionCheckpoint = executedToolCallsInRun;
          }
        }

        const events = await this.client.streamChatCompletions(
          "", // deployment name not used for OpenAI
          this.convertMessagesToOpenAIFormat(
            plannerInstruction ? [...preparedMessages, plannerInstruction] : preparedMessages,
          ),
          {
            tools:
              this.internalState.tools.length > 0
                ? this.convertToolsToOpenAIFormat()
                : undefined,
            tool_choice:
              this.internalState.tools.length > 0 ? "auto" : undefined,
            // Keep execution deterministic by default.
            temperature: 0.2,
            max_completion_tokens: this.config.maxOutputTokens ?? 4096,
            stream_options: { include_usage: true },
          },
          { abortSignal: signal },
        );

        this.recordSuccess();

        const contentBlocks: AssistantContentBlock[] = [];
        const toolCalls: ToolCallInProgress[] = [];
        let usageInfo:
          | {
              prompt_tokens?: number;
              completion_tokens?: number;
              total_tokens?: number;
            }
          | undefined;

        let hitTokenLimit = false;
        let sawToolCallSignal = false;
        for await (const event of events) {
          if (signal.aborted) break;

          if (event.usage) {
            usageInfo = event.usage;
          }

          for (const choice of event.choices ?? []) {
            if (choice.finish_reason === "length") {
              hitTokenLimit = true;
            }
            if (
              choice.finish_reason === "tool_calls" ||
              choice.finish_reason === "function_call"
            ) {
              sawToolCallSignal = true;
            }

            const delta = choice.delta;
            if (delta?.content) {
              const textContent = delta.content;
              const lastBlock = contentBlocks[contentBlocks.length - 1];

              if (lastBlock?.type === "text") {
                lastBlock.text += textContent;
              } else {
                contentBlocks.push({ type: "text", text: textContent });
              }
            }

            if (delta?.reasoning_content) {
              const reasoningText = delta.reasoning_content;
              const lastBlock = contentBlocks[contentBlocks.length - 1];
              if (lastBlock?.type === "thinking") {
                lastBlock.thinking += reasoningText;
              } else {
                contentBlocks.push({
                  type: "thinking",
                  thinking: reasoningText,
                });
              }
            }

            if (delta?.tool_calls) {
              sawToolCallSignal = true;
              for (const tc of delta.tool_calls) {
                if (tc.id) {
                  toolCalls.push({
                    id: tc.id,
                    name: tc.function?.name ?? "",
                    arguments: {},
                    accumulatedArgs: "",
                  });
                }
                if (tc.function?.arguments && toolCalls.length > 0) {
                  const lastTool = toolCalls[toolCalls.length - 1];
                  lastTool.accumulatedArgs += tc.function.arguments;
                }
              }
            }
          }
        }

        if (hitTokenLimit) {
          console.warn(
            "[OpenAIAgent] WARNING: Model hit max_completion_tokens limit.",
          );
        }

        if (contentBlocks.length === 0 && toolCalls.length === 0) {
          console.warn(
            "[OpenAIAgent] Empty response received (no content blocks or tool calls). Will retry in 3 seconds...",
          );
          await new Promise((resolve) => setTimeout(resolve, 3000));
          continue;
        }

        if (sawToolCallSignal && toolCalls.length === 0) {
          console.warn(
            "[OpenAIAgent] Stream indicated tool calling but no parseable tool calls were captured. Retrying once.",
          );
          await new Promise((resolve) => setTimeout(resolve, 800));
          continue;
        }

        for (const tc of toolCalls) {
          if (tc.accumulatedArgs) {
            try {
              tc.arguments = JSON.parse(tc.accumulatedArgs);
            } catch (e) {
              console.warn(
                "[OpenAIAgent] Failed to parse tool arguments:",
                tc.accumulatedArgs,
                e,
              );
              tc.arguments = {};
            }
          }
        }

        for (const tc of toolCalls) {
          contentBlocks.push({
            type: "tool_call",
            id: tc.id,
            name: tc.name,
            arguments: tc.arguments,
          });
        }

        const hasToolCalls = toolCalls.length > 0;
        const stopReason: AssistantMessage["stopReason"] = hasToolCalls
          ? "tool_calls"
          : "complete";

        let usage: UsageInfo | undefined;
        if (usageInfo) {
          usage = {
            input: usageInfo.prompt_tokens ?? 0,
            output: usageInfo.completion_tokens ?? 0,
            cacheRead: 0,
            cacheWrite: 0,
          };
        }

        const assistantMessage = this.createAssistantMessage(
          contentBlocks,
          stopReason,
          usage,
        );
        this.internalState.messages.push(assistantMessage);

        this.emit({ type: "message_start", message: assistantMessage });
        this.emit({ type: "message_update", message: assistantMessage });
        this.emit({ type: "message_end", message: assistantMessage });

        if (hasToolCalls && !signal.aborted) {
          hasExecutedToolsInRun = true;
          executedToolCallsInRun += toolCalls.length;
          console.log(
            `[OpenAIAgent] Executing ${toolCalls.length} tool call(s)...`,
          );
          for (const tc of toolCalls) {
            await this.executeTool(tc, signal);
          }

          const rateLimitDelay = this.config.rateLimitDelayMs ?? 1000;
          if (rateLimitDelay > 0) {
            await new Promise((resolve) =>
              setTimeout(resolve, rateLimitDelay),
            );
          }

          if (iterations >= maxIterations && !grantedPostToolFinalizationPass) {
            grantedPostToolFinalizationPass = true;
            iterations = maxIterations - 1;
            this.internalState.messages.push({
              role: "user",
              content:
                "Iteration budget reached. Use the existing tool results to finish now: run final quality checks and provide the final answer. Do not call more tools unless required to avoid a factual error.",
              timestamp: Date.now(),
            });
          }

          continue;
        }

        const hasOnlyThinking =
          contentBlocks.length > 0 &&
          contentBlocks.every((b) => b.type === "thinking");
        const hasText = contentBlocks.some(
          (b) => b.type === "text" && b.text && b.text.trim().length > 0,
        );

        if (hasOnlyThinking && !hasText) {
          const actionPrompt: UserMessage = {
            role: "user",
            content: "Please proceed with the requested actions using the available tools.",
            timestamp: Date.now(),
          };
          this.internalState.messages.push(actionPrompt);
          iterations = Math.max(0, iterations - 1);
          continue;
        }

        if (
          shouldUsePlannerExecution &&
          !hasExecutedToolsInRun &&
          !hasToolCalls &&
          plannerNudgesUsed < 2
        ) {
          plannerNudgesUsed++;
          this.internalState.messages.push({
            role: "user",
            content:
              "Continue with execution now: call the appropriate tools and proceed without asking additional confirmation.",
            timestamp: Date.now(),
          });
          continue;
        }

        if (
          !actionNudgeUsed &&
          this.shouldNudgeForActionWithoutTools(hasToolCalls, contentBlocks)
        ) {
          actionNudgeUsed = true;
          const actionPrompt: UserMessage = {
            role: "user",
            content:
              "Please execute the requested work now using the available tools and then report concise results.",
            timestamp: Date.now(),
          };
          this.internalState.messages.push(actionPrompt);
          continue;
        }

        break;
      } catch (error) {
        this.recordFailure();
        const errorMessage =
          error instanceof Error ? error.message : "Unknown error";
        console.error("[OpenAIAgent] API call failed:", error);

        const errorAssistant: AssistantMessage = {
          role: "assistant",
          content: [{ type: "text", text: `API Error: ${errorMessage}` }],
          timestamp: Date.now(),
          stopReason: "error",
          errorMessage: errorMessage,
        };

        this.emit({ type: "message_start", message: errorAssistant });
        this.emit({ type: "message_end", message: errorAssistant });
        this.emit({ type: "agent_end" });
        return;
      }
    }

    if (!signal.aborted && iterations >= maxIterations) {
      const limitMessage: AssistantMessage = {
        role: "assistant",
        content: [
          {
            type: "text",
            text:
              "Execution stopped after reaching the iteration budget. Partial results are preserved; retry to continue from current state.",
          },
        ],
        timestamp: Date.now(),
        stopReason: "complete",
      };
      this.emit({ type: "message_start", message: limitMessage });
      this.emit({ type: "message_update", message: limitMessage });
      this.emit({ type: "message_end", message: limitMessage });
    }

    this.emit({ type: "agent_end" });
  }

  private async executeTool(
    toolCall: ToolCallInProgress,
    signal: AbortSignal,
  ): Promise<void> {
    const tool = this.internalState.tools.find((t) => t.name === toolCall.name);

    if (!tool) {
      const errorResult = this.createToolResultMessage(
        toolCall.id,
        {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                error: `Tool ${toolCall.name} not found`,
              }),
            },
          ],
        },
        true,
      );
      this.internalState.messages.push(errorResult);
      return;
    }

    this.emit({
      type: "tool_execution_start",
      toolCallId: toolCall.id,
      name: toolCall.name,
      arguments: toolCall.arguments,
    });

    try {
      // Determine if this is a read operation (for batching)
      const isReadTool = [
        "get_cell_ranges",
        "get_range_as_csv",
        "search_data",
        "get_all_objects",
        "read",
        "bash",
      ].includes(tool.name);
      const isNonIdempotentTool = this.isNonIdempotentTool(tool.name);
      const toolFingerprint = this.createToolExecutionFingerprint(
        tool.name,
        toolCall.arguments,
      );

      this.pruneRecentToolExecutions();

      if (isNonIdempotentTool) {
        const recentExecution = this.recentToolExecutions.get(toolFingerprint);
        if (recentExecution) {
          const skippedDuplicateResult: ToolResult = {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  success: true,
                  skippedDuplicate: true,
                  message:
                    "Skipped duplicate email drafting action because an identical draft was already opened recently.",
                  originalToolCallId: recentExecution.toolCallId,
                }),
              },
            ],
          };

          const toolResult = this.createToolResultMessage(
            toolCall.id,
            skippedDuplicateResult,
            false,
          );
          this.internalState.messages.push(toolResult);

          this.emit({
            type: "tool_execution_update",
            toolCallId: toolCall.id,
            partialResult: skippedDuplicateResult,
          });
          this.emit({
            type: "tool_execution_end",
            toolCallId: toolCall.id,
            result: skippedDuplicateResult,
            isError: false,
          });
          return;
        }
      }

      // Execute through workflow manager for rate limiting
      const result = await this.workflowManager.executeTool(
        tool.name,
        toolCall.arguments,
        async () => {
          if (signal.aborted) {
            throw new Error("Tool execution cancelled");
          }
          return await this.runToolWithTimeout(
            () => tool.execute(toolCall.id, toolCall.arguments, signal),
            AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs,
            `Tool '${tool.name}' timed out after ${AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs}ms`,
          );
        },
        {
          isReadOperation: isReadTool,
          maxRetries: isNonIdempotentTool ? 0 : 2,
          dedupKey: isNonIdempotentTool ? toolFingerprint : undefined,
          onStatus: (statusText) => {
            this.emit({
              type: "tool_execution_update",
              toolCallId: toolCall.id,
              partialResult: undefined,
              statusText,
            });
          },
        },
      );

      if (isNonIdempotentTool) {
        this.recentToolExecutions.set(toolFingerprint, {
          toolCallId: toolCall.id,
          completedAt: Date.now(),
        });
      }

      const toolResult = this.createToolResultMessage(
        toolCall.id,
        result as ToolResult,
        false,
      );
      this.internalState.messages.push(toolResult);

      this.emit({
        type: "tool_execution_update",
        toolCallId: toolCall.id,
        partialResult: result as ToolResult,
      });
      this.emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: result as ToolResult,
        isError: false,
      });
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Tool execution failed";
      const errorResult = this.createToolResultMessage(
        toolCall.id,
        {
          content: [
            { type: "text", text: JSON.stringify({ error: errorMessage }) },
          ],
        },
        true,
      );
      this.internalState.messages.push(errorResult);

      this.emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: { error: errorMessage },
        isError: true,
      });
    }
  }

  abort(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
  }

  reset(): void {
    this.abort();
    this.internalState.messages = [];
    this.recentToolExecutions.clear();
  }

  private async runToolWithTimeout<R>(
    run: () => Promise<R>,
    timeoutMs: number,
    timeoutMessage: string,
  ): Promise<R> {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
    });

    try {
      return await Promise.race([run(), timeoutPromise]);
    } finally {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    }
  }

  dispose(): void {
    this.abort();
    this.eventHandlers = [];
    this.recentToolExecutions.clear();

    if (this.ownsWorkflowManager) {
      this.workflowManager.dispose();
    }
  }

  replaceMessages(messages: AgentMessage[]): void {
    this.internalState.messages = [...messages];
  }

  updateConfig(config: Partial<OpenAIAgentConfig>): void {
    const needsReinit =
      config.apiKey !== undefined ||
      config.baseUrl !== undefined ||
      config.model !== undefined ||
      config.maxRetries !== undefined ||
      config.useWorkflowManager !== undefined ||
      config.workflowManager !== undefined ||
      config.workflowMaxRequestsPerMinute !== undefined ||
      config.workflowMaxConcurrent !== undefined;

    this.config = { ...this.config, ...config };

    if (config.systemPrompt !== undefined) {
      this.internalState.systemPrompt = config.systemPrompt;
    }
    if (config.thinkingLevel !== undefined) {
      this.internalState.thinkingLevel = config.thinkingLevel;
    }
    if (config.tools !== undefined) {
      this.internalState.tools = config.tools;
      this.toolsJson = JSON.stringify(this.convertToolsToOpenAIFormat());
    }
    if (config.messages !== undefined) {
      this.internalState.messages = config.messages;
    }

    if (needsReinit) {
      this.initClient();
    }
  }
}

export function createOpenAIAgent(config: OpenAIAgentConfig): OpenAIAgent {
  return new OpenAIAgent(config);
}
