import type { AgentMessage, UserMessage } from "../agent/types";
import { stripEnrichment } from "../message-utils";

export interface ChatSession {
  id: string;
  workbookId: string;
  name: string;
  agentMessages: AgentMessage[];
  createdAt: number;
  updatedAt: number;
}

export interface VfsFile {
  id: string; // "{sessionId}:{path}" composite key
  sessionId: string;
  path: string;
  data: Uint8Array;
}

export interface SkillFile {
  id: string; // "{skillName}:{path}" composite key
  skillName: string;
  path: string; // relative path within skill folder, e.g. "SKILL.md"
  data: Uint8Array;
}

const sessionStore = new Map<string, ChatSession>();
const vfsFileStore = new Map<string, Map<string, Uint8Array>>();
const skillFileStore = new Map<string, Map<string, Uint8Array>>();
const LEGACY_INDEXED_DB_NAMES = ["OfficeAI", "OpenExcelDB_v3"];

function cloneBytes(data: Uint8Array): Uint8Array {
  const copy = new Uint8Array(data.byteLength);
  copy.set(data);
  return copy;
}

function cloneSession(session: ChatSession): ChatSession {
  return {
    ...session,
    agentMessages: [...(session.agentMessages ?? [])],
  };
}

function deleteIndexedDbDatabase(name: string): Promise<void> {
  if (typeof indexedDB === "undefined") {
    return Promise.resolve();
  }

  return new Promise((resolve) => {
    try {
      const request = indexedDB.deleteDatabase(name);
      request.onsuccess = () => resolve();
      request.onerror = () => resolve();
      request.onblocked = () => resolve();
    } catch {
      resolve();
    }
  });
}


function extractUserText(msg: AgentMessage): string | null {
  if (msg.role !== "user") return null;
  const text = stripEnrichment((msg as UserMessage).content).trim();
  return text || null;
}

function deriveSessionName(agentMessages: AgentMessage[]): string | null {
  const firstUser = agentMessages.find((m) => m.role === "user");
  if (!firstUser) return null;
  const text = extractUserText(firstUser);
  if (!text) return null;
  return text.length > 40 ? `${text.slice(0, 37)}...` : text;
}

export function getSessionMessageCount(session: ChatSession): number {
  return (session.agentMessages ?? []).filter(
    (m) => m.role === "user" || m.role === "assistant",
  ).length;
}

export async function getOrCreateWorkbookId(): Promise<string> {
  // Outlook doesn't have document.settings, use a fixed ID based on mailbox
  if (Office.context.mailbox) {
    return (
      "outlook-" +
      (Office.context.mailbox.userProfile?.emailAddress ?? crypto.randomUUID())
    );
  }

  // Excel and other hosts use document.settings
  return new Promise((resolve, reject) => {
    const settings = Office.context.document?.settings;
    if (!settings) {
      // Fallback for hosts without document.settings
      resolve("host-" + crypto.randomUUID());
      return;
    }

    let workbookId = settings.get("officeai-workbook-id") as string | null;

    if (workbookId) {
      resolve(workbookId);
      return;
    }

    workbookId = crypto.randomUUID();
    settings.set("officeai-workbook-id", workbookId);
    settings.saveAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(workbookId);
      } else {
        reject(
          new Error(result.error?.message ?? "Failed to save workbook ID"),
        );
      }
    });
  });
}

export async function listSessions(workbookId: string): Promise<ChatSession[]> {
  const sessions = [...sessionStore.values()].filter(
    (session) => session.workbookId === workbookId,
  );
  for (const s of sessions) {
    if (!s.agentMessages) s.agentMessages = [];
  }
  sessions.sort((a, b) => b.updatedAt - a.updatedAt);
  return sessions.map(cloneSession);
}

export async function deleteWorkbookSessions(
  workbookId: string,
  keepSessionId?: string,
): Promise<void> {
  const sessions = await listSessions(workbookId);
  const sessionIdsToDelete = sessions
    .filter((session) => session.id !== keepSessionId)
    .map((session) => session.id);

  if (sessionIdsToDelete.length === 0) {
    return;
  }

  await Promise.all(sessionIdsToDelete.map((sessionId) => deleteSession(sessionId)));
}

export async function createSession(
  workbookId: string,
  name?: string,
): Promise<ChatSession> {
  await deleteWorkbookSessions(workbookId);
  const now = Date.now();
  const session: ChatSession = {
    id: crypto.randomUUID(),
    workbookId,
    name: name ?? "New Chat",
    agentMessages: [],
    createdAt: now,
    updatedAt: now,
  };
  sessionStore.set(session.id, cloneSession(session));
  return cloneSession(session);
}

export async function getSession(
  sessionId: string,
): Promise<ChatSession | undefined> {
  const session = sessionStore.get(sessionId);
  if (session && !session.agentMessages) {
    session.agentMessages = [];
  }
  return session ? cloneSession(session) : undefined;
}

export async function saveSession(
  sessionId: string,
  agentMessages: AgentMessage[],
): Promise<void> {
  console.log(
    "[Storage] saveSession:",
    sessionId,
    "agentMessages:",
    agentMessages.length,
  );
  const session = sessionStore.get(sessionId);
  if (!session) {
    console.error("[Storage] Session not found for save:", sessionId);
    return;
  }
  let name = session.name;
  if (name === "New Chat") {
    const derivedName = deriveSessionName(agentMessages);
    if (derivedName) name = derivedName;
  }
  sessionStore.set(sessionId, {
    ...session,
    agentMessages: [...agentMessages],
    name,
    updatedAt: Date.now(),
  });
  console.log("[Storage] saveSession complete");
}

export async function renameSession(
  sessionId: string,
  name: string,
): Promise<void> {
  const session = sessionStore.get(sessionId);
  if (session) {
    sessionStore.set(sessionId, { ...session, name });
  }
}

export async function deleteSession(sessionId: string): Promise<void> {
  sessionStore.delete(sessionId);
  await deleteVfsFiles(sessionId);
}

export async function getOrCreateCurrentSession(
  workbookId: string,
): Promise<ChatSession> {
  const sessions = await listSessions(workbookId);
  if (sessions.length > 0) {
    await deleteWorkbookSessions(workbookId, sessions[0].id);
    const session = sessions[0];
    if (!session.agentMessages) session.agentMessages = [];
    return session;
  }
  return createSession(workbookId);
}

export async function saveVfsFiles(
  sessionId: string,
  files: { path: string; data: Uint8Array }[],
): Promise<void> {
  console.log("[Storage] saveVfsFiles:", sessionId, "files:", files.length);
  if (files.length === 0) {
    vfsFileStore.delete(sessionId);
    return;
  }

  const storedFiles = new Map<string, Uint8Array>();
  for (const f of files) {
    storedFiles.set(f.path, cloneBytes(f.data));
  }
  vfsFileStore.set(sessionId, storedFiles);
}

export async function loadVfsFiles(
  sessionId: string,
): Promise<{ path: string; data: Uint8Array }[]> {
  const rows = [...(vfsFileStore.get(sessionId)?.entries() ?? [])].map(
    ([path, data]) => ({ path, data: cloneBytes(data) }),
  );
  console.log("[Storage] loadVfsFiles:", sessionId, "files:", rows.length);
  return rows;
}

export async function deleteVfsFiles(sessionId: string): Promise<void> {
  vfsFileStore.delete(sessionId);
}

export async function saveSkillFiles(
  skillName: string,
  files: { path: string; data: Uint8Array }[],
): Promise<void> {
  if (files.length === 0) {
    skillFileStore.delete(skillName);
    return;
  }

  const storedFiles = new Map<string, Uint8Array>();
  for (const f of files) {
    storedFiles.set(f.path, cloneBytes(f.data));
  }
  skillFileStore.set(skillName, storedFiles);
}

export async function loadSkillFiles(
  skillName: string,
): Promise<{ path: string; data: Uint8Array }[]> {
  return [...(skillFileStore.get(skillName)?.entries() ?? [])].map(
    ([path, data]) => ({ path, data: cloneBytes(data) }),
  );
}

export async function loadAllSkillFiles(): Promise<
  { skillName: string; path: string; data: Uint8Array }[]
> {
  const rows: { skillName: string; path: string; data: Uint8Array }[] = [];
  for (const [skillName, files] of skillFileStore.entries()) {
    for (const [path, data] of files.entries()) {
      rows.push({ skillName, path, data: cloneBytes(data) });
    }
  }
  return rows.sort((left, right) => {
    if (left.skillName === right.skillName) {
      return left.path.localeCompare(right.path);
    }
    return left.skillName.localeCompare(right.skillName);
  });
}

export async function deleteSkillFiles(skillName: string): Promise<void> {
  skillFileStore.delete(skillName);
}

export async function listSkillNames(): Promise<string[]> {
  return [...skillFileStore.keys()].sort();
}
