import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";

// Map registry cache
let mapRegistryCache: {
  version: string;
  generatedAt: string;
  totalMaps: number;
  maps: Array<{
    id: string;
    name: string;
    filename: string;
    category: string;
    size: number;
  }>;
} | null = null;

async function loadMapRegistry(retries = 0): Promise<typeof mapRegistryCache> {
  if (mapRegistryCache) return mapRegistryCache;

  try {
    const response = await fetch("/maps/maps.json");
    if (!response.ok) {
      if (retries < 2) {
        // Wait and retry
        await new Promise((r) => setTimeout(r, 500));
        return loadMapRegistry(retries + 1);
      }
      return null;
    }
    mapRegistryCache = (await response.json()) as typeof mapRegistryCache;
    return mapRegistryCache;
  } catch (error) {
    if (retries < 2) {
      await new Promise((r) => setTimeout(r, 500));
      return loadMapRegistry(retries + 1);
    }
    return null;
  }
}

export const listAvailableMapsTool = defineTool({
  name: "list_available_maps",
  label: "List Available Maps",
  description:
    "List all available SVG base maps for map visualizations. " +
    "Returns maps available for offline/airgapped use including: " +
    "world maps, country maps (usa, canada, france, etc.), and US state maps (usa-ca, usa-tx, etc.). " +
    "Use before generate_map_chart to choose the appropriate baseMap.",
  parameters: Type.Object({
    filter: Type.Optional(
      Type.String({
        description:
          "Filter maps by ID or name (case-insensitive). Examples: 'usa', 'virginia', 'world'",
        default: "",
      }),
    ),
    category: Type.Optional(
      Type.Enum(
        {
          all: "all",
          world: "world",
          country: "country",
          usa: "usa",
          continent: "continent",
        },
        {
          description: "Filter by category",
          default: "all",
        },
      ),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're looking for (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const { filter = "", category = "all" } = params;

      const registry = await loadMapRegistry();
      if (!registry) {
        return toolError(
          "Map registry not available. Maps may not be downloaded yet.",
        );
      }

      let maps = registry.maps;

      // Apply category filter
      if (category !== "all") {
        maps = maps.filter((m) => m.category === category);
      }

      // Apply text filter
      if (filter.trim()) {
        const lowerFilter = filter.toLowerCase();
        maps = maps.filter(
          (m) =>
            m.id.toLowerCase().includes(lowerFilter) ||
            m.name.toLowerCase().includes(lowerFilter),
        );
      }

      // Sort by name
      maps.sort((a, b) => a.name.localeCompare(b.name));

      // Group by category for display
      const byCategory = maps.reduce(
        (acc, map) => {
          if (!acc[map.category]) acc[map.category] = [];
          acc[map.category].push({
            id: map.id,
            name: map.name,
            sizeKB: Math.round((map.size / 1024) * 100) / 100,
          });
          return acc;
        },
        {} as Record<
          string,
          Array<{ id: string; name: string; sizeKB: number }>
        >,
      );

      return toolSuccess({
        total: registry.totalMaps,
        filtered: maps.length,
        categories: Object.keys(byCategory).sort(),
        maps: maps.map((m) => ({
          id: m.id,
          name: m.name,
          category: m.category,
          sizeKB: Math.round((m.size / 1024) * 100) / 100,
        })),
        byCategory,
        usage: {
          world: "Use 'world' for global data",
          country: "Use country name like 'usa', 'france', 'germany'",
          usa: "Use state codes like 'usa-va' (Virginia), 'usa-ca' (California)",
          generateMapChart: "Pass the 'id' value as the 'baseMap' parameter",
        },
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error listing maps";
      return toolError(message);
    }
  },
});
