import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";

export const emailReplyTool = defineTool({
  name: "email_reply",
  label: "Reply to Email",
  description:
    "Reply to the currently open email in Outlook, or edit the current compose draft. " +
    "In read mode (viewing an email), can reply to all recipients or just the sender with a new draft. " +
    "In compose mode (editing a draft), updates the current message body instead. " +
    "Supports both text and HTML body formats.",
  parameters: Type.Object({
    replyAll: Type.Optional(
      Type.Boolean({
        description:
          "If true, reply to all recipients (To + Cc). If false, reply only to sender. Default: false",
        default: false,
      }),
    ),
    body: Type.String({
      description:
        "Reply body content. Use HTML formatting with <p> tags, lists, and professional structure for best appearance.",
    }),
    bodyFormat: Type.Optional(
      Type.String({
        enum: ["text", "html"],
        description:
          "Format of the reply body. Use 'html' for professional formatting. Default: 'html'",
        default: "html",
      }),
    ),
    prependQuote: Type.Optional(
      Type.Boolean({
        description:
          "Whether to include the original message as a quote. Default: true",
        default: true,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the reply purpose (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const item = Office.context.mailbox.item;

      if (!item) {
        return toolError("No email item is currently open");
      }

      if (item.itemType !== Office.MailboxEnums.ItemType.Message) {
        return toolError("Current item is not an email message");
      }

      // Determine if we're in read mode or compose mode
      const isComposeMode =
        "to" in item && typeof (item as Office.MessageCompose).to === "object";

      // Handle compose mode: update the current draft body
      if (isComposeMode) {
        const messageCompose = item as Office.MessageCompose;

        try {
          await new Promise<void>((resolve, reject) => {
            if (params.bodyFormat === "html") {
              messageCompose.body.setAsync(
                params.body,
                { coercionType: Office.CoercionType.Html },
                (result) => {
                  if (result.status === Office.AsyncResultStatus.Succeeded) {
                    resolve();
                  } else {
                    reject(
                      new Error(result.error?.message || "Failed to set body"),
                    );
                  }
                },
              );
            } else {
              messageCompose.body.setAsync(
                params.body,
                { coercionType: Office.CoercionType.Text },
                (result) => {
                  if (result.status === Office.AsyncResultStatus.Succeeded) {
                    resolve();
                  } else {
                    reject(
                      new Error(result.error?.message || "Failed to set body"),
                    );
                  }
                },
              );
            }
          });

          return toolSuccess({
            success: true,
            message: "Compose draft updated successfully",
            mode: "compose",
          });
        } catch (e) {
          return toolError(
            `Failed to update compose draft: ${e instanceof Error ? e.message : String(e)}`,
          );
        }
      }

      // Handle read mode: create reply draft
      const messageRead = item as Office.MessageRead;

      // Check if reply methods are available
      const hasReplyMethod = typeof messageRead.displayReplyForm === "function";
      const hasReplyAllMethod =
        typeof messageRead.displayReplyAllForm === "function";

      if (params.replyAll && !hasReplyAllMethod) {
        return toolError(
          "Reply all is not supported in this Outlook context. " +
            "This may be due to permission restrictions or Outlook version limitations.",
        );
      }
      if (!params.replyAll && !hasReplyMethod) {
        return toolError(
          "Reply is not supported in this Outlook context. " +
            "This may be due to permission restrictions or Outlook version limitations.",
        );
      }

      // Build form parameters
      const formParams: {
        body?: string;
        htmlBody?: string;
      } = {};

      if (params.bodyFormat === "html") {
        formParams.htmlBody = params.body;
      } else {
        formParams.body = params.body;
      }

      // Use displayReplyForm or displayReplyAllForm
      try {
        if (params.replyAll) {
          messageRead.displayReplyAllForm(formParams);
        } else {
          messageRead.displayReplyForm(formParams);
        }
      } catch (e) {
        return toolError(
          `Failed to open reply form: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      const successMessage = `Reply${params.replyAll ? "-all" : ""} draft created and opened`;

      return toolSuccess({
        success: true,
        message: successMessage,
        replyAll: params.replyAll || false,
        mode: "read",
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error creating reply";
      return toolError(message);
    }
  },
});
