import type { TokenCredential } from "@azure/core-auth";
import { InteractiveBrowserCredential } from "@azure/identity";
import { captureEntraIdentityFromAccessToken } from "../entra-identity";
import { AIRGAP_CONFIG } from "../airgap-config";
import {
  MAX_CONTEXT_TOKENS,
  MAX_INPUT_TOKENS,
  estimateTokens,
  type TokenCount,
  prepareMessagesForApi,
  truncateToolResult,
} from "../token-manager";
import {
  WorkflowManager,
  createWorkflowManager,
} from "../workflow";

import type {
  AgentEvent,
  AgentEventHandler,
  AgentMessage,
  AgentState,
  AssistantContentBlock,
  AssistantMessage,
  OpenAICompatibleClient,
  ThinkingLevel,
  Tool,
  ToolCallContentBlock,
  ToolResult,
  ToolResultMessage,
  UsageInfo,
  UserMessage,
} from "./types";

export interface AzureAgentConfig {
  endpoint: string;
  deploymentName: string;
  apiMode?: "chat-completions" | "responses";
  apiKey?: string;
  useEntraId?: boolean;
  azureClientId?: string;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  tools: Tool[];
  messages?: AgentMessage[];
  /** Delay between tool execution rounds to avoid rate limits (ms). Default: 5000 for air-gapped */
  rateLimitDelayMs?: number;
  /** Max retries for rate-limited requests. Default: 5 */
  maxRetries?: number;
  /** Max tokens for context window. Default: 32000 for air-gapped (<40k limit) */
  maxContextTokens?: number;
  /** Max tokens generated per assistant response. Default: 8192 */
  maxOutputTokens?: number;
  /** Enable circuit breaker for failing requests. Default: true */
  enableCircuitBreaker?: boolean;
  /** Use workflow manager for rate limiting and request coordination. Default: true */
  useWorkflowManager?: boolean;
  /** Custom workflow manager instance */
  workflowManager?: WorkflowManager;
  /** Workflow rate limit in requests per minute. Default: 20 */
  workflowMaxRequestsPerMinute?: number;
  /** Workflow queue concurrency. Default: 1 */
  workflowMaxConcurrent?: number;
  /** Agent execution behavior model */
  executionModel?: "standard" | "planner";
}

interface ToolCallInProgress {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  accumulatedArgs?: string;
}

interface StreamedToolCallDelta {
  index?: number;
  id?: string;
  function?: { name?: string; arguments?: string };
}

interface LegacyFunctionCallDelta {
  name?: string;
  arguments?: string;
}

interface CircuitBreakerState {
  failures: number;
  lastFailure: number;
  isOpen: boolean;
}

interface RecentToolExecution {
  toolCallId: string;
  completedAt: number;
}

const NON_IDEMPOTENT_TOOL_NAMES = new Set([
  "email_create",
  "email_reply",
  "email_forward",
]);

const NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS = 120000;
const WORKFLOW_PROGRESS_FILE_PATH = "/home/user/uploads/.officeai-workflow-progress.md";

export class AzureAgent {
  private client: OpenAICompatibleClient | null = null;
  private config: AzureAgentConfig;
  private eventHandlers: AgentEventHandler[] = [];
  private abortController: AbortController | null = null;
  private internalState: AgentState;
  private circuitBreaker: CircuitBreakerState;
  private tokenCount: TokenCount;
  private toolsJson: string;
  private workflowManager: WorkflowManager;
  private ownsWorkflowManager = false;
  private recentToolExecutions = new Map<string, RecentToolExecution>();

  get state(): AgentState {
    return { ...this.internalState };
  }

  get currentTokenCount(): TokenCount {
    return { ...this.tokenCount };
  }

  constructor(config: AzureAgentConfig) {
    this.config = {
      rateLimitDelayMs: 5000,
      maxRetries: 5,
      maxContextTokens: MAX_CONTEXT_TOKENS,
      maxOutputTokens: 8192,
      enableCircuitBreaker: true,
      useWorkflowManager: true,
      executionModel: "planner",
      apiMode: "chat-completions",
      ...config,
    };
    this.internalState = {
      messages: config.messages ?? [],
      systemPrompt: config.systemPrompt,
      thinkingLevel: config.thinkingLevel,
      tools: config.tools,
    };
    this.circuitBreaker = { failures: 0, lastFailure: 0, isOpen: false };
    this.toolsJson = JSON.stringify(this.convertToolsToAzureFormat());
    this.tokenCount = { total: 0, system: 0, messages: 0, tools: 0 };

    if (this.config.workflowManager) {
      this.workflowManager = this.config.workflowManager;
      this.ownsWorkflowManager = false;
    } else if (this.config.useWorkflowManager) {
      this.workflowManager = createWorkflowManager("azure", {
        rateLimit: {
          // Keep Azure throughput conservative by default to reduce API pressure.
          maxRequests: this.config.workflowMaxRequestsPerMinute ?? 20,
          windowMs: 60000,
          adaptiveLimiting: true,
        },
        queue: {
          maxConcurrent: this.config.workflowMaxConcurrent ?? 1,
          maxQueueSize: 50,
          defaultTimeoutMs: 60000,
          enableDeduplication: true,
          dedupWindowMs: 5000,
        },
      });
      this.ownsWorkflowManager = true;
    } else {
      this.workflowManager = createWorkflowManager("azure");
      this.workflowManager.updateRateLimitConfig({
        maxRequests: 10000,
        windowMs: 1000,
      });
      this.ownsWorkflowManager = true;
    }

    this.initClient();
    this.updateTokenCount();
  }

  private updateTokenCount(): void {
    const { total, system, messages, tools } = prepareMessagesForApi(
      this.internalState.messages,
      this.internalState.systemPrompt,
      this.toolsJson,
      this.config.maxContextTokens,
    ).tokenCount;
    this.tokenCount = { total, system, messages, tools };
  }

  private checkCircuitBreaker(): boolean {
    if (!this.config.enableCircuitBreaker) return false;

    const now = Date.now();
    const cooldownPeriod = 60000; // 1 minute

    if (this.circuitBreaker.isOpen) {
      if (now - this.circuitBreaker.lastFailure > cooldownPeriod) {
        this.circuitBreaker.isOpen = false;
        this.circuitBreaker.failures = 0;
        return false;
      }
      return true;
    }

    return false;
  }

  private recordFailure(): void {
    if (!this.config.enableCircuitBreaker) return;

    this.circuitBreaker.failures++;
    this.circuitBreaker.lastFailure = Date.now();

    // Open circuit after 5 failures
    if (this.circuitBreaker.failures >= 5) {
      this.circuitBreaker.isOpen = true;
      console.warn(
        "[AzureAgent] Circuit breaker opened due to repeated failures",
      );
    }
  }

  private recordSuccess(): void {
    if (!this.config.enableCircuitBreaker) return;

    this.circuitBreaker.failures = Math.max(
      0,
      this.circuitBreaker.failures - 1,
    );
  }

  private initClient(): void {
    const { endpoint, apiKey, useEntraId, azureClientId, apiMode } = this.config;
    const workflowManager = this.workflowManager;
    const maxRetries = this.config.maxRetries ?? 5;
    const requestTimeoutMs = AIRGAP_CONFIG.timeouts.requestTimeoutMs;

    // Normalize endpoint - users sometimes paste the full API URL or endpoint with /openai path
    // We need to extract just the base endpoint: https://{resource}.openai.azure.com/
    let normalizedEndpoint = endpoint.trim();

    // If the endpoint contains /openai/deployments, extract just the base endpoint
    const openaiPathIndex = normalizedEndpoint.indexOf("/openai/");
    if (openaiPathIndex !== -1) {
      normalizedEndpoint = normalizedEndpoint.substring(0, openaiPathIndex);
    }

    // Remove trailing slashes
    normalizedEndpoint = normalizedEndpoint.replace(/\/+$/, "");

    const fetchWithTimeout = async (
      url: string,
      init: RequestInit,
      signal?: AbortSignal,
    ): Promise<Response> => {
      const timeoutController = new AbortController();
      const onAbort = () => timeoutController.abort();

      if (signal) {
        if (signal.aborted) {
          timeoutController.abort();
        } else {
          signal.addEventListener("abort", onAbort, { once: true });
        }
      }

      const timeoutId = setTimeout(() => {
        timeoutController.abort();
      }, requestTimeoutMs);

      try {
        return await fetch(url, {
          ...init,
          signal: timeoutController.signal,
        });
      } finally {
        clearTimeout(timeoutId);
        if (signal) {
          signal.removeEventListener("abort", onAbort);
        }
      }
    };

    // Create a client that makes direct fetch calls to Azure OpenAI API
    this.client = {
      streamChatCompletions: async function* (
        deploymentName: string,
        messages: unknown[],
        options?: Record<string, unknown>,
        requestOptions?: { abortSignal?: AbortSignal },
      ): AsyncIterableIterator<{
        choices?: Array<{
          delta?: {
            content?: string;
            reasoning_content?: string; // For models like Kimi-K2.5
            tool_calls?: Array<{
              id?: string;
              function?: { name?: string; arguments?: string };
            }>;
          };
          finish_reason?: string | null;
        }>;
        usage?: {
          prompt_tokens?: number;
          completion_tokens?: number;
          total_tokens?: number;
        };
      }> {
        const useResponsesApi = apiMode === "responses";
        const url = useResponsesApi
          ? `${normalizedEndpoint}/openai/responses?api-version=2025-04-01-preview`
          : `${normalizedEndpoint}/openai/deployments/${deploymentName}/chat/completions?api-version=2024-08-01-preview`;

        const headers: Record<string, string> = {
          "Content-Type": "application/json",
        };

        let token: string | undefined;

        if (useEntraId) {
          if (!azureClientId?.trim()) {
            throw new Error(
              "Azure Entra Client ID is required when useEntraId is enabled",
            );
          }

          const redirectUri =
            typeof window !== "undefined"
              ? `${window.location.origin}/taskpane.html`
              : undefined;

          const credential = new InteractiveBrowserCredential({
            tenantId: "common",
            clientId: azureClientId,
            redirectUri,
          });
          const response = await credential.getToken(
            "https://cognitiveservices.azure.com/.default",
          );
          token = response.token;
          captureEntraIdentityFromAccessToken(token);
          headers.Authorization = `Bearer ${token}`;
        } else if (apiKey) {
          headers["api-key"] = apiKey;
        } else {
          throw new Error("Either apiKey or useEntraId must be provided");
        }

        let currentOptions: Record<string, unknown> = {
          ...(options ?? {}),
        };

        const normalizeStreamChunk = (chunk: unknown) => {
          if (!useResponsesApi) {
            return chunk as {
              choices?: Array<{
                delta?: {
                  content?: string;
                  reasoning_content?: string;
                  tool_calls?: Array<{
                    id?: string;
                    function?: { name?: string; arguments?: string };
                  }>;
                };
                finish_reason?: string | null;
              }>;
              usage?: {
                prompt_tokens?: number;
                completion_tokens?: number;
                total_tokens?: number;
              };
            };
          }

          const event = chunk as Record<string, unknown>;
          const eventType =
            typeof event.type === "string" ? event.type : undefined;

          const eventError = event.error as Record<string, unknown> | undefined;
          if (eventError) {
            const message =
              (typeof eventError.message === "string" && eventError.message) ||
              "Unknown Azure Responses stream error";
            throw new Error(`Azure Responses stream error: ${message}`);
          }

          if (!eventType) {
            return null;
          }

          if (eventType === "response.output_text.delta") {
            const delta = typeof event.delta === "string" ? event.delta : "";
            if (!delta) return null;
            return {
              choices: [{ delta: { content: delta } }],
            };
          }

          if (eventType.includes("reasoning") && typeof event.delta === "string") {
            return {
              choices: [{ delta: { reasoning_content: event.delta } }],
            };
          }

          if (eventType === "response.output_item.added") {
            const item = event.item as Record<string, unknown> | undefined;
            if (item?.type !== "function_call") {
              return null;
            }
            return {
              choices: [
                {
                  delta: {
                    tool_calls: [
                      {
                        index:
                          typeof event.output_index === "number"
                            ? event.output_index
                            : 0,
                        id:
                          (typeof item.call_id === "string" && item.call_id) ||
                          (typeof item.id === "string" ? item.id : undefined),
                        function: {
                          name:
                            typeof item.name === "string" ? item.name : undefined,
                        },
                      },
                    ],
                  },
                },
              ],
            };
          }

          if (eventType === "response.function_call_arguments.delta") {
            const delta = typeof event.delta === "string" ? event.delta : "";
            if (!delta) return null;
            return {
              choices: [
                {
                  delta: {
                    tool_calls: [
                      {
                        index:
                          typeof event.output_index === "number"
                            ? event.output_index
                            : 0,
                        id:
                          typeof event.call_id === "string"
                            ? event.call_id
                            : undefined,
                        function: {
                          name:
                            typeof event.name === "string" ? event.name : undefined,
                          arguments: delta,
                        },
                      },
                    ],
                  },
                },
              ],
            };
          }

          if (eventType === "response.output_text.done") {
            // We already stream text via response.output_text.delta.
            // Emitting "done" text again can duplicate the final answer.
            return null;
          }

          if (eventType === "response.function_call_arguments.done") {
            const args = typeof event.arguments === "string" ? event.arguments : "";
            return {
              choices: [
                {
                  delta: {
                    tool_calls: [
                      {
                        index:
                          typeof event.output_index === "number"
                            ? event.output_index
                            : 0,
                        id:
                          typeof event.call_id === "string"
                            ? event.call_id
                            : undefined,
                        function: {
                          name:
                            typeof event.name === "string" ? event.name : undefined,
                          arguments: args,
                        },
                      },
                    ],
                  },
                },
              ],
            };
          }

          if (
            eventType === "response.completed" ||
            eventType === "response.done" ||
            eventType === "response.failed"
          ) {
            const response = event.response as Record<string, unknown> | undefined;
            const responseError = response?.error as Record<string, unknown> | undefined;
            if (eventType === "response.failed" || responseError) {
              const message =
                (typeof responseError?.message === "string" &&
                  responseError.message) ||
                "Azure Responses request failed";
              throw new Error(`Azure Responses request failed: ${message}`);
            }
            const usage = response?.usage as Record<string, unknown> | undefined;
            const outputItems = Array.isArray(response?.output)
              ? (response?.output as Array<Record<string, unknown>>)
              : [];
            const hasFunctionCall = outputItems.some(
              (item) => item?.type === "function_call",
            );

            return {
              choices: [
                {
                  finish_reason: hasFunctionCall ? "tool_calls" : "stop",
                },
              ],
              usage: {
                prompt_tokens:
                  typeof usage?.input_tokens === "number"
                    ? usage.input_tokens
                    : 0,
                completion_tokens:
                  typeof usage?.output_tokens === "number"
                    ? usage.output_tokens
                    : 0,
                total_tokens:
                  typeof usage?.total_tokens === "number"
                    ? usage.total_tokens
                    : undefined,
              },
            };
          }

          return null;
        };

        // Retry logic with exponential backoff + jitter for 429 rate limit errors
        let lastError: Error | undefined;
        const maxAttempts = maxRetries;

        for (let attempt = 0; attempt < maxAttempts; attempt++) {
          let sawMeaningfulResponsesEvent = false;
          let keepaliveCount = 0;
          const streamStartTime = Date.now();

          const updateResponsesStreamHealth = (parsed: unknown): void => {
            if (!useResponsesApi) return;

            const event = parsed as Record<string, unknown>;
            const eventType =
              typeof event.type === "string" ? event.type : undefined;
            if (!eventType) return;

            if (eventType === "keepalive") {
              keepaliveCount += 1;

              // If we only receive keepalives for too long, surface a clear error.
              const elapsedMs = Date.now() - streamStartTime;
              if (
                !sawMeaningfulResponsesEvent &&
                keepaliveCount >= 10 &&
                elapsedMs >= 30000
              ) {
                throw new Error(
                  "Azure Responses stream timed out with keepalive-only events and no model output. Please retry or switch Azure API mode.",
                );
              }
              return;
            }

            // Not every non-keepalive event is useful for UI output.
            if (eventType === "response.created" || eventType === "response.in_progress") {
              return;
            }

            sawMeaningfulResponsesEvent = true;
          };

          const requestOptionsForApi = { ...(currentOptions ?? {}) };
          if (
            useResponsesApi &&
            Object.prototype.hasOwnProperty.call(
              requestOptionsForApi,
              "max_completion_tokens",
            ) &&
            !Object.prototype.hasOwnProperty.call(
              requestOptionsForApi,
              "max_output_tokens",
            )
          ) {
            requestOptionsForApi.max_output_tokens =
              requestOptionsForApi.max_completion_tokens;
            delete requestOptionsForApi.max_completion_tokens;
          }

          const body = useResponsesApi
            ? JSON.stringify({
                model: deploymentName,
                input: messages,
                stream: true,
                ...requestOptionsForApi,
              })
            : JSON.stringify({
                messages,
                stream: true,
                ...requestOptionsForApi,
              });

          if (attempt === 0) {
            const rateLimitResult = await workflowManager.acquireRateLimitToken(
              30000,
            );
            if (!rateLimitResult.allowed) {
              throw new Error(
                `Rate limit exceeded. Retry after ${rateLimitResult.retryAfterMs}ms`,
              );
            }
          }

          if (attempt > 0) {
            // Exponential backoff with jitter for air-gapped environments
            // Base delay: 5s, doubling each attempt, max 60s, with ±20% jitter
            const baseDelay = Math.min(5000 * 2 ** (attempt - 1), 60000);
            const jitter = baseDelay * 0.2 * (Math.random() * 2 - 1);
            const delay = Math.max(1000, Math.floor(baseDelay + jitter));

            console.log(
              `[AzureAgent] Rate limited, retrying in ${delay}ms (attempt ${attempt + 1}/${maxAttempts})...`,
            );
            await new Promise((resolve) => setTimeout(resolve, delay));
          }

          const response = await fetchWithTimeout(
            url,
            {
            method: "POST",
            headers,
            body,
            },
            requestOptions?.abortSignal,
          );

          if (response.status === 400) {
            const errorText = await response.text();
            const normalizedError = errorText.toLowerCase();
            workflowManager.reportRecoverableHttpError(400);

            if (attempt < maxAttempts - 1) {
              let adjusted = false;

              // Some Azure model/API-version combinations only accept max_tokens.
              if (
                Object.prototype.hasOwnProperty.call(
                  currentOptions,
                  "max_completion_tokens",
                ) &&
                (normalizedError.includes("max_completion_tokens") ||
                  normalizedError.includes("unknown parameter") ||
                  normalizedError.includes("unrecognized"))
              ) {
                currentOptions.max_tokens = currentOptions.max_completion_tokens;
                delete currentOptions.max_completion_tokens;
                adjusted = true;
                console.warn(
                  "[AzureAgent] Retrying with max_tokens fallback (removed max_completion_tokens)",
                );
              }

              // Older Azure variants may reject stream_options.
              if (
                Object.prototype.hasOwnProperty.call(
                  currentOptions,
                  "stream_options",
                ) &&
                normalizedError.includes("stream_options")
              ) {
                delete currentOptions.stream_options;
                adjusted = true;
                console.warn(
                  "[AzureAgent] Retrying without stream_options due to 400 response",
                );
              }

              // Some models (notably reasoning/Responses deployments) reject temperature.
              if (
                Object.prototype.hasOwnProperty.call(currentOptions, "temperature") &&
                normalizedError.includes("temperature") &&
                (normalizedError.includes("not supported") ||
                  normalizedError.includes("unsupported parameter"))
              ) {
                delete currentOptions.temperature;
                adjusted = true;
                console.warn(
                  "[AzureAgent] Retrying without temperature due to unsupported-parameter response",
                );
              }

              // If function calling is unsupported for a deployment, fall back to plain chat.
              if (
                (Object.prototype.hasOwnProperty.call(currentOptions, "tools") ||
                  Object.prototype.hasOwnProperty.call(
                    currentOptions,
                    "tool_choice",
                  )) &&
                (normalizedError.includes("tool") ||
                  normalizedError.includes("function") ||
                  normalizedError.includes("not supported"))
              ) {
                delete currentOptions.tools;
                delete currentOptions.tool_choice;
                adjusted = true;
                console.warn(
                  "[AzureAgent] Retrying without tools/tool_choice due to 400 response",
                );
              }

              if (adjusted) {
                lastError = new Error(errorText);
                continue;
              }
            }

            console.error("[AzureAgent] 400 Bad Request details:", errorText);
            console.error(
              "[AzureAgent] 400 hint: verify deployment model supports tools and that request history has no orphan tool messages.",
            );
            throw new Error(`Azure OpenAI API error (400): ${errorText}`);
          }

          if (response.status === 429) {
            const retryAfter = response.headers.get("retry-after");
            const retryAfterMs = retryAfter
              ? Number.parseInt(retryAfter, 10) * 1000
              : undefined;
            workflowManager.reportRecoverableHttpError(429, retryAfterMs);

            if (retryAfter) {
              const delayMs = Number.parseInt(retryAfter, 10) * 1000;
              console.log(
                `[AzureAgent] Server requested Retry-After: ${retryAfter}s`,
              );
              await new Promise((resolve) => setTimeout(resolve, delayMs));
              continue;
            }
            lastError = new Error(await response.text());
            continue; // Will retry with exponential backoff
          }

          // Handle server errors (5xx) with retry
          if (
            response.status >= 500 &&
            response.status < 600 &&
            attempt < maxAttempts - 1
          ) {
            console.warn(
              `[AzureAgent] Server error ${response.status}, will retry...`,
            );
            lastError = new Error(`Server error: ${response.status}`);
            continue;
          }

          // Handle network timeouts
          if (response.status === 408 || response.status === 524) {
            console.warn("[AzureAgent] Request timeout, will retry...");
            lastError = new Error(`Timeout: ${response.status}`);
            continue;
          }

          if (!response.ok) {
            const errorText = await response.text();
            throw new Error(
              `Azure OpenAI API error (${response.status}): ${errorText}`,
            );
          }

          if (!response.body) {
            throw new Error("No response body from Azure OpenAI API");
          }

          workflowManager.reportSuccess();

          // Success - stream the response
          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = "";

          try {
            while (true) {
              if (requestOptions?.abortSignal?.aborted) {
                break;
              }

              const { done, value } = await reader.read();
              if (done) break;

              buffer += decoder.decode(value, { stream: true });

              const lines = buffer.split("\n");
              buffer = lines.pop() ?? "";

              for (const line of lines) {
                const trimmed = line.trim();
                if (!trimmed || !trimmed.startsWith("data: ")) continue;

                const data = trimmed.slice(6);

                if (data === "[DONE]") {
                  return;
                }

                try {
                  const parsed = JSON.parse(data);
                  updateResponsesStreamHealth(parsed);
                  const normalized = normalizeStreamChunk(parsed);
                  if (normalized) {
                    yield normalized;
                  }
                } catch (error) {
                  if (error instanceof SyntaxError) {
                    continue;
                  }
                  throw error;
                }
              }
            }

            // Process remaining buffer
            if (buffer.trim()) {
              const trimmed = buffer.trim();
              if (trimmed.startsWith("data: ")) {
                const data = trimmed.slice(6);
                if (data && data !== "[DONE]") {
                  try {
                    const parsed = JSON.parse(data);
                    updateResponsesStreamHealth(parsed);
                    const normalized = normalizeStreamChunk(parsed);
                    if (normalized) {
                      yield normalized;
                    }
                  } catch (error) {
                    if (error instanceof SyntaxError) {
                      // Invalid JSON
                    } else {
                      throw error;
                    }
                  }
                }
              }
            }
          } finally {
            reader.releaseLock();
          }

          return; // Success, exit retry loop
        }

        throw (
          lastError ?? new Error("Max retries exceeded for Azure OpenAI API")
        );
      },
    };
  }

  private async *streamResponse(
    body: ReadableStream<Uint8Array>,
    abortSignal?: AbortSignal,
  ): AsyncIterableIterator<{
    choices?: Array<{
      delta?: {
        content?: string;
        reasoning_content?: string; // For models like Kimi-K2.5
        tool_calls?: Array<{
          id?: string;
          function?: { name?: string; arguments?: string };
        }>;
      };
      finish_reason?: string | null;
    }>;
    usage?: {
      prompt_tokens?: number;
      completion_tokens?: number;
      total_tokens?: number;
    };
  }> {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    try {
      while (true) {
        if (abortSignal?.aborted) {
          break;
        }

        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || !trimmed.startsWith("data: ")) continue;

          const data = trimmed.slice(6);

          if (data === "[DONE]") {
            return;
          }

          try {
            const parsed = JSON.parse(data);
            yield parsed;
          } catch {
            // Invalid JSON, skip this chunk
          }
        }
      }

      // Process remaining buffer
      if (buffer.trim()) {
        const trimmed = buffer.trim();
        if (trimmed.startsWith("data: ")) {
          const data = trimmed.slice(6);
          if (data && data !== "[DONE]") {
            try {
              const parsed = JSON.parse(data);
              yield parsed;
            } catch {
              // Invalid JSON
            }
          }
        }
      }
    } finally {
      reader.releaseLock();
    }
  }

  subscribe(handler: AgentEventHandler): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emit(event: AgentEvent): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error("[AzureAgent] Event handler error:", err);
      }
    }
  }

  private createUserMessage(content: string): UserMessage {
    return {
      role: "user",
      content,
      timestamp: Date.now(),
    };
  }

  private createAssistantMessage(
    content: AssistantContentBlock[],
    stopReason: AssistantMessage["stopReason"] = "complete",
    usage?: UsageInfo,
  ): AssistantMessage {
    return {
      role: "assistant",
      content,
      timestamp: Date.now(),
      stopReason,
      usage,
    };
  }

  private createToolResultMessage(
    toolCallId: string,
    content: ToolResult,
    isError: boolean,
  ): ToolResultMessage {
    return {
      role: "tool",
      toolCallId,
      content: content.content,
      isError,
      timestamp: Date.now(),
    };
  }

  private stringifyToolArguments(args: unknown): string {
    try {
      return JSON.stringify(args ?? {});
    } catch {
      return "{}";
    }
  }

  private createToolExecutionFingerprint(
    toolName: string,
    args: Record<string, unknown>,
  ): string {
    const normalizedArgs = Object.keys(args)
      .sort()
      .reduce<Record<string, unknown>>((acc, key) => {
        acc[key] = args[key];
        return acc;
      }, {});

    return `${toolName}:${JSON.stringify(normalizedArgs)}`;
  }

  private pruneRecentToolExecutions(now = Date.now()): void {
    for (const [fingerprint, execution] of this.recentToolExecutions) {
      if (now - execution.completedAt > NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS) {
        this.recentToolExecutions.delete(fingerprint);
      }
    }
  }

  private isNonIdempotentTool(toolName: string): boolean {
    return NON_IDEMPOTENT_TOOL_NAMES.has(toolName);
  }

  private normalizeTextContent(value: unknown): string {
    if (typeof value !== "string") {
      return "";
    }
    return value.trim();
  }

  private getLastUserMessageText(): string {
    for (let i = this.internalState.messages.length - 1; i >= 0; i--) {
      const msg = this.internalState.messages[i];
      if (msg.role === "user") {
        return this.normalizeTextContent((msg as UserMessage).content).toLowerCase();
      }
    }
    return "";
  }

  private isGreetingOrSmallTalk(text: string): boolean {
    if (!text) {
      return false;
    }

    const compact = text.trim().toLowerCase();
    if (!compact) {
      return false;
    }

    if (compact.length > 64) {
      return false;
    }

    return /^(hi|hello|hey|yo|sup|howdy|good\s+(morning|afternoon|evening)|how are you|thanks|thank you|thx|nice to meet you)([!.?,\s].*)?$/.test(
      compact,
    );
  }

  private shouldForcePlannerExecution(lastUserText: string): boolean {
    if (!this.isPlannerMode()) {
      return false;
    }
    return !this.isGreetingOrSmallTalk(lastUserText);
  }

  private hasToolNamed(toolName: string): boolean {
    return this.internalState.tools.some((tool) => tool.name === toolName);
  }

  private shouldUseComplexWorkflowMode(lastUserText: string): boolean {
    if (!this.shouldForcePlannerExecution(lastUserText)) {
      return false;
    }

    const complexSignals = [
      /\bplan\b/i,
      /\bworkflow\b/i,
      /\bcomplex\b/i,
      /\bmulti[-\s]?step\b/i,
      /\bend[-\s]?to[-\s]?end\b/i,
      /\bimplement\b/i,
      /\bexecute\b/i,
      /\bvalidate\b/i,
      /\bquality\b/i,
      /\bcheck\b/i,
      /\bverify\b/i,
      /\baudit\b/i,
    ];

    return (
      lastUserText.length > 220 ||
      complexSignals.some((pattern) => pattern.test(lastUserText))
    );
  }

  private shouldNudgeForActionWithoutTools(
    hasToolCalls: boolean,
    contentBlocks: AssistantContentBlock[],
  ): boolean {
    if (hasToolCalls || this.internalState.tools.length === 0) {
      return false;
    }

    const lastUserText = this.getLastUserMessageText();
    if (!lastUserText) {
      return false;
    }

    const shortAffirmativeReplies = new Set([
      "all",
      "yes",
      "y",
      "ok",
      "okay",
      "sure",
      "go ahead",
      "do it",
      "please do",
      "continue",
      "proceed",
      "a",
      "b",
      "c",
      "d",
      "a+d",
    ]);

    const isShortAffirmative =
      shortAffirmativeReplies.has(lastUserText) ||
      (lastUserText.length <= 24 && /^(yes|all|ok|sure|go ahead|do it|proceed)\b/.test(lastUserText));

    if (!isShortAffirmative) {
      return false;
    }

    const combinedText = contentBlocks
      .filter((b): b is Extract<AssistantContentBlock, { type: "text" }> => b.type === "text")
      .map((b) => b.text)
      .join(" ")
      .toLowerCase();

    return combinedText.length > 0;
  }

  private isPlannerMode(): boolean {
    return this.config.executionModel === "planner";
  }

  private buildPlannerExecutionPrompt(
    hasExecutedToolsInRun: boolean,
    options?: {
      complexMode?: boolean;
      forceCompaction?: boolean;
      executedToolCalls?: number;
    },
  ): string {
    const complexMode = options?.complexMode ?? false;
    const forceCompaction = options?.forceCompaction ?? false;
    const executedToolCalls = options?.executedToolCalls ?? 0;

    if (complexMode) {
      const canUseVfsProgressFile =
        this.hasToolNamed("write_file") && this.hasToolNamed("read");
      const progressFileInstructions = canUseVfsProgressFile
        ? `Context freshness + compaction (required): Use ${WORKFLOW_PROGRESS_FILE_PATH} as your run log in markdown.\n- During PLAN phase: create/update this markdown with sections: Objective, Assumptions, Plan Checklist, Evidence Log, Open Risks, Quality Checks.\n- During EXECUTION phase: update checklist and evidence after meaningful progress.\n- During QUALITY CHECK phase: write pass/fail checks and remediation if needed.\n- Only rewrite this file when content materially changes; avoid redundant read/write loops.\n- When context grows, compact by writing a concise snapshot to this file and continue from the snapshot instead of repeating verbose history.`
        : "Context freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history.";

      const compactionInstruction = forceCompaction
        ? "Compaction checkpoint: perform a compaction update now before further execution."
        : "";

      if (!hasExecutedToolsInRun) {
        return `Planner mode (complex workload): follow three phases and execute now.\nPhase 1 - PLAN: create a short actionable checklist tied to the user request.\nPhase 2 - EXECUTION: immediately start executing checklist items with tools.\nPhase 3 - QUALITY CHECK: before final answer, verify outcomes against requirements and run at least one concrete validation/read-back step.\n${progressFileInstructions}\n${compactionInstruction}\nDo not stop at planning text, do not ask for confirmation, and do not ask the user to paste prior planner output.`;
      }

      return `Planner mode (complex workload): continue execution until complete, then run QUALITY CHECK before final answer.\nExecution status: ${executedToolCalls} tool call(s) executed in this run.\nIf prior planner state is missing, reconstruct remaining steps from tool results, conversation history, and workspace state.\nRequired QUALITY CHECK before final answer:\n- Confirm each user requirement is satisfied.\n- Run concrete verification using available tools (for example read-back, search, or inspection).\n- Report residual risk or gaps explicitly.\n${progressFileInstructions}\n${compactionInstruction}\nDo not ask the user for old checklists/planner output. Only provide a final answer when execution and quality checks are complete.`;
    }

    if (!hasExecutedToolsInRun) {
      return "Planner mode: create a short execution plan from the current request and available conversation context, then immediately call the required tools now. If any prior checklist is missing, infer the next best steps from the repo/files and continue execution. Do not stop at planning text, do not ask for confirmation, and do not ask the user to paste prior planner output.";
    }
    return "Planner mode: continue executing remaining tool steps until complete. If prior planner state is missing, reconstruct the remaining steps from tool results, conversation history, and current workspace state, then keep executing. Do not ask the user for the old checklist or planner output. Only provide a final answer when tool execution is done.";
  }

  private upsertStreamedToolCall(
    toolCallsByIndex: Map<number, ToolCallInProgress>,
    tc: StreamedToolCallDelta,
  ): void {
    const index = tc.index ?? 0;
    const existing = toolCallsByIndex.get(index) ?? {
      id: "",
      name: "",
      arguments: {},
      accumulatedArgs: "",
    };

    if (tc.id) {
      existing.id = tc.id;
    }
    if (tc.function?.name) {
      existing.name = tc.function.name;
    }
    if (tc.function?.arguments) {
      existing.accumulatedArgs = (existing.accumulatedArgs ?? "") + tc.function.arguments;
    }

    toolCallsByIndex.set(index, existing);
  }

  private finalizeToolCalls(
    toolCallsByIndex: Map<number, ToolCallInProgress>,
  ): ToolCallInProgress[] {
    return [...toolCallsByIndex.entries()]
      .sort(([a], [b]) => a - b)
      .map(([, tc], idx) => ({
        ...tc,
        id: tc.id || `azure_tool_call_${Date.now()}_${idx}`,
      }))
      .filter((tc) => this.normalizeTextContent(tc.name).length > 0);
  }

  private convertMessagesToAzureFormat(messages: AgentMessage[]): unknown[] {
    const azureMessages: unknown[] = [];
    const announcedToolCalls = new Set<string>();
    let skippedOrphanToolMessages = 0;
    let skippedInvalidAssistantMessages = 0;

    // Add system prompt
    const systemPrompt = this.normalizeTextContent(this.internalState.systemPrompt);
    if (systemPrompt) {
      azureMessages.push({
        role: "system",
        content: systemPrompt,
      });
    }

    for (const msg of messages) {
      if (msg.role === "user") {
        const content = this.normalizeTextContent((msg as UserMessage).content);
        if (!content) {
          continue;
        }

        azureMessages.push({
          role: "user",
          content,
        });
      } else if (msg.role === "assistant") {
        const assistantMsg = msg as AssistantMessage;

        // Separate text content from tool calls
        const textParts: string[] = [];
        const toolCalls: Array<{
          id: string;
          type: string;
          function: { name: string; arguments: string };
        }> = [];

        for (const block of assistantMsg.content) {
          if (block.type === "text") {
            const normalized = this.normalizeTextContent(block.text);
            if (normalized) {
              textParts.push(normalized);
            }
          } else if (block.type === "thinking") {
            const normalized = this.normalizeTextContent(block.thinking);
            if (normalized) {
              textParts.push(`[Thinking: ${normalized}]`);
            }
          } else if (block.type === "tool_call") {
            const id = this.normalizeTextContent(block.id);
            const name = this.normalizeTextContent(block.name);
            if (!id || !name) {
              continue;
            }

            announcedToolCalls.add(id);
            toolCalls.push({
              id,
              type: "function",
              function: {
                name,
                arguments: this.stringifyToolArguments(block.arguments),
              },
            });
          }
        }

        // Build assistant message
        const azureMsg: Record<string, unknown> = {
          role: "assistant",
        };

        // Only add content if there's text (Azure rejects content: null)
        const contentText = textParts.join("\n");
        if (contentText) {
          azureMsg.content = contentText;
        }

        // Add tool_calls if present
        if (toolCalls.length > 0) {
          azureMsg.tool_calls = toolCalls;
        }

        // Azure rejects assistant messages with neither content nor tool_calls.
        if (!("content" in azureMsg) && !("tool_calls" in azureMsg)) {
          skippedInvalidAssistantMessages++;
          continue;
        }

        azureMessages.push(azureMsg);
      } else if (msg.role === "tool") {
        const toolMsg = msg as ToolResultMessage;
        const toolCallId = this.normalizeTextContent(toolMsg.toolCallId);

        // Prevent orphan tool results from being sent. These can happen after history truncation.
        if (!toolCallId || !announcedToolCalls.has(toolCallId)) {
          skippedOrphanToolMessages++;
          continue;
        }

        // Azure API expects tool messages with role="tool" and tool_call_id
        // Join all text content, skip image content for Azure API messages
        const text = toolMsg.content
          .filter((c) => c.type === "text")
          .map((c) => (c as { type: "text"; text: string }).text)
          .map((t) => this.normalizeTextContent(t))
          .filter(Boolean)
          .join("\n");

        azureMessages.push({
          role: "tool",
          tool_call_id: toolCallId,
          content: text || "[Tool result with images]",
        });
      }
    }

    if (skippedOrphanToolMessages > 0) {
      console.warn(
        `[AzureAgent] Skipped ${skippedOrphanToolMessages} orphan tool message(s) to avoid Azure 400 errors`,
      );
    }
    if (skippedInvalidAssistantMessages > 0) {
      console.warn(
        `[AzureAgent] Skipped ${skippedInvalidAssistantMessages} invalid assistant message(s) with no content/tool_calls`,
      );
    }

    // Debug: log the generated messages
    console.log(
      "[AzureAgent] Converted messages for Azure:",
      JSON.stringify(azureMessages, null, 2),
    );

    return azureMessages;
  }

  private convertMessagesToResponsesFormat(messages: AgentMessage[]): unknown[] {
    const responseInput: unknown[] = [];
    const announcedToolCalls = new Set<string>();

    const systemPrompt = this.normalizeTextContent(this.internalState.systemPrompt);
    if (systemPrompt) {
      responseInput.push({
        role: "system",
        content: [{ type: "input_text", text: systemPrompt }],
      });
    }

    for (const msg of messages) {
      if (msg.role === "user") {
        const content = this.normalizeTextContent((msg as UserMessage).content);
        if (!content) continue;

        responseInput.push({
          role: "user",
          content: [{ type: "input_text", text: content }],
        });
        continue;
      }

      if (msg.role === "assistant") {
        const assistantMsg = msg as AssistantMessage;
        const textParts: string[] = [];

        for (const block of assistantMsg.content) {
          if (block.type === "text") {
            const normalized = this.normalizeTextContent(block.text);
            if (normalized) {
              textParts.push(normalized);
            }
          }

          if (block.type === "thinking") {
            const normalized = this.normalizeTextContent(block.thinking);
            if (normalized) {
              textParts.push(`[Thinking: ${normalized}]`);
            }
          }

          if (block.type === "tool_call") {
            const id = this.normalizeTextContent(block.id);
            const name = this.normalizeTextContent(block.name);
            if (!id || !name) {
              continue;
            }
            announcedToolCalls.add(id);
            responseInput.push({
              type: "function_call",
              call_id: id,
              name,
              arguments: this.stringifyToolArguments(block.arguments),
            });
          }
        }

        const assistantText = textParts.join("\n");
        if (assistantText) {
          responseInput.push({
            role: "assistant",
            content: [{ type: "output_text", text: assistantText }],
          });
        }
        continue;
      }

      if (msg.role === "tool") {
        const toolMsg = msg as ToolResultMessage;
        const toolCallId = this.normalizeTextContent(toolMsg.toolCallId);
        if (!toolCallId || !announcedToolCalls.has(toolCallId)) {
          continue;
        }

        const text = toolMsg.content
          .filter((c) => c.type === "text")
          .map((c) => (c as { type: "text"; text: string }).text)
          .map((t) => this.normalizeTextContent(t))
          .filter(Boolean)
          .join("\n");

        responseInput.push({
          type: "function_call_output",
          call_id: toolCallId,
          output: text || "[Tool result with images]",
        });
      }
    }

    console.log(
      "[AzureAgent] Converted messages for Azure Responses:",
      JSON.stringify(responseInput, null, 2),
    );

    return responseInput;
  }

  private convertToolsToAzureFormat(): unknown[] {
    return this.internalState.tools.map((tool) => ({
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      },
    }));
  }

  private convertToolsToResponsesFormat(): unknown[] {
    return this.internalState.tools.map((tool) => ({
      type: "function",
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
    }));
  }

  async prompt(content: string): Promise<void> {
    if (!this.client) {
      throw new Error("Agent client not initialized");
    }

    const inputTokens = estimateTokens(content);
    if (inputTokens > MAX_INPUT_TOKENS) {
      throw new Error(
        `Input too large (${inputTokens} estimated tokens). Maximum allowed is ${MAX_INPUT_TOKENS}.`,
      );
    }

    this.abortController = new AbortController();
    const signal = this.abortController.signal;
    this.recentToolExecutions.clear();

    try {
      // Add user message
      const userMessage = this.createUserMessage(content);
      this.internalState.messages.push(userMessage);

      // Start streaming
      await this.runAgentLoop(signal);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error";
      console.error("[AzureAgent] Prompt error:", error);

      // Emit error message
      const errorAssistant: AssistantMessage = {
        role: "assistant",
        content: [{ type: "text", text: `Error: ${errorMessage}` }],
        timestamp: Date.now(),
        stopReason: "error",
        errorMessage: errorMessage,
      };

      this.emit({ type: "message_start", message: errorAssistant });
      this.emit({ type: "message_end", message: errorAssistant });
      this.emit({ type: "agent_end" });
    } finally {
      this.abortController = null;
    }
  }

  private async runAgentLoop(signal: AbortSignal): Promise<void> {
    if (!this.client) return;

    // Check circuit breaker before running
    if (this.checkCircuitBreaker()) {
      throw new Error(
        "Circuit breaker is open due to repeated failures. Please wait a minute before retrying.",
      );
    }

    const maxIterations = 50;
    let iterations = 0;
    let actionNudgeUsed = false;
    let plannerNudgesUsed = 0;
    let hasExecutedToolsInRun = false;
    let executedToolCallsInRun = 0;
    let grantedPostToolFinalizationPass = false;
    let plannerDirectiveInjected = false;
    const lastUserText = this.getLastUserMessageText();
    const shouldUsePlannerExecution = this.shouldForcePlannerExecution(lastUserText);
    const useComplexWorkflowMode = this.shouldUseComplexWorkflowMode(lastUserText);

    while (iterations < maxIterations && !signal.aborted) {
      iterations++;

      // Prepare messages with token limit enforcement
      const maxTokens = this.config.maxContextTokens ?? MAX_CONTEXT_TOKENS;

      console.log("[AzureAgent] === Preparing messages for iteration", iterations, "===");
      console.log("[AzureAgent] Internal messages count:", this.internalState.messages.length);
      console.log("[AzureAgent] Message roles:", this.internalState.messages.map(m => m.role));

      const { preparedMessages, tokenCount, wasTruncated } =
        prepareMessagesForApi(
          this.internalState.messages,
          this.internalState.systemPrompt,
          this.toolsJson,
          maxTokens,
        );

      this.tokenCount = tokenCount;

      console.log("[AzureAgent] Prepared messages count:", preparedMessages.length);
      console.log("[AzureAgent] Prepared message roles:", preparedMessages.map(m => m.role));

      if (wasTruncated) {
        console.log(
          `[AzureAgent] Message history truncated for token limit (${tokenCount.total}/${maxTokens})`,
        );
        this.emit({
          type: "message_update",
          message: {
            role: "assistant",
            content: [
              {
                type: "text",
                text: "[Context summary: Earlier messages compressed to stay within token limits.]",
              },
            ],
            timestamp: Date.now(),
          },
        });
      }

      try {
        const shouldForceCompaction =
          useComplexWorkflowMode &&
          hasExecutedToolsInRun &&
          executedToolCallsInRun > 0 &&
          executedToolCallsInRun % 4 === 0;

        // Inject the synthetic planner directive only once per run.
        // Re-injecting it every loop can trap the model in repeated
        // meta-compliance actions (for example, rewriting progress logs).
        const plannerInstruction = shouldUsePlannerExecution && !plannerDirectiveInjected
          ? this.createUserMessage(
              this.buildPlannerExecutionPrompt(hasExecutedToolsInRun, {
                complexMode: useComplexWorkflowMode,
                forceCompaction: shouldForceCompaction,
                executedToolCalls: executedToolCallsInRun,
              }),
            )
          : null;

        if (plannerInstruction) {
          plannerDirectiveInjected = true;
        }

        const outboundMessages = plannerInstruction
          ? [...preparedMessages, plannerInstruction]
          : preparedMessages;

        const useResponsesApi = this.config.apiMode === "responses";
        const formattedMessages = useResponsesApi
          ? this.convertMessagesToResponsesFormat(outboundMessages)
          : this.convertMessagesToAzureFormat(outboundMessages);
        const formattedTools =
          this.internalState.tools.length > 0
            ? useResponsesApi
              ? this.convertToolsToResponsesFormat()
              : this.convertToolsToAzureFormat()
            : undefined;

        const events = await this.client.streamChatCompletions(
          this.config.deploymentName,
          formattedMessages,
          {
            tools: formattedTools,
            tool_choice:
              this.internalState.tools.length > 0 ? "auto" : undefined,
            // Some Azure Responses/reasoning models reject temperature.
            ...(useResponsesApi ? {} : { temperature: 0.2 }),
            ...(useResponsesApi
              ? { max_output_tokens: this.config.maxOutputTokens ?? 8192 }
              : {
                  max_completion_tokens: this.config.maxOutputTokens ?? 8192,
                  stream_options: { include_usage: true },
                }),
          },
          { abortSignal: signal },
        );

        this.recordSuccess();

        // Convert stream to content blocks
        const contentBlocks: AssistantContentBlock[] = [];
        const toolCallsByIndex = new Map<number, ToolCallInProgress>();
        let usageInfo:
          | {
              prompt_tokens?: number;
              completion_tokens?: number;
              total_tokens?: number;
            }
          | undefined;

        let chunkCount = 0;
        let hitTokenLimit = false;
        let sawToolCallSignal = false;
        const legacyFunctionCall: {
          name: string;
          accumulatedArgs: string;
        } = {
          name: "",
          accumulatedArgs: "",
        };
        for await (const event of events) {
          if (signal.aborted) break;
          chunkCount++;

          // Capture usage from final event (Azure sends this after content completes)
          if (event.usage) {
            usageInfo = event.usage;
            console.log("[AzureAgent] Usage received:", usageInfo);
          }

          // Debug: log first few chunks
          if (chunkCount <= 5) {
            console.log(`[AzureAgent] Chunk ${chunkCount}:`, JSON.stringify(event, null, 2).slice(0, 500));
          }

          for (const choice of event.choices ?? []) {
            // Check if we hit the token limit
            if (choice.finish_reason === "length") {
              hitTokenLimit = true;
              console.warn("[AzureAgent] WARNING: Model hit token limit (finish_reason: length)");
            }
            if (
              choice.finish_reason === "tool_calls" ||
              choice.finish_reason === "function_call"
            ) {
              sawToolCallSignal = true;
            }

            // Handle streaming text content
            const delta = choice.delta;
            if (delta?.content) {
              const textContent = delta.content;
              const lastBlock = contentBlocks[contentBlocks.length - 1];

              if (lastBlock?.type === "text") {
                lastBlock.text += textContent;
              } else {
                contentBlocks.push({ type: "text", text: textContent });
              }
            }

            // Handle reasoning content (Kimi-K2.5 and similar models)
            if (delta?.reasoning_content) {
              const reasoningText = delta.reasoning_content;
              // Track reasoning as thinking blocks
              const lastBlock = contentBlocks[contentBlocks.length - 1];
              if (lastBlock?.type === "thinking") {
                lastBlock.thinking += reasoningText;
              } else {
                contentBlocks.push({ type: "thinking", thinking: reasoningText });
              }
            }

            // Handle tool calls
            if (delta?.tool_calls) {
              sawToolCallSignal = true;
              for (const tc of delta.tool_calls as StreamedToolCallDelta[]) {
                this.upsertStreamedToolCall(toolCallsByIndex, tc);
              }
            }

            // Handle legacy function_call streaming shape for older Azure deployments.
            const legacyFc = (delta as { function_call?: LegacyFunctionCallDelta })
              ?.function_call;
            if (legacyFc) {
              sawToolCallSignal = true;
              if (legacyFc.name) {
                legacyFunctionCall.name = legacyFc.name;
              }
              if (legacyFc.arguments) {
                legacyFunctionCall.accumulatedArgs += legacyFc.arguments;
              }
            }
          }
        }
        const toolCalls = this.finalizeToolCalls(toolCallsByIndex);
        if (toolCalls.length === 0 && legacyFunctionCall.name) {
          toolCalls.push({
            id: `azure_function_call_${Date.now()}`,
            name: legacyFunctionCall.name,
            arguments: {},
            accumulatedArgs: legacyFunctionCall.accumulatedArgs,
          });
        }
        console.log(`[AzureAgent] Total chunks received: ${chunkCount}`);
        if (hitTokenLimit) {
          console.warn("[AzureAgent] WARNING: Model hit max_completion_tokens limit. Consider increasing.");
        }

        // Check if we got any content at all - Azure sometimes returns empty choices after rate limit recovery
        if (contentBlocks.length === 0 && toolCalls.length === 0) {
          console.warn("[AzureAgent] Empty response received (no content blocks or tool calls). This may be due to rate limiting. Will retry in 3 seconds...");
          await new Promise(resolve => setTimeout(resolve, 3000));
          // Retry by continuing to the next iteration of the outer loop
          continue;
        }

        if (sawToolCallSignal && toolCalls.length === 0) {
          console.warn(
            "[AzureAgent] Stream indicated tool calling but no parseable tool calls were captured. Retrying once.",
          );
          await new Promise((resolve) => setTimeout(resolve, 800));
          continue;
        }

        // Parse accumulated arguments for each tool call after streaming completes
        for (const tc of toolCalls) {
          if (tc.accumulatedArgs) {
            try {
              tc.arguments = JSON.parse(tc.accumulatedArgs);
            } catch (e) {
              // If parsing fails, leave as empty object
              console.warn(
                "[AzureAgent] Failed to parse tool arguments:",
                tc.accumulatedArgs,
                e,
              );
              tc.arguments = {};
            }
          }
        }

        // Add tool calls to content blocks
        for (const tc of toolCalls) {
          contentBlocks.push({
            type: "tool_call",
            id: tc.id,
            name: tc.name,
            arguments: tc.arguments,
          });
        }

        // Debug logging for loop decision
        console.log("[AzureAgent] === Loop iteration decision ===");
        console.log("[AzureAgent] contentBlocks count:", contentBlocks.length);
        console.log("[AzureAgent] contentBlocks types:", contentBlocks.map(b => b.type));
        console.log("[AzureAgent] toolCalls count:", toolCalls.length);
        console.log("[AzureAgent] toolCalls details:", toolCalls.map(tc => ({ id: tc.id, name: tc.name })));

        // Determine if we should continue (tool calls) or stop
        const hasToolCalls = toolCalls.length > 0;
        const stopReason: AssistantMessage["stopReason"] = hasToolCalls
          ? "tool_calls"
          : "complete";

        console.log("[AzureAgent] Decision:", { hasToolCalls, stopReason, iteration: iterations });

        // Build usage info from captured usage data
        let usage: UsageInfo | undefined;
        if (usageInfo) {
          usage = {
            input: usageInfo.prompt_tokens ?? 0,
            output: usageInfo.completion_tokens ?? 0,
            cacheRead: 0, // Azure doesn't use cache tokens
            cacheWrite: 0,
          };
        }

        // Create assistant message
        const assistantMessage = this.createAssistantMessage(
          contentBlocks,
          stopReason,
          usage,
        );
        this.internalState.messages.push(assistantMessage);

        // Emit events
        this.emit({ type: "message_start", message: assistantMessage });
        this.emit({ type: "message_update", message: assistantMessage });
        this.emit({ type: "message_end", message: assistantMessage });

        // Execute tools if any
        if (hasToolCalls && !signal.aborted) {
          hasExecutedToolsInRun = true;
          executedToolCallsInRun += toolCalls.length;
          console.log(
            `[AzureAgent] Executing ${toolCalls.length} tool call(s)...`,
          );
          for (const tc of toolCalls) {
            console.log(`[AzureAgent] Executing tool: ${tc.name}`);
            await this.executeTool(tc, signal);
            console.log(`[AzureAgent] Completed tool: ${tc.name}`);
          }

          // Add a delay between tool execution rounds to avoid rate limits
          // Air-gapped environments often have strict rate limits
          const rateLimitDelay = this.config.rateLimitDelayMs ?? 1000;
          if (rateLimitDelay > 0) {
            console.log(
              `[AzureAgent] Waiting ${rateLimitDelay}ms before next LLM call...`,
            );
            await new Promise((resolve) => setTimeout(resolve, rateLimitDelay));
          }

          // If the loop budget is exhausted immediately after tool execution,
          // grant one final pass so the model can consume tool results and
          // produce a quality-check/final response instead of stopping abruptly.
          if (iterations >= maxIterations && !grantedPostToolFinalizationPass) {
            grantedPostToolFinalizationPass = true;
            iterations = maxIterations - 1;
            this.internalState.messages.push({
              role: "user",
              content:
                "Iteration budget reached. Use the existing tool results to finish now: run final quality checks and provide the final answer. Do not call more tools unless required to avoid a factual error.",
              timestamp: Date.now(),
            });
          }

          console.log(
            "[AzureAgent] Continuing conversation loop with tool results",
          );
          // Continue loop to send tool results back to model
          continue;
        }

        // No tool calls, but check if this was just thinking without action
        // Some models (like Kimi-K2.5) may output reasoning without actually calling tools
        const hasOnlyThinking = contentBlocks.length > 0 && contentBlocks.every(b => b.type === "thinking");
        const hasText = contentBlocks.some(b => b.type === "text" && b.text && b.text.trim().length > 0);

        if (hasOnlyThinking && !hasText) {
          console.log(`[AzureAgent] Model only provided thinking, no tools or response. Nudging to execute...`);
          // Add a nudge message to prompt the model to actually do something
          const nudgeMessage: AssistantMessage = {
            role: "assistant",
            content: contentBlocks,
            timestamp: Date.now(),
            stopReason: "complete",
          };
          this.internalState.messages.push(nudgeMessage);

          // Add a user message prompting for action (don't count nudge as an iteration)
          const actionPrompt: UserMessage = {
            role: "user",
            content: "Please proceed with the requested actions using the available tools.",
            timestamp: Date.now(),
          };
          this.internalState.messages.push(actionPrompt);
          // Don't increment iteration counter for nudge retries - they don't consume meaningful API resources
          iterations = Math.max(0, iterations - 1);

          this.emit({ type: "message_start", message: nudgeMessage });
          this.emit({ type: "message_end", message: nudgeMessage });
          continue; // Retry the loop
        }

        // Planner mode: if the model planned but didn't execute any tool call yet,
        // force progression into execution phase with bounded retries.
        if (
          shouldUsePlannerExecution &&
          !hasExecutedToolsInRun &&
          !hasToolCalls &&
          plannerNudgesUsed < 2
        ) {
          plannerNudgesUsed++;
          console.log(
            `[AzureAgent] Planner mode retry ${plannerNudgesUsed}: no tool calls yet, nudging execution.`,
          );
          this.internalState.messages.push({
            role: "user",
            content:
              "Continue with execution now: call the appropriate tools and proceed without asking additional confirmation.",
            timestamp: Date.now(),
          });
          continue;
        }

        // If the model answered with plain text after a short user confirmation,
        // nudge once to execute concrete steps with tools.
        if (!actionNudgeUsed && this.shouldNudgeForActionWithoutTools(hasToolCalls, contentBlocks)) {
          console.log("[AzureAgent] Text-only response on actionable turn. Nudging model to use tools.");
          actionNudgeUsed = true;
          const actionPrompt: UserMessage = {
            role: "user",
            content:
              "Please execute the requested work now using the available tools and then report concise results.",
            timestamp: Date.now(),
          };
          this.internalState.messages.push(actionPrompt);
          continue;
        }

        // No tool calls, end the agent run
        console.log(`[AzureAgent] === Breaking from loop (no tool calls) ===`);
        console.log(`[AzureAgent] Final content blocks:`, contentBlocks.map(b => ({ type: b.type, text: b.type === 'text' ? b.text?.slice(0, 100) : undefined })));
        break;
      } catch (error) {
        // Record failure for circuit breaker
        this.recordFailure();

        // Handle specific error types
        const errorMessage =
          error instanceof Error ? error.message : "Unknown error";
        console.error("[AzureAgent] API call failed:", error);

        // Emit error message
        const errorAssistant: AssistantMessage = {
          role: "assistant",
          content: [{ type: "text", text: `API Error: ${errorMessage}` }],
          timestamp: Date.now(),
          stopReason: "error",
          errorMessage: errorMessage,
        };

        this.emit({ type: "message_start", message: errorAssistant });
        this.emit({ type: "message_end", message: errorAssistant });
        this.emit({ type: "agent_end" });
        return;
      }
    }

    if (!signal.aborted && iterations >= maxIterations) {
      const limitMessage: AssistantMessage = {
        role: "assistant",
        content: [
          {
            type: "text",
            text:
              "Execution stopped after reaching the iteration budget. Partial results are preserved; retry to continue from current state.",
          },
        ],
        timestamp: Date.now(),
        stopReason: "complete",
      };
      this.emit({ type: "message_start", message: limitMessage });
      this.emit({ type: "message_update", message: limitMessage });
      this.emit({ type: "message_end", message: limitMessage });
    }

    this.emit({ type: "agent_end" });
  }

  private async executeTool(
    toolCall: ToolCallInProgress,
    signal: AbortSignal,
  ): Promise<void> {
    const tool = this.internalState.tools.find((t) => t.name === toolCall.name);

    if (!tool) {
      const errorResult = this.createToolResultMessage(
        toolCall.id,
        {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                error: `Tool ${toolCall.name} not found`,
              }),
            },
          ],
        },
        true,
      );
      this.internalState.messages.push(errorResult);
      return;
    }

    // Emit start event
    this.emit({
      type: "tool_execution_start",
      toolCallId: toolCall.id,
      name: toolCall.name,
      arguments: toolCall.arguments,
    });

    try {
      const isReadTool = [
        "get_cell_ranges",
        "get_range_as_csv",
        "search_data",
        "get_all_objects",
        "read",
        "bash",
      ].includes(tool.name);
      const isNonIdempotentTool = this.isNonIdempotentTool(tool.name);
      const toolFingerprint = this.createToolExecutionFingerprint(
        tool.name,
        toolCall.arguments,
      );

      this.pruneRecentToolExecutions();

      if (isNonIdempotentTool) {
        const recentExecution = this.recentToolExecutions.get(toolFingerprint);
        if (recentExecution) {
          const skippedDuplicateResult: ToolResult = {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  success: true,
                  skippedDuplicate: true,
                  message:
                    "Skipped duplicate email drafting action because an identical draft was already opened recently.",
                  originalToolCallId: recentExecution.toolCallId,
                }),
              },
            ],
          };

          const toolResult = this.createToolResultMessage(
            toolCall.id,
            skippedDuplicateResult,
            false,
          );
          this.internalState.messages.push(toolResult);

          this.emit({
            type: "tool_execution_update",
            toolCallId: toolCall.id,
            partialResult: skippedDuplicateResult,
          });

          this.emit({
            type: "tool_execution_end",
            toolCallId: toolCall.id,
            result: skippedDuplicateResult,
            isError: false,
          });
          return;
        }
      }

      const result = await this.workflowManager.executeTool(
        tool.name,
        toolCall.arguments,
        async () => {
          if (signal.aborted) {
            throw new Error("Tool execution cancelled");
          }
          return await this.runToolWithTimeout(
            () => tool.execute(toolCall.id, toolCall.arguments, signal),
            AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs,
            `Tool '${tool.name}' timed out after ${AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs}ms`,
          );
        },
        {
          isReadOperation: isReadTool,
          maxRetries: isNonIdempotentTool ? 0 : 2,
          dedupKey: isNonIdempotentTool ? toolFingerprint : undefined,
          onStatus: (statusText) => {
            this.emit({
              type: "tool_execution_update",
              toolCallId: toolCall.id,
              partialResult: undefined,
              statusText,
            });
          },
        },
      );

      if (isNonIdempotentTool) {
        this.recentToolExecutions.set(toolFingerprint, {
          toolCallId: toolCall.id,
          completedAt: Date.now(),
        });
      }

      // Create tool result message
      const toolResult = this.createToolResultMessage(
        toolCall.id,
        result,
        false,
      );
      this.internalState.messages.push(toolResult);

      // Emit update for partial result (using final result)
      this.emit({
        type: "tool_execution_update",
        toolCallId: toolCall.id,
        partialResult: result,
      });

      // Emit end event
      this.emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: result,
        isError: false,
      });
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Tool execution failed";

      const errorResult = this.createToolResultMessage(
        toolCall.id,
        {
          content: [
            { type: "text", text: JSON.stringify({ error: errorMessage }) },
          ],
        },
        true,
      );
      this.internalState.messages.push(errorResult);

      this.emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: { error: errorMessage },
        isError: true,
      });
    }
  }

  private getTemperatureForThinkingLevel(): number {
    switch (this.internalState.thinkingLevel) {
      case "off":
      case "low":
        return 0.0;
      case "medium":
        return 0.3;
      case "high":
        return 0.7;
      default:
        return 0.0;
    }
  }

  private async runToolWithTimeout<R>(
    run: () => Promise<R>,
    timeoutMs: number,
    timeoutMessage: string,
  ): Promise<R> {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
    });

    try {
      return await Promise.race([run(), timeoutPromise]);
    } finally {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    }
  }

  abort(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
  }

  reset(): void {
    this.abort();
    this.internalState.messages = [];
    this.recentToolExecutions.clear();
  }

  dispose(): void {
    this.abort();
    this.eventHandlers = [];
    this.recentToolExecutions.clear();

    if (this.ownsWorkflowManager) {
      this.workflowManager.dispose();
    }
  }

  replaceMessages(messages: AgentMessage[]): void {
    this.internalState.messages = [...messages];
  }

  updateConfig(config: Partial<AzureAgentConfig>): void {
    const needsReinit =
      config.endpoint !== undefined ||
      config.apiMode !== undefined ||
      config.apiKey !== undefined ||
      config.useEntraId !== undefined ||
      config.azureClientId !== undefined ||
      config.maxRetries !== undefined ||
      config.useWorkflowManager !== undefined ||
      config.workflowManager !== undefined ||
      config.workflowMaxRequestsPerMinute !== undefined ||
      config.workflowMaxConcurrent !== undefined;

    this.config = { ...this.config, ...config };

    if (config.systemPrompt !== undefined) {
      this.internalState.systemPrompt = config.systemPrompt;
    }
    if (config.thinkingLevel !== undefined) {
      this.internalState.thinkingLevel = config.thinkingLevel;
    }
    if (config.tools !== undefined) {
      this.internalState.tools = config.tools;
      this.toolsJson = JSON.stringify(this.convertToolsToAzureFormat());
    }
    if (config.messages !== undefined) {
      this.internalState.messages = config.messages;
    }

    if (needsReinit) {
      this.initClient();
    }
  }
}

export function createAzureAgent(config: AzureAgentConfig): AzureAgent {
  return new AzureAgent(config);
}
