export interface EndpointRuntimeTuning {
  maxContextTokens?: number;
  maxRetries?: number;
  rateLimitDelayMs?: number;
  maxOutputTokens?: number;
  workflowMaxRequestsPerMinute?: number;
  workflowMaxConcurrent?: number;
}

export interface RuntimeAgentTuningConfig {
  azure?: EndpointRuntimeTuning;
  openai?: EndpointRuntimeTuning;
}

export interface RuntimeConfig {
  appInsightsEnabled: boolean;
  appInsightsConnectionString: string;
  includeUsernameForEntra: boolean;
  airGappedMode: boolean;
  captureUserInput: boolean;
  agentTuning: RuntimeAgentTuningConfig;
}

const DEFAULT_CONFIG: RuntimeConfig = {
  appInsightsEnabled: false,
  appInsightsConnectionString: "",
  includeUsernameForEntra: false,
  airGappedMode: false,
  captureUserInput: false,
  agentTuning: {},
};

function toPositiveInteger(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return Math.floor(value);
  }

  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) {
      return undefined;
    }

    const parsed = Number.parseInt(trimmed, 10);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed;
    }
  }

  return undefined;
}

function normalizeEndpointTuning(value: unknown): EndpointRuntimeTuning {
  const tuning =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};

  return {
    maxContextTokens: toPositiveInteger(tuning.maxContextTokens),
    maxRetries: toPositiveInteger(tuning.maxRetries),
    rateLimitDelayMs: toPositiveInteger(tuning.rateLimitDelayMs),
    maxOutputTokens: toPositiveInteger(tuning.maxOutputTokens),
    workflowMaxRequestsPerMinute: toPositiveInteger(
      tuning.workflowMaxRequestsPerMinute,
    ),
    workflowMaxConcurrent: toPositiveInteger(tuning.workflowMaxConcurrent),
  };
}

function normalizeAgentTuning(value: unknown): RuntimeAgentTuningConfig {
  const tuning =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};

  return {
    azure: normalizeEndpointTuning(tuning.azure),
    openai: normalizeEndpointTuning(tuning.openai),
  };
}

let cachedConfig: RuntimeConfig | null = null;

export async function loadRuntimeConfig(): Promise<RuntimeConfig> {
  if (cachedConfig) return cachedConfig;

  try {
    const response = await fetch("runtime-config.json", {
      cache: "no-store",
    });

    if (!response.ok) {
      cachedConfig = DEFAULT_CONFIG;
      return cachedConfig;
    }

    const raw = (await response.json()) as Partial<RuntimeConfig>;
    cachedConfig = {
      ...DEFAULT_CONFIG,
      ...raw,
      agentTuning: normalizeAgentTuning(raw.agentTuning),
    };
    return cachedConfig;
  } catch {
    cachedConfig = DEFAULT_CONFIG;
    return cachedConfig;
  }
}

export function getRuntimeConfigSync(): RuntimeConfig {
  return cachedConfig ?? DEFAULT_CONFIG;
}
