/**
 * Request Queue - Priority-based Concurrent Request Management
 *
 * Manages concurrent request execution with priority queuing,
 * request deduplication, and automatic retry handling.
 */

import type {
  QueueConfig,
  QueueStats,
  QueuedRequest,
  RequestPriority,
  RetryConfig,
  RetryState,
} from "./types";
import {
  extractHttpStatusCode,
  isAdaptiveThrottleError,
} from "./error-classification";

const PRIORITY_WEIGHTS: Record<RequestPriority, number> = {
  critical: 0,
  high: 1,
  normal: 2,
  low: 3,
};

const DEFAULT_QUEUE_CONFIG: Required<QueueConfig> = {
  maxConcurrent: 3,
  maxQueueSize: 100,
  defaultTimeoutMs: 30000,
  enableDeduplication: true,
  dedupWindowMs: 5000,
};

const DEFAULT_RETRY_CONFIG: Required<RetryConfig> = {
  maxRetries: 3,
  baseDelayMs: 1000,
  maxDelayMs: 30000,
  backoffFactor: 2,
  enableJitter: true,
  jitterFactor: 0.2,
  retryableStatusCodes: [400, 408, 429, 500, 502, 503, 504, 524],
};

export class RequestQueue {
  private config: Required<QueueConfig>;
  private retryConfig: Required<RetryConfig>;
  private queue: QueuedRequest[] = [];
  private activeRequests = new Map<string, QueuedRequest>();
  private dedupMap = new Map<string, QueuedRequest>();
  private stats = {
    processed: 0,
    failed: 0,
    retried: 0,
    totalWaitTime: 0,
  };
  private eventHandlers: Array<
    (event: { type: string; data?: unknown }) => void
  > = [];
  private isProcessing = false;
  private isPaused = false;

  constructor(
    config?: Partial<QueueConfig>,
    retryConfig?: Partial<RetryConfig>,
  ) {
    this.config = { ...DEFAULT_QUEUE_CONFIG, ...config };
    this.retryConfig = { ...DEFAULT_RETRY_CONFIG, ...retryConfig };

    // Start processing loop
    this.startProcessingLoop();
  }

  /**
   * Subscribe to queue events
   */
  subscribe(
    handler: (event: { type: string; data?: unknown }) => void,
  ): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emit(event: { type: string; data?: unknown }): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error("[RequestQueue] Event handler error:", err);
      }
    }
  }

  /**
   * Enqueue a new request
   */
  async enqueue<R>(
    payload: unknown,
    execute: (payload: unknown, signal?: AbortSignal) => Promise<R>,
    options: {
      priority?: RequestPriority;
      timeoutMs?: number;
      maxRetries?: number;
      dedupKey?: string;
    } = {},
  ): Promise<R> {
    const {
      priority = "normal",
      timeoutMs = this.config.defaultTimeoutMs,
      maxRetries = this.retryConfig.maxRetries,
      dedupKey,
    } = options;

    // Check queue size limit
    if (
      this.config.maxQueueSize > 0 &&
      this.queue.length >= this.config.maxQueueSize
    ) {
      throw new Error("Request queue is full");
    }

    // Check for deduplication
    if (this.config.enableDeduplication && dedupKey) {
      const existingRequest = this.findDedupRequest(dedupKey);
      if (existingRequest) {
        console.log(`[RequestQueue] Deduplicating request: ${dedupKey}`);
        return existingRequest.promise as Promise<R>;
      }
    }

    const requestId = generateRequestId();
    const abortController = new AbortController();

    // Create the request promise
    let resolve!: (value: R) => void;
    let reject!: (error: Error) => void;
    const promise = new Promise<R>((res, rej) => {
      resolve = res;
      reject = rej;
    });

    const request: QueuedRequest = {
      id: requestId,
      priority,
      payload,
      execute,
      abortController,
      queuedAt: Date.now(),
      timeoutMs,
      retries: 0,
      maxRetries,
      isExecuting: false,
      resolve: resolve as (value: unknown) => void,
      reject,
      promise: promise as Promise<unknown>,
    };

    // Add to dedup map if key provided
    if (this.config.enableDeduplication && dedupKey) {
      this.dedupMap.set(dedupKey, request);
      // Clean up dedup entry after window expires
      setTimeout(() => {
        this.dedupMap.delete(dedupKey);
      }, this.config.dedupWindowMs);
    }

    // Insert into queue based on priority and FIFO
    this.insertByPriority(request);

    this.emit({
      type: "request_queued",
      data: { requestId, priority, queueLength: this.queue.length },
    });

    return promise;
  }

  /**
   * Cancel a pending request
   */
  cancel(requestId: string): boolean {
    // Check active requests
    const activeRequest = this.activeRequests.get(requestId);
    if (activeRequest) {
      activeRequest.abortController.abort();
      return true;
    }

    // Check queue
    const queueIndex = this.queue.findIndex((r) => r.id === requestId);
    if (queueIndex !== -1) {
      const request = this.queue[queueIndex];
      this.queue.splice(queueIndex, 1);
      request.reject(new Error("Request cancelled"));
      return true;
    }

    return false;
  }

  /**
   * Cancel all pending requests
   */
  cancelAll(): void {
    // Cancel all queued requests
    for (const request of this.queue) {
      request.reject(new Error("All requests cancelled"));
    }
    this.queue = [];

    // Cancel all active requests
    for (const request of this.activeRequests.values()) {
      request.abortController.abort();
    }
  }

  /**
   * Pause queue processing
   */
  pause(): void {
    this.isPaused = true;
    this.emit({ type: "queue_stalled", data: { reason: "paused" } });
  }

  /**
   * Resume queue processing
   */
  resume(): void {
    this.isPaused = false;
    this.emit({ type: "queue_resumed" });
  }

  /**
   * Get current queue statistics
   */
  getStats(): QueueStats {
    const byPriority: Record<RequestPriority, number> = {
      critical: 0,
      high: 0,
      normal: 0,
      low: 0,
    };

    for (const request of this.queue) {
      byPriority[request.priority]++;
    }

    const avgWaitTime =
      this.stats.processed > 0
        ? Math.floor(this.stats.totalWaitTime / this.stats.processed)
        : 0;

    return {
      active: this.activeRequests.size,
      pending: this.queue.length,
      processed: this.stats.processed,
      failed: this.stats.failed,
      retried: this.stats.retried,
      avgWaitTimeMs: avgWaitTime,
      byPriority,
    };
  }

  /**
   * Update configuration at runtime
   */
  updateConfig(config: Partial<QueueConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Update retry configuration at runtime
   */
  updateRetryConfig(config: Partial<RetryConfig>): void {
    this.retryConfig = { ...this.retryConfig, ...config };
  }

  /**
   * Clear all queue statistics
   */
  clearStats(): void {
    this.stats = {
      processed: 0,
      failed: 0,
      retried: 0,
      totalWaitTime: 0,
    };
  }

  /**
   * Dispose of the queue
   */
  dispose(): void {
    this.cancelAll();
    this.eventHandlers = [];
  }

  private insertByPriority(request: QueuedRequest): void {
    const priorityWeight = PRIORITY_WEIGHTS[request.priority];

    // Find insertion point - maintain FIFO for same priority
    let insertIndex = this.queue.length;
    for (let i = 0; i < this.queue.length; i++) {
      const existingWeight = PRIORITY_WEIGHTS[this.queue[i].priority];
      if (priorityWeight < existingWeight) {
        insertIndex = i;
        break;
      }
    }

    this.queue.splice(insertIndex, 0, request);
  }

  private findDedupRequest(dedupKey: string): QueuedRequest | undefined {
    const request = this.dedupMap.get(dedupKey);
    if (request) {
      // Check if request is still valid (not completed/failed)
      const age = Date.now() - request.queuedAt;
      if (age < this.config.dedupWindowMs) {
        return request;
      }
      // Clean up stale entry
      this.dedupMap.delete(dedupKey);
    }
    return undefined;
  }

  private startProcessingLoop(): void {
    const processLoop = async () => {
      while (true) {
        if (
          this.isPaused ||
          this.activeRequests.size >= this.config.maxConcurrent
        ) {
          await sleep(100);
          continue;
        }

        const request = this.queue.shift();
        if (!request) {
          await sleep(50);
          continue;
        }

        this.processRequest(request);
      }
    };

    // Start processing in background
    processLoop().catch(console.error);
  }

  private async processRequest(request: QueuedRequest): Promise<void> {
    request.isExecuting = true;
    this.activeRequests.set(request.id, request);

    const waitTime = Date.now() - request.queuedAt;
    this.stats.totalWaitTime += waitTime;

    console.log(
      `[RequestQueue] Processing request ${request.id}, active=${this.activeRequests.size}`,
    );

    this.emit({
      type: "request_started",
      data: { requestId: request.id, waitTimeMs: waitTime },
    });

    try {
      // Set up timeout
      const timeoutId = setTimeout(() => {
        console.log(`[RequestQueue] Request ${request.id} timed out`);
        request.abortController.abort();
      }, request.timeoutMs);

      console.log(`[RequestQueue] Executing request ${request.id}`);
      const result = await request.execute(
        request.payload,
        request.abortController.signal,
      );
      console.log(`[RequestQueue] Request ${request.id} executed successfully`);

      clearTimeout(timeoutId);

      request.resolve(result);
      this.stats.processed++;

      this.emit({
        type: "request_completed",
        data: {
          requestId: request.id,
          durationMs: Date.now() - request.queuedAt,
        },
      });
    } catch (error) {
      console.error(`[RequestQueue] Request ${request.id} failed:`, error);
      await this.handleRequestError(request, error);
    } finally {
      request.isExecuting = false;
      this.activeRequests.delete(request.id);
      console.log(
        `[RequestQueue] Request ${request.id} finished, active=${this.activeRequests.size}`,
      );
    }
  }

  private async handleRequestError(
    request: QueuedRequest,
    error: unknown,
  ): Promise<void> {
    const errorMessage = error instanceof Error ? error.message : String(error);

    // Check if it's a retryable error
    const shouldRetry =
      request.retries < request.maxRetries &&
      this.isRetryableError(error) &&
      !request.abortController.signal.aborted;

    if (shouldRetry) {
      request.retries++;
      this.stats.retried++;

      const delay = this.calculateRetryDelay(request.retries);
      console.log(
        `[RequestQueue] Retrying request ${request.id} (attempt ${request.retries}/${request.maxRetries}) after ${delay}ms`,
      );

      // Create new abort controller for retry
      request.abortController = new AbortController();

      await sleep(delay);

      // Re-insert into queue at same priority
      this.insertByPriority(request);

      this.emit({
        type: "request_retrying",
        data: {
          requestId: request.id,
          attempt: request.retries,
          maxRetries: request.maxRetries,
          delayMs: delay,
        },
      });

      return;
    }

    // Max retries exceeded or non-retryable error
    const finalError = new Error(
      shouldRetry
        ? errorMessage
        : `Request failed after ${request.retries} retries: ${errorMessage}`,
    );

    request.reject(finalError);
    this.stats.failed++;

    this.emit({
      type: "request_failed",
      data: {
        requestId: request.id,
        error: errorMessage,
        retries: request.retries,
      },
    });
  }

  private isRetryableError(error: unknown): boolean {
    if (error instanceof Error) {
      const message = error.message.toLowerCase();
      const statusCode = extractHttpStatusCode(error);

      if (isAdaptiveThrottleError(error)) {
        return true;
      }

      // Check for retryable HTTP status codes in message
      if (
        statusCode !== undefined &&
        this.retryConfig.retryableStatusCodes.includes(statusCode)
      ) {
        return true;
      }

      // Network errors
      if (
        message.includes("network") ||
        message.includes("timeout") ||
        message.includes("econnreset") ||
        message.includes("abort")
      ) {
        return true;
      }
    }

    return false;
  }

  private calculateRetryDelay(attempt: number): number {
    const exponentialDelay =
      this.retryConfig.baseDelayMs *
      Math.pow(this.retryConfig.backoffFactor, attempt - 1);
    const cappedDelay = Math.min(exponentialDelay, this.retryConfig.maxDelayMs);

    if (!this.retryConfig.enableJitter) {
      return cappedDelay;
    }

    // Add jitter to prevent thundering herd
    const jitterRange = cappedDelay * this.retryConfig.jitterFactor;
    const jitter = (Math.random() * 2 - 1) * jitterRange;
    return Math.max(
      this.retryConfig.baseDelayMs,
      Math.floor(cappedDelay + jitter),
    );
  }
}

function generateRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 9)}`;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Create a request queue with provider-specific defaults
 */
export function createRequestQueue(
  provider: string,
  customConfig?: Partial<QueueConfig>,
  retryConfig?: Partial<RetryConfig>,
): RequestQueue {
  const defaults: Record<string, Partial<QueueConfig>> = {
    openai: {
      maxConcurrent: 2,
      maxQueueSize: 50,
      defaultTimeoutMs: 60000,
    },
    azure: {
      maxConcurrent: 3,
      maxQueueSize: 100,
      defaultTimeoutMs: 120000,
    },
    anthropic: {
      maxConcurrent: 2,
      maxQueueSize: 50,
      defaultTimeoutMs: 90000,
    },
    default: {
      maxConcurrent: 2,
      maxQueueSize: 50,
      defaultTimeoutMs: 60000,
    },
  };

  const providerConfig = defaults[provider] ?? defaults.default;
  return new RequestQueue({ ...providerConfig, ...customConfig }, retryConfig);
}
