import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import {
  anchorMatchesParagraphText,
  getAnchorDocumentParagraphIndex,
  getAnchorScopeParagraphIndex,
  type WordAnchor,
  wordAnchorSchema,
} from "./word-anchor-utils";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

export const formatParagraphsTool = defineTool({
  name: "format_paragraphs",
  label: "Format Paragraphs",
  description:
    "Apply formatting to paragraphs in a Word document. " +
    "Can target all paragraphs, a specific paragraph by index, or the current selection. " +
    "Supports alignment, spacing, indentation, and borders. " +
    "Can also target a specific paragraph anchor from get_document_content or search_document.",
  parameters: Type.Object({
    scope: Type.Union(
      [
        Type.Literal("all", {
          description: "Format all paragraphs in document",
        }),
        Type.Literal("selection", {
          description: "Format selected paragraphs",
        }),
        Type.Literal("single", {
          description: "Format single paragraph by index",
        }),
      ],
      { description: "Which paragraphs to format", default: "all" },
    ),
    paragraphIndex: Type.Optional(
      Type.Number({
        description: "Paragraph index (0-based) when scope is 'single'",
        default: 0,
      }),
    ),
    anchor: Type.Optional(wordAnchorSchema),
    alignment: Type.Optional(
      Type.Union(
        [
          Type.Literal("left", { description: "Left align" }),
          Type.Literal("center", { description: "Center align" }),
          Type.Literal("right", { description: "Right align" }),
          Type.Literal("justified", { description: "Justify align" }),
        ],
        { description: "Text alignment" },
      ),
    ),
    lineSpacing: Type.Optional(
      Type.Number({
        description: "Line spacing in points (e.g., 12, 18, 24)",
      }),
    ),
    spaceBefore: Type.Optional(
      Type.Number({
        description: "Space before paragraph in points",
      }),
    ),
    spaceAfter: Type.Optional(
      Type.Number({
        description: "Space after paragraph in points",
      }),
    ),
    leftIndent: Type.Optional(
      Type.Number({
        description: "Left indent in points",
      }),
    ),
    rightIndent: Type.Optional(
      Type.Number({
        description: "Right indent in points",
      }),
    ),
    firstLineIndent: Type.Optional(
      Type.Number({
        description:
          "First line indent in points (positive) or hanging indent (negative)",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what formatting is being applied (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          true,
          async () => {
            if (params.anchor) {
              const target = await resolveParagraphTarget(context, params.anchor, signal);
              formatParagraph(target.paragraph, params);
              await syncWordContext(context, signal);

              return {
                formatted: 1,
                scope: params.scope,
                alignment: params.alignment,
                anchorUsed: true,
                paragraphIndex: target.paragraphIndex,
                scopeParagraphIndex: target.scopeParagraphIndex,
              };
            }

            let paragraphs: Word.ParagraphCollection;

            switch (params.scope) {
              case "selection": {
                const selection = context.document.getSelection();
                paragraphs = selection.paragraphs;
                break;
              }
              case "single": {
                const body = context.document.body;
                const allParas = body.paragraphs;
                allParas.load("items");
                await syncWordContext(context, signal);

                const index = params.paragraphIndex ?? 0;
                if (index < 0 || index >= allParas.items.length) {
                  throw new Error(
                    `Paragraph index ${index} is out of range (0-${allParas.items.length - 1})`,
                  );
                }
                const singlePara = allParas.items[index];
                if (singlePara) {
                  singlePara.load();
                  await syncWordContext(context, signal);
                }
                if (!singlePara) {
                  throw new Error(`Paragraph index ${index} could not be resolved`);
                }

                formatParagraph(singlePara, params);
                await syncWordContext(context, signal);

                return {
                  formatted: 1,
                  scope: params.scope,
                  alignment: params.alignment,
                  paragraphIndex: index,
                  scopeParagraphIndex: index,
                };
              }
              case "all":
              default: {
                paragraphs = context.document.body.paragraphs;
                break;
              }
            }

            paragraphs.load("items");
            await syncWordContext(context, signal);

            let formattedCount = 0;
            for (const para of paragraphs.items) {
              throwIfToolAborted(signal);
              formatParagraph(para, params);
              formattedCount++;
            }

            await syncWordContext(context, signal);

            return {
              formatted: formattedCount,
              scope: params.scope,
              alignment: params.alignment,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error formatting paragraphs";
      return toolError(message);
    }
  },
});

function formatParagraph(
  para: Word.Paragraph,
  params: {
    alignment?: "left" | "center" | "right" | "justified";
    lineSpacing?: number;
    spaceBefore?: number;
    spaceAfter?: number;
    leftIndent?: number;
    rightIndent?: number;
    firstLineIndent?: number;
  },
): void {
  // Map alignment string to Word.Alignment enum
  if (params.alignment) {
    const alignmentMap: Record<string, Word.Alignment> = {
      left: "Left" as Word.Alignment,
      center: "Centered" as Word.Alignment,
      right: "Right" as Word.Alignment,
      justified: "Justified" as Word.Alignment,
    };
    para.alignment =
      alignmentMap[params.alignment] ?? ("Left" as Word.Alignment);
  }

  if (params.lineSpacing !== undefined) {
    para.lineSpacing = params.lineSpacing;
  }

  if (params.spaceBefore !== undefined) {
    para.spaceBefore = params.spaceBefore;
  }

  if (params.spaceAfter !== undefined) {
    para.spaceAfter = params.spaceAfter;
  }

  if (params.leftIndent !== undefined) {
    para.leftIndent = params.leftIndent;
  }

  if (params.rightIndent !== undefined) {
    para.rightIndent = params.rightIndent;
  }

  if (params.firstLineIndent !== undefined) {
    para.firstLineIndent = params.firstLineIndent;
  }
}

async function resolveParagraphTarget(
  context: Word.RequestContext,
  anchor: WordAnchor,
  signal?: AbortSignal,
): Promise<{
  paragraph: Word.Paragraph;
  paragraphIndex: number | null;
  scopeParagraphIndex: number | null;
}> {
  let anchorMismatch = false;
  const documentParagraphIndex = getAnchorDocumentParagraphIndex(anchor);
  if (documentParagraphIndex !== null) {
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (
      documentParagraphIndex < 0 ||
      documentParagraphIndex >= paragraphs.items.length
    ) {
      throw new Error(
        `Anchor paragraphIndex ${documentParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[documentParagraphIndex];
    if (!paragraph) {
      throw new Error(`Anchor paragraphIndex ${documentParagraphIndex} could not be resolved`);
    }

    if (anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
      return {
        paragraph,
        paragraphIndex: documentParagraphIndex,
        scopeParagraphIndex: getAnchorScopeParagraphIndex(anchor),
      };
    }

    anchorMismatch = true;
  }

  const scopeParagraphIndex = getAnchorScopeParagraphIndex(anchor);
  if (scopeParagraphIndex !== null) {
    const selection = context.document.getSelection();
    const paragraphs = selection.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (scopeParagraphIndex < 0 || scopeParagraphIndex >= paragraphs.items.length) {
      throw new Error(
        `Anchor scopeParagraphIndex ${scopeParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[scopeParagraphIndex];
    if (!paragraph) {
      throw new Error(
        `Anchor scopeParagraphIndex ${scopeParagraphIndex} could not be resolved`,
      );
    }

    if (anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
      return {
        paragraph,
        paragraphIndex: null,
        scopeParagraphIndex,
      };
    }

    anchorMismatch = true;
  }

  if (anchorMismatch) {
    throw new Error(
      "Anchor no longer matches current document content. Read the target again before editing.",
    );
  }

  throw new Error(
    "Anchor is missing paragraphIndex/scopeParagraphIndex and cannot be used for paragraph formatting.",
  );
}
