function thinkingLevelToAgent(level: ThinkingLevel): AgentThinkingLevel {
  return level === "none" ? "off" : level;
}

export function ChatProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<ChatState>(() => {
    const saved = loadSavedConfig();
    const hasAuth = saved?.useEntraId ? true : Boolean(saved?.apiKey?.trim());
    const validConfig = saved?.provider && hasAuth ? saved : null;
    return {
      messages: [],
      isStreaming: false,
      error: null,
      providerConfig: validConfig,
      sessionStats: INITIAL_STATS,
      currentSession: null,
      sessions: [],
      sheetNames: {},
      uploads: [],
      isUploading: false,
      skills: [],
    };
  });

  const agentRef = useRef<AzureAgent | OpenAIAgent | null>(null);
  const streamingMessageIdRef = useRef<string | null>(null);
  const isStreamingRef = useRef(false);
  const isMountedRef = useRef(true);
  const pendingConfigRef = useRef<ProviderConfig | null>(null);
  const workbookIdRef = useRef<string | null>(null);
  const sessionLoadedRef = useRef(false);
  const currentSessionIdRef = useRef<string | null>(null);
  const followModeRef = useRef(state.providerConfig?.followMode ?? true);
  const skillsRef = useRef<SkillMeta[]>([]);
  const configRef = useRef<ProviderConfig | null>(null);
  const toolStartTimesRef = useRef<Record<string, number>>({});
  const toolNamesRef = useRef<Record<string, string>>({});
  const entraIdentityLoggedRef = useRef(false);
  const llmWikiActivationKeyRef = useRef<string | null>(null);

  const availableProviders = ["azure", "my-ai"];

  const getModelsForProvider = useCallback((provider: string): string[] => {
    if (provider === "azure") {
      return ["gpt-4o", "gpt-4o-mini", "gpt-4.1", "gpt-4"];
    }
    if (provider === "my-ai") {
      return [
        "gpt-4o",
        "gpt-4o-mini",
        "gpt-4-turbo",
        "gpt-4",
        "o3-mini",
        "o1",
        "o1-mini",
      ];
    }
    return [];
  }, []);

  const handleAgentEvent = useCallback((event: AgentEvent) => {
    console.log("[Chat] Agent event:", event.type, event);
    switch (event.type) {
      case "message_start": {
        if (event.message.role === "assistant") {
          const id = generateId();
          streamingMessageIdRef.current = id;
          const parts = extractPartsFromAssistantMessage(event.message);
          const chatMessage: ChatMessage = {
            id,
            role: "assistant",
            parts,
            timestamp: event.message.timestamp,
          };
          setState((prev) => ({
            ...prev,
            messages: [...prev.messages, chatMessage],
          }));
        }
        break;
      }
      case "message_update": {
        if (
          event.message.role === "assistant" &&
          streamingMessageIdRef.current
        ) {
          setState((prev) => {
            const messages = [...prev.messages];
            const idx = messages.findIndex(
              (m) => m.id === streamingMessageIdRef.current,
            );
            if (idx !== -1) {
              const parts = extractPartsFromAssistantMessage(
                event.message,
                messages[idx].parts,
              );
              messages[idx] = { ...messages[idx], parts };
            }
            return { ...prev, messages };
          });
        }
        break;
      }
      case "message_end": {
        if (event.message.role === "assistant") {
          const assistantMsg = event.message as AssistantMessage;
          const isError =
            assistantMsg.stopReason === "error" ||
            assistantMsg.stopReason === "aborted";
          console.log("[Chat] Assistant message result:", event.message);
          console.log("[Chat] Usage:", assistantMsg.usage);
          console.log(
            "[Chat] stopReason:",
            assistantMsg.stopReason,
            "errorMessage:",
            assistantMsg.errorMessage,
          );

          setState((prev) => {
            const messages = [...prev.messages];
            const idx = messages.findIndex(
              (m) => m.id === streamingMessageIdRef.current,
            );

            if (isError) {
              if (idx !== -1) {
                messages.splice(idx, 1);
              }
            } else if (idx !== -1) {
              const parts = extractPartsFromAssistantMessage(
                event.message,
                messages[idx].parts,
              );
              messages[idx] = { ...messages[idx], parts };
            }

            return {
              ...prev,
              messages,
              error: isError
                ? assistantMsg.errorMessage || "Request failed"
                : prev.error,
              sessionStats: isError
                ? prev.sessionStats
                : {
                    ...deriveStats(
                      agentRef.current?.state.messages ?? [],
                      agentRef.current?.currentTokenCount.total ?? 0,
                    ),
                    contextWindow: prev.sessionStats.contextWindow,
                  },
            };
          });
          streamingMessageIdRef.current = null;
        }
        break;
      }
      case "tool_execution_start": {
        toolStartTimesRef.current[event.toolCallId] = Date.now();
        toolNamesRef.current[event.toolCallId] = event.name;
        trackEvent("tool_call_start", {
          product: getHostContext().type,
          provider: configRef.current?.provider ?? "unknown",
          toolName: event.name,
        });

        setState((prev) => {
          const messages = [...prev.messages];
          for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            const partIdx = msg.parts.findIndex(
              (p) => p.type === "toolCall" && p.id === event.toolCallId,
            );
            if (partIdx !== -1) {
              const parts = [...msg.parts];
              const part = parts[partIdx];
              if (part.type === "toolCall") {
                parts[partIdx] = { ...part, status: "running" };
                messages[i] = { ...msg, parts };
              }
              break;
            }
          }
          return { ...prev, messages };
        });
        break;
      }
      case "tool_execution_update": {
        setState((prev) => {
          const messages = [...prev.messages];
          for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            const partIdx = msg.parts.findIndex(
              (p) => p.type === "toolCall" && p.id === event.toolCallId,
            );
            if (partIdx !== -1) {
              const parts = [...msg.parts];
              const part = parts[partIdx];
              if (part.type === "toolCall") {
                const nextPart = { ...part };

                if (event.statusText) {
                  nextPart.statusText = event.statusText;
                }

                if (event.partialResult !== undefined) {
                  let partialText: string;
                  if (typeof event.partialResult === "string") {
                    partialText = event.partialResult;
                  } else if (
                    event.partialResult &&
                    typeof event.partialResult === "object" &&
                    "content" in event.partialResult &&
                    Array.isArray(
                      (event.partialResult as { content?: unknown }).content,
                    )
                  ) {
                    partialText = (
                      event.partialResult as {
                        content: { type: string; text: string }[];
                      }
                    ).content
                      .filter((c) => c.type === "text")
                      .map((c) => c.text)
                      .join("\n");
                  } else {
                    partialText = JSON.stringify(event.partialResult, null, 2);
                  }
                  nextPart.result = partialText;
                }

                parts[partIdx] = nextPart;
                messages[i] = { ...msg, parts };
              }
              break;
            }
          }
          return { ...prev, messages };
        });
        break;
      }
      case "tool_execution_end": {
        const startedAt = toolStartTimesRef.current[event.toolCallId];
        const durationMs = startedAt ? Date.now() - startedAt : undefined;
        const toolName = toolNamesRef.current[event.toolCallId] ?? "unknown";

        trackEvent(
          "tool_call",
          {
            product: getHostContext().type,
            provider: configRef.current?.provider ?? "unknown",
            toolName,
            success: event.isError ? "false" : "true",
          },
          durationMs !== undefined ? { durationMs } : undefined,
        );

        delete toolStartTimesRef.current[event.toolCallId];
        delete toolNamesRef.current[event.toolCallId];

        let resultText: string;
        if (typeof event.result === "string") {
          resultText = event.result;
        } else if (
          event.result &&
          typeof event.result === "object" &&
          "content" in event.result &&
          Array.isArray((event.result as { content?: unknown }).content)
        ) {
          resultText = (
            event.result as { content: { type: string; text: string }[] }
          ).content
            .filter((c) => c.type === "text")
            .map((c) => c.text)
            .join("\n");
        } else {
          resultText = JSON.stringify(event.result, null, 2);
        }

        if (!event.isError && followModeRef.current) {
          const dirtyRanges = parseDirtyRanges(resultText);
          if (dirtyRanges && dirtyRanges.length > 0) {
            const first = dirtyRanges[0];
            if (first.sheetId >= 0 && first.range !== "*") {
              navigateTo(first.sheetId, first.range).catch((err) => {
                console.error("[FollowMode] Navigation failed:", err);
              });
            } else if (first.sheetId >= 0) {
              // For whole-sheet changes, just activate the sheet
              navigateTo(first.sheetId).catch((err) => {
                console.error("[FollowMode] Navigation failed:", err);
              });
            }
          }
        }

        setState((prev) => {
          const messages = [...prev.messages];
          for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            const partIdx = msg.parts.findIndex(
              (p) => p.type === "toolCall" && p.id === event.toolCallId,
            );
            if (partIdx !== -1) {
              const parts = [...msg.parts];
              const part = parts[partIdx];
              if (part.type === "toolCall") {
                parts[partIdx] = {
                  ...part,
                  status: event.isError ? "error" : "complete",
                  result: resultText,
                  statusText: undefined,
                };
                messages[i] = { ...msg, parts };
              }
              break;
            }
          }
          return { ...prev, messages };
        });
        break;
      }
      case "agent_end": {
        isStreamingRef.current = false;
        setState((prev) => ({ ...prev, isStreaming: false }));
        // Note: streamingMessageIdRef is cleared in message_end, not here
        // to avoid race condition where agent_end fires before message_end completes
        break;
      }
    }
  }, []);

  const getActiveApiKey = useCallback(
    async (config: ProviderConfig): Promise<string> => {
      // For Azure OpenAI: use API key or Entra ID (handled by Azure SDK)
      // If useEntraId is true, we'll return empty and let the SDK handle auth
      return config.useEntraId ? "" : config.apiKey;
    },
    [],
  );

  const applyConfig = useCallback(
    (config: ProviderConfig) => {
      const modelConfig = getDefaultAzureModelConfig();
      const contextWindow = modelConfig.contextWindow;
      const airgapMode = isAirGappedMode();
      const runtimeConfig = getRuntimeConfigSync();
      const azureRuntimeTuning = runtimeConfig.agentTuning.azure ?? {};
      const openaiRuntimeTuning = runtimeConfig.agentTuning.openai ?? {};
      configRef.current = config;

      const existingMessages = agentRef.current?.state.messages ?? [];

      if (agentRef.current) {
        agentRef.current.dispose();
      }

      const systemPrompt = buildSystemPrompt(skillsRef.current);
      console.log(
        "[Chat] Skills in prompt:",
        skillsRef.current.length,
        skillsRef.current.map((s) => s.name),
      );
      console.log("[Chat] System prompt tail:", systemPrompt.slice(-500));

      const thinkingLevel = thinkingLevelToAgent(config.thinking);
      const tools = getToolsForHost();
      const messages = existingMessages as AgentMessage[];
      const normalizePositiveNumber = (
        value: number | undefined,
      ): number | undefined => {
        if (typeof value !== "number") {
          return undefined;
        }
        if (!Number.isFinite(value) || value <= 0) {
          return undefined;
        }
        return Math.floor(value);
      };

      const resolveTuningValue = (
        configuredValue: number | undefined,
        airgapFallback: number,
      ): number | undefined => {
        const normalized = normalizePositiveNumber(configuredValue);
        if (normalized !== undefined) {
          return normalized;
        }
        return airgapMode ? airgapFallback : undefined;
      };

      if (config.provider === "my-ai") {
        const baseUrl =
          config.openaiBaseUrl.trim() || "https://api.openai.com/v1";
        const agent = createOpenAIAgent({
          apiKey: config.apiKey,
          model: config.model || "gpt-4o",
          baseUrl,
          systemPrompt,
          thinkingLevel,
          tools,
          messages,
          executionModel: "planner",
          maxContextTokens: resolveTuningValue(
            openaiRuntimeTuning.maxContextTokens,
            AIRGAP_CONFIG.tokens.maxContextTokens,
          ),
          maxRetries: resolveTuningValue(
            openaiRuntimeTuning.maxRetries,
            AIRGAP_CONFIG.rateLimit.maxRetries,
          ),
          rateLimitDelayMs: resolveTuningValue(
            openaiRuntimeTuning.rateLimitDelayMs,
            AIRGAP_CONFIG.rateLimit.defaultDelayMs,
          ),
          maxOutputTokens: normalizePositiveNumber(
            openaiRuntimeTuning.maxOutputTokens,
          ),
          workflowMaxRequestsPerMinute: normalizePositiveNumber(
            openaiRuntimeTuning.workflowMaxRequestsPerMinute,
          ),
          workflowMaxConcurrent: normalizePositiveNumber(
            openaiRuntimeTuning.workflowMaxConcurrent,
          ),
        });
        agentRef.current = agent;
        agent.subscribe(handleAgentEvent);
        console.log("[Chat] OpenAI config:", {
          model: config.model || "gpt-4o",
          baseUrl,
          contextWindow,
          tuning: openaiRuntimeTuning,
        });
      } else {
        // Azure provider (default)
        const agent = createAzureAgent({
          endpoint: getAzureEndpoint(config),
          deploymentName: config.azureDeploymentName,
          apiMode: config.azureApiMode,
          apiKey: config.apiKey,
          useEntraId: config.useEntraId,
          azureClientId: config.azureClientId,
          systemPrompt,
          thinkingLevel,
          tools,
          messages,
          executionModel: "planner",
          maxContextTokens: resolveTuningValue(
            azureRuntimeTuning.maxContextTokens,
            AIRGAP_CONFIG.tokens.maxContextTokens,
          ),
          maxRetries: resolveTuningValue(
            azureRuntimeTuning.maxRetries,
            AIRGAP_CONFIG.rateLimit.maxRetries,
          ),
          rateLimitDelayMs: resolveTuningValue(
            azureRuntimeTuning.rateLimitDelayMs,
            AIRGAP_CONFIG.rateLimit.defaultDelayMs,
          ),
          maxOutputTokens: normalizePositiveNumber(
            azureRuntimeTuning.maxOutputTokens,
          ),
          workflowMaxRequestsPerMinute: normalizePositiveNumber(
            azureRuntimeTuning.workflowMaxRequestsPerMinute,
          ),
          workflowMaxConcurrent: normalizePositiveNumber(
            azureRuntimeTuning.workflowMaxConcurrent,
          ),
        });
        agentRef.current = agent;
        agent.subscribe(handleAgentEvent);
        console.log("[Chat] Azure model config:", {
          deploymentName: config.azureDeploymentName,
          model: config.model,
          contextWindow: modelConfig.contextWindow,
          maxTokens: modelConfig.maxTokens,
          tuning: azureRuntimeTuning,
        });
      }

      pendingConfigRef.current = null;
      followModeRef.current = config.followMode ?? true;

      setState((prev) => ({
        ...prev,
        providerConfig: config,
        error: null,
        sessionStats: { ...prev.sessionStats, contextWindow },
      }));
    },
    [handleAgentEvent],
  );

  const setProviderConfig = useCallback(
    (config: ProviderConfig) => {
      if (isStreamingRef.current) {
        pendingConfigRef.current = config;
        setState((prev) => ({ ...prev, providerConfig: config }));
        return;
      }
      applyConfig(config);
    },
    [applyConfig],
  );

  const abort = useCallback(() => {
    agentRef.current?.abort();
    isStreamingRef.current = false;
    streamingMessageIdRef.current = null;
    setState((prev) => ({ ...prev, isStreaming: false }));
  }, []);

  const refreshUploads = useCallback(async () => {
    const uploadNames = await listUploads();
    setState((prev) => ({
      ...prev,
      uploads: uploadNames.map((name) => ({ name, size: 0 })),
    }));
  }, []);

  const sendMessage = useCallback(
    async (content: string, attachments?: string[]) => {
      if (pendingConfigRef.current) {
        applyConfig(pendingConfigRef.current);
      }
      const agent = agentRef.current;
      if (!agent || !state.providerConfig) {
        setState((prev) => ({
          ...prev,
          error: "Please configure your API key first",
        }));
        return;
      }

      const userMessage: ChatMessage = {
        id: generateId(),
        role: "user",
        parts: [{ type: "text", text: content }],
        timestamp: Date.now(),
      };

      isStreamingRef.current = true;
      setState((prev) => ({
        ...prev,
        messages: [...prev.messages, userMessage],
        isStreaming: true,
        error: null,
      }));

      try {
        let promptContent = content;
        const liveUploads = await listUploads();
        const effectiveAttachments = resolveAttachmentNames(
          attachments,
          liveUploads,
        );
        const attachmentActivationKey = effectiveAttachments
          ? [...effectiveAttachments].sort().join("\n")
          : "";
        const shouldIncludeLlmWiki =
          effectiveAttachments !== undefined &&
          effectiveAttachments.length >= 2 &&
          attachmentActivationKey !== llmWikiActivationKeyRef.current;
        const telemetryHost = getHostContext();
        const telemetryConfig = state.providerConfig;

        const sessionProperties: Record<string, string> = {
          product: telemetryHost.type,
          provider: telemetryConfig.provider,
          authOption: telemetryConfig.useEntraId ? "entra_id" : "api_key",
          endpointHost: getEndpointHost(telemetryConfig),
          useProxy: telemetryConfig.useProxy ? "true" : "false",
        };
        if (telemetryConfig.provider === "azure") {
          sessionProperties.deployment =
            telemetryConfig.azureDeploymentName || "unset";
        }

        let initialUsernameLogged = false;
        if (telemetryConfig.useEntraId && shouldIncludeUsernameForEntra()) {
          const username = getUsernameForTelemetry();
          if (username) {
            sessionProperties.username = username;
            setAuthenticatedUser(username);
            entraIdentityLoggedRef.current = true;
            initialUsernameLogged = true;
          }
        }
        trackEvent("session_config_snapshot", sessionProperties);

        if (getRuntimeConfigSync().captureUserInput) {
          trackEvent(
            "user_message",
            {
              product: telemetryHost.type,
              provider: telemetryConfig.provider,
              userInput: truncateForTelemetry(content),
            },
            { inputLength: content.length },
          );
        }

        // Only fetch workbook metadata in Excel (not Outlook)
        const isExcel = Office?.context?.host === Office.HostType.Excel;
        if (isExcel) {
          try {
            console.log("[Chat] Fetching workbook metadata...");
            const metadata = await getWorkbookMetadata();
            console.log("[Chat] Workbook metadata:", metadata);
            promptContent = `<wb_context>\n${JSON.stringify(metadata, null, 2)}\n</wb_context>\n\n${content}`;

            if (metadata.sheetsMetadata) {
              const newSheetNames: Record<number, string> = {};
              for (const sheet of metadata.sheetsMetadata) {
                newSheetNames[sheet.id] = sheet.name;
              }
              setState((prev) => ({ ...prev, sheetNames: newSheetNames }));
            }
          } catch (err) {
            console.error("[Chat] Failed to get workbook metadata:", err);
          }
        }

        // Add attachments section if files are uploaded
        promptContent = `${buildAttachmentsEnrichment(effectiveAttachments, {
          includeLlmWiki: shouldIncludeLlmWiki,
        })}${promptContent}`;

        if (shouldIncludeLlmWiki) {
          llmWikiActivationKeyRef.current = attachmentActivationKey;
        }

        await agent.prompt(promptContent);

        // First Entra username often becomes available only after token acquisition
        // inside the Azure agent request. Emit a one-time identity enrichment event.
        if (
          telemetryConfig.useEntraId &&
          shouldIncludeUsernameForEntra() &&
          !initialUsernameLogged &&
          !entraIdentityLoggedRef.current
        ) {
          const deferredUsername = getUsernameForTelemetry();
          if (deferredUsername) {
            setAuthenticatedUser(deferredUsername);
            entraIdentityLoggedRef.current = true;
            trackEvent("session_identity", {
              product: telemetryHost.type,
              provider: telemetryConfig.provider,
              authOption: "entra_id",
              username: deferredUsername,
            });
          }
        }

        console.log("[Chat] Full context:", agent.state.messages);
      } catch (err) {
        console.error("[Chat] sendMessage error:", err);
        isStreamingRef.current = false;
        setState((prev) => ({
          ...prev,
          isStreaming: false,
          error: err instanceof Error ? err.message : "An error occurred",
        }));
      }
    },
    [state.providerConfig, applyConfig],
  );

  const clearMessages = useCallback(() => {
    abort();
    agentRef.current?.reset();
    resetVfs();
    llmWikiActivationKeyRef.current = null;
    if (currentSessionIdRef.current) {
      Promise.all([
        saveSession(currentSessionIdRef.current, []),
        saveVfsFiles(currentSessionIdRef.current, []),
      ]).catch(console.error);
    }
    setState((prev) => ({
      ...prev,
      messages: [],
      error: null,
      sessionStats: INITIAL_STATS,
      uploads: [],
    }));
  }, [abort]);

  const refreshSessions = useCallback(async () => {
    if (!workbookIdRef.current) return;
    const sessions = await listSessions(workbookIdRef.current);
    console.log(
      "[Chat] refreshSessions:",
      sessions.map((s) => ({
        id: s.id,
        name: s.name,
        msgs: (s.agentMessages ?? []).length,
      })),
    );
    setState((prev) => ({ ...prev, sessions }));
  }, []);

  const newSession = useCallback(async () => {
    console.log("[Chat] newSession called, workbookId:", workbookIdRef.current);
    if (!workbookIdRef.current) {
      console.error("[Chat] Cannot create session: workbookId not set");
      return;
    }
    if (isStreamingRef.current) {
      console.log("[Chat] newSession blocked: streaming in progress");
      return;
    }
    try {
      agentRef.current?.reset();
      resetVfs();
      llmWikiActivationKeyRef.current = null;
      const session = await createSession(workbookIdRef.current);
      console.log("[Chat] Created new session:", session.id);
      currentSessionIdRef.current = session.id;
      await refreshSessions();
      if (!isMountedRef.current) return;
      setState((prev) => ({
        ...prev,
        messages: [],
        currentSession: session,
        error: null,
        sessionStats: INITIAL_STATS,
        uploads: [],
      }));
    } catch (err) {
      console.error("[Chat] Failed to create session:", err);
    }
  }, [refreshSessions]);

  const switchSession = useCallback(async (sessionId: string) => {
    console.log(
      "[Chat] switchSession called:",
      sessionId,
      "current:",
      currentSessionIdRef.current,
    );
    if (currentSessionIdRef.current === sessionId) return;
    if (isStreamingRef.current) {
      console.log("[Chat] switchSession blocked: streaming in progress");
      return;
    }
    agentRef.current?.reset();
    llmWikiActivationKeyRef.current = null;
    try {
      const [session, vfsFiles] = await Promise.all([
        getSession(sessionId),
        loadVfsFiles(sessionId),
      ]);
      console.log(
        "[Chat] switchSession loaded:",
        session?.id,
        "agentMessages:",
        session?.agentMessages.length,
        "vfs:",
        vfsFiles.length,
      );
      if (!session) {
        console.error("[Chat] Session not found:", sessionId);
        return;
      }
      await restoreVfs(vfsFiles);
      currentSessionIdRef.current = session.id;

      if (session.agentMessages.length > 0 && agentRef.current) {
        agentRef.current.replaceMessages(session.agentMessages);
      }

      const uploadNames = await listUploads();
      const stats = deriveStats(session.agentMessages);
      if (!isMountedRef.current) return;
      setState((prev) => ({
        ...prev,
        messages: agentMessagesToChatMessages(session.agentMessages),
        currentSession: session,
        error: null,
        sessionStats: {
          ...stats,
          contextWindow: prev.sessionStats.contextWindow,
        },
        uploads: uploadNames.map((name) => ({ name, size: 0 })),
      }));
    } catch (err) {
      console.error("[Chat] Failed to switch session:", err);
    }
  }, []);

  const deleteCurrentSession = useCallback(async () => {
    if (!currentSessionIdRef.current || !workbookIdRef.current) return;
    if (isStreamingRef.current) {
      console.log("[Chat] deleteCurrentSession blocked: streaming in progress");
      return;
    }
    agentRef.current?.reset();
    llmWikiActivationKeyRef.current = null;
    const deletedId = currentSessionIdRef.current;
    await deleteSession(deletedId);
    const session = await createSession(workbookIdRef.current);
    currentSessionIdRef.current = session.id;
    const vfsFiles = await loadVfsFiles(session.id);
    await restoreVfs(vfsFiles);

    if (session.agentMessages.length > 0 && agentRef.current) {
      agentRef.current.replaceMessages(session.agentMessages);
    }

    await refreshSessions();
    const uploadNames = await listUploads();
    const stats = deriveStats(session.agentMessages);
    setState((prev) => ({
      ...prev,
      messages: agentMessagesToChatMessages(session.agentMessages),
      currentSession: session,
      error: null,
      sessionStats: {
        ...stats,
        contextWindow: prev.sessionStats.contextWindow,
      },
      uploads: uploadNames.map((name) => ({ name, size: 0 })),
    }));
  }, [refreshSessions]);

  const prevStreamingRef = useRef(false);
  useEffect(() => {
    if (
      prevStreamingRef.current &&
      !state.isStreaming &&
      currentSessionIdRef.current
    ) {
      const sessionId = currentSessionIdRef.current;
      const agentMessages = agentRef.current?.state.messages ?? [];
      // Snapshot VFS first (returns native Promise), then save to runtime storage.
      (async () => {
        try {
          const vfsFiles = await snapshotVfs();
          await Promise.all([
            saveSession(sessionId, agentMessages),
            saveVfsFiles(sessionId, vfsFiles),
          ]);
          await refreshSessions();
          const updated = await getSession(sessionId);
          if (updated && isMountedRef.current) {
            setState((prev) => ({ ...prev, currentSession: updated }));
          }
        } catch (e) {
          console.error(e);
        }
      })();
    }
    prevStreamingRef.current = state.isStreaming;
  }, [state.isStreaming, refreshSessions]);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
      agentRef.current?.dispose();
    };
  }, []);

  useEffect(() => {
    if (sessionLoadedRef.current) return;
    sessionLoadedRef.current = true;

    getOrCreateWorkbookId()
      .then(async (id) => {
        workbookIdRef.current = id;
        console.log("[Chat] Workbook ID:", id);

        // Load skills into VFS cache BEFORE applyConfig so the system prompt includes them
        const skills = await getInstalledSkills();
        skillsRef.current = skills;
        await syncSkillsToVfs();
        console.log(
          "[Chat] Loaded",
          skills.length,
          "skills:",
          skills.map((s) => s.name),
        );

        // Now apply provider config — agent gets the correct system prompt with skills
        const saved = loadSavedConfig();
        if (
          saved?.provider &&
          (saved.useEntraId || Boolean(saved.apiKey?.trim()))
        ) {
          applyConfig(saved);
        }

        const session = await getOrCreateCurrentSession(id);
        llmWikiActivationKeyRef.current = null;
        currentSessionIdRef.current = session.id;
        const [sessions, vfsFiles] = await Promise.all([
          listSessions(id),
          loadVfsFiles(session.id),
        ]);
        if (vfsFiles.length > 0) {
          await restoreVfs(vfsFiles);
        }

        if (session.agentMessages.length > 0 && agentRef.current) {
          agentRef.current.replaceMessages(session.agentMessages);
          console.log(
            "[Chat] Restored",
            session.agentMessages.length,
            "agent messages from runtime storage",
          );
        }

        const uploadNames = await listUploads();
        const stats = deriveStats(session.agentMessages);
        console.log(
          "[Chat] Loaded session:",
          session.id,
          "agentMessages:",
          session.agentMessages.length,
          "vfs:",
          vfsFiles.length,
        );
        if (!isMountedRef.current) return;
        setState((prev) => ({
          ...prev,
          messages: agentMessagesToChatMessages(session.agentMessages),
          currentSession: session,
          sessions,
          skills,
          sessionStats: {
            ...stats,
            contextWindow: prev.sessionStats.contextWindow,
          },
          uploads: uploadNames.map((name) => ({ name, size: 0 })),
        }));
      })
      .catch((err) => {
        console.error("[Chat] Failed to load session:", err);
      });
  }, [applyConfig]);

  const getSheetName = useCallback(
    (sheetId: number): string | undefined => state.sheetNames[sheetId],
    [state.sheetNames],
  );

  const processFiles = useCallback(
    async (files: File[]) => {
      if (files.length === 0) return;
      setState((prev) => ({ ...prev, isUploading: true }));
      try {
        const diConfig = state.providerConfig
          ? getDocumentIntelligenceConfig(state.providerConfig)
          : null;

        for (const file of files) {
          const buffer = await file.arrayBuffer();
          const data = new Uint8Array(buffer);

          // Use webkitRelativePath when uploading a folder to preserve directory structure
          const relativePath = (file as any).webkitRelativePath;
          let uploadName =
            relativePath && relativePath.trim().length > 0
              ? relativePath
              : file.name;

          let parsedFileName: string | null = null;
          let parsedContentLength: number | null = null;

          // Use Document Intelligence if configured
          if (diConfig) {
            try {
              const result = await processDocumentWithIntelligence(
                file,
                data,
                diConfig,
              );
              if (result.parsedPath && result.parsedDocument) {
                uploadName = `${file.name} (parsed: ${result.parsedDocument.pages} pages, ${result.parsedDocument.tables} tables)`;
                parsedFileName = `${file.name}.parsed.txt`;
                parsedContentLength =
                  result.parsedDocument.content?.length ?? 0;
              }
            } catch (diErr) {
              console.error("[Chat] Document Intelligence failed:", diErr);
              // Fall back to storing raw file
              await writeFile(file.name, data);
            }
          } else {
            await writeFile(uploadName, data);
          }

          setState((prev) => {
            const newUploads = [...prev.uploads];
            // Remove existing entries for this file or its parsed version
            const filtered = newUploads.filter(
              (u) => u.name !== file.name && u.name !== parsedFileName,
            );
            // Add the original file entry (with annotation if parsed)
            filtered.push({ name: uploadName, size: file.size });
            // Add the parsed file entry if it exists
            if (parsedFileName) {
              filtered.push({
                name: parsedFileName,
                size: parsedContentLength ?? file.size,
              });
            }
            return { ...prev, uploads: filtered };
          });
        }
        if (currentSessionIdRef.current) {
          const snapshot = await snapshotVfs();
          await saveVfsFiles(currentSessionIdRef.current, snapshot);
        }
      } catch (err) {
        console.error("Failed to upload file:", err);
      } finally {
        setState((prev) => ({ ...prev, isUploading: false }));
      }
    },
    [state.providerConfig],
  );

  const removeUpload = useCallback(async (name: string) => {
    try {
      await deleteFile(name);
      setState((prev) => ({
        ...prev,
        uploads: prev.uploads.filter((u) => u.name !== name),
      }));
      if (currentSessionIdRef.current) {
        const snapshot = await snapshotVfs();
        await saveVfsFiles(currentSessionIdRef.current, snapshot);
      }
    } catch (err) {
      console.error("Failed to delete file:", err);
      setState((prev) => ({
        ...prev,
        uploads: prev.uploads.filter((u) => u.name !== name),
      }));
    }
  }, []);

  const refreshSkillsAndRebuildAgent = useCallback(async () => {
    skillsRef.current = await getInstalledSkills();
    setState((prev) => {
      // Re-apply config to rebuild agent with updated system prompt
      if (prev.providerConfig) {
        applyConfig(prev.providerConfig);
      }
      return { ...prev, skills: skillsRef.current };
    });
  }, [applyConfig]);

  const installSkill = useCallback(
    async (files: File[]) => {
      if (files.length === 0) return;
      try {
        const inputs = await Promise.all(
          files.map(async (f) => {
            // For folder uploads, webkitRelativePath is "folderName/file.md"
            // Strip the top-level folder to get the relative path within the skill
            const fullPath = f.webkitRelativePath || f.name;
            const parts = fullPath.split("/");
            const path = parts.length > 1 ? parts.slice(1).join("/") : parts[0];
            return { path, data: new Uint8Array(await f.arrayBuffer()) };
          }),
        );
        const meta = await addSkill(inputs);
        console.log("[Chat] Installed skill:", meta.name);
        await refreshSkillsAndRebuildAgent();
      } catch (err) {
        console.error("[Chat] Failed to install skill:", err);
        setState((prev) => ({
          ...prev,
          error: err instanceof Error ? err.message : "Failed to install skill",
        }));
      }
    },
    [refreshSkillsAndRebuildAgent],
  );

  const uninstallSkill = useCallback(
    async (name: string) => {
      try {
        await removeSkill(name);
        console.log("[Chat] Uninstalled skill:", name);
        await refreshSkillsAndRebuildAgent();
      } catch (err) {
        console.error("[Chat] Failed to uninstall skill:", err);
      }
    },
    [refreshSkillsAndRebuildAgent],
  );

  const toggleFollowMode = useCallback(() => {
    setState((prev) => {
      if (!prev.providerConfig) return prev;
      const newFollowMode = !prev.providerConfig.followMode;
      followModeRef.current = newFollowMode;
      const newConfig = { ...prev.providerConfig, followMode: newFollowMode };
      saveConfig(newConfig);
      return { ...prev, providerConfig: newConfig };
    });
  }, []);

  return (
    <ChatContext.Provider
      value={{
        state,
        sendMessage,
        setProviderConfig,
        clearMessages,
        abort,
        availableProviders,
        getModelsForProvider,
        newSession,
        switchSession,
        deleteCurrentSession,
        getSheetName,
        toggleFollowMode,
        processFiles,
        refreshUploads,
        removeUpload,
        installSkill,
        uninstallSkill,
      }}
    >
      {children}
    </ChatContext.Provider>
  );
}
