import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { writeFile, readFileBuffer } from "../vfs";
import { withTemporaryChangeTracking } from "./word-change-tracking";

// Diagram constants
const STROKE_WIDTH = 2;
const DEFAULT_FONT_SIZE = 14;
const PADDING = 20;

// mxGraph/draw.io specific types
interface MxCell {
  id: string;
  vertex?: 1;
  edge?: 1;
  parent?: string;
  source?: string;
  target?: string;
  value?: string;
  style?: string;
  geometry?: MxGeometry;
}

interface MxGeometry {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  relative?: number;
  as?: "geometry";
}

interface DiagramNode {
  id: string;
  label: string;
  x: number;
  y: number;
  width: number;
  height: number;
}

interface DiagramEdge {
  from: string;
  to: string;
  label?: string;
  id: string;
}

interface ParsedDiagram {
  nodes: DiagramNode[];
  edges: DiagramEdge[];
}

// Generate unique ID for mxGraph elements
function generateMxId(prefix: string, index: number): string {
  return `${prefix}-${index}`;
}

/**
 * Parse a simple diagram description into nodes and edges.
 * Format:
 *   - "node: Label" to create a node
 *   - "Label1 -> Label2" or "Label1 -> Label2: description" to create an edge
 */
function parseDiagramDescription(description: string): ParsedDiagram {
  const lines = description
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
  const nodes = new Map<string, DiagramNode>();
  const edges: DiagramEdge[] = [];
  let nodeId = 0;
  let edgeId = 0;
  let yOffset = 0;
  const NODE_SPACING_X = 200;
  const NODE_SPACING_Y = 150;

  for (const line of lines) {
    // Match node definition: "node: Label"
    const nodeMatch = line.match(/^node:\s*(.+)$/i);
    if (nodeMatch) {
      const label = nodeMatch[1].trim();
      const id = generateMxId("node", nodeId++);
      const width = Math.max(120, label.length * 10 + PADDING * 2);
      const height = 60;
      const x = (nodeId % 3) * NODE_SPACING_X + 50;
      const y = Math.floor(nodeId / 3) * NODE_SPACING_Y + 50;
      nodes.set(label, { id, label, x, y, width, height });
      continue;
    }

    // Match edge: "Label1 -> Label2" or "Label1 -> Label2: description"
    const edgeMatch = line.match(/^(.+?)\s*->\s*(.+?)(?:\s*:\s*(.+))?$/i);
    if (edgeMatch) {
      const from = edgeMatch[1].trim();
      const to = edgeMatch[2].trim();
      const label = edgeMatch[3]?.trim();

      // Create nodes if they don't exist
      if (!nodes.has(from)) {
        const id = generateMxId("node", nodeId++);
        const width = Math.max(120, from.length * 10 + PADDING * 2);
        nodes.set(from, {
          id,
          label: from,
          x: 50 + Math.random() * 200,
          y: 50 + yOffset,
          width,
          height: 60,
        });
        yOffset += NODE_SPACING_Y;
      }
      if (!nodes.has(to)) {
        const id = generateMxId("node", nodeId++);
        const width = Math.max(120, to.length * 10 + PADDING * 2);
        nodes.set(to, {
          id,
          label: to,
          x: 50 + Math.random() * 200,
          y: 50 + yOffset,
          width,
          height: 60,
        });
        yOffset += NODE_SPACING_Y;
      }

      edges.push({ from, to, label, id: generateMxId("edge", edgeId++) });
    }
  }

  return { nodes: Array.from(nodes.values()), edges };
}

/**
 * Escape XML special characters
 */
function escapeXml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/**
 * Create mxCell for a rectangle node
 */
function createMxCellNode(node: DiagramNode): MxCell {
  const style = `rounded=1;whiteSpace=wrap;html=1;fillColor=#dae8fc;strokeColor=#6c8ebf;`;
  return {
    id: node.id,
    vertex: 1,
    parent: "1",
    value: escapeXml(node.label),
    style,
    geometry: {
      x: node.x,
      y: node.y,
      width: node.width,
      height: node.height,
      as: "geometry",
    },
  };
}

/**
 * Create mxCell for an edge/arrow
 */
function createMxCellEdge(
  edge: DiagramEdge,
  fromId: string,
  toId: string,
): MxCell {
  const style = `edgeStyle=orthogonalEdgeStyle;rounded=0;orthogonalLoop=1;jettySize=auto;html=1;endArrow=classic;endFill=1;strokeColor=#6c8ebf;`;
  return {
    id: edge.id,
    edge: 1,
    parent: "1",
    source: fromId,
    target: toId,
    value: edge.label ? escapeXml(edge.label) : undefined,
    style,
  };
}

/**
 * Export diagram to draw.io XML format (.drawio)
 */
function exportToDrawio(nodes: DiagramNode[], edges: DiagramEdge[]): string {
  let nodeIndex = 0;
  const nodeIdMap = new Map<string, string>();

  // Build cells
  const cells: string[] = [];

  // Root cell (parent)
  cells.push(`<mxCell id="0" />`);
  cells.push(`<mxCell id="1" parent="0" />`);

  // Node cells
  for (const node of nodes) {
    const mxNode = createMxCellNode(node);
    nodeIdMap.set(node.label, node.id);
    cells.push(
      `<mxCell id="${mxNode.id}" value="${mxNode.value}" style="${mxNode.style}" vertex="1" parent="${mxNode.parent}">`,
    );
    cells.push(
      `  <mxGeometry x="${mxNode.geometry?.x}" y="${mxNode.geometry?.y}" width="${mxNode.geometry?.width}" height="${mxNode.geometry?.height}" as="geometry" />`,
    );
    cells.push(`</mxCell>`);
  }

  // Edge cells
  for (const edge of edges) {
    const fromNode = nodes.find((n) => n.label === edge.from);
    const toNode = nodes.find((n) => n.label === edge.to);
    if (fromNode && toNode) {
      const mxEdge = createMxCellEdge(edge, fromNode.id, toNode.id);
      cells.push(
        `<mxCell id="${mxEdge.id}" value="${mxEdge.value ?? ""}" style="${mxEdge.style}" edge="1" parent="${mxEdge.parent}" source="${mxEdge.source}" target="${mxEdge.target}">`,
      );
      cells.push(`  <mxGeometry relative="1" as="geometry" />`);
      cells.push(`</mxCell>`);
    }
  }

  // Calculate bounds
  const canvasPadding = 50;
  const maxX =
    Math.max(...nodes.map((n) => n.x + n.width), 400) + canvasPadding;
  const maxY =
    Math.max(...nodes.map((n) => n.y + n.height), 300) + canvasPadding;

  const xml = `<mxfile host="app.diagrams.net" modified="${new Date().toISOString()}" agent="OfficeAI" version="21.0.0" etag="${Date.now()}" type="device">
  <diagram name="Page-1" id="Drawio-${Date.now()}">
    <mxGraphModel dx="1422" dy="762" grid="1" gridSize="10" guides="1" tooltips="1" connect="1" arrows="1" fold="1" page="1" pageScale="1" pageWidth="827" pageHeight="1169" math="0" shadow="0">
      <root>
${cells.map((c) => `        ${c}`).join("\n")}
      </root>
    </mxGraphModel>
  </diagram>
</mxfile>`;

  return xml;
}

/**
 * Export diagram to SVG format for Excel/Word insertion
 */
function exportToSvg(
  nodes: DiagramNode[],
  edges: DiagramEdge[],
  width: number,
  height: number,
): string {
  const svgParts: string[] = [];
  svgParts.push(`<?xml version="1.0" encoding="UTF-8"?>`);
  svgParts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`,
  );
  svgParts.push(`<rect width="100%" height="100%" fill="#ffffff"/>`);

  // Draw rectangles for nodes (matching draw.io style)
  for (const node of nodes) {
    const rx = 8; // rounded corners
    svgParts.push(
      `<rect x="${node.x}" y="${node.y}" width="${node.width}" height="${node.height}" fill="#dae8fc" stroke="#6c8ebf" stroke-width="2" rx="${rx}"/>`,
    );

    // Draw text label
    const centerX = node.x + node.width / 2;
    const centerY = node.y + node.height / 2;
    const escapedText = escapeXml(node.label);
    svgParts.push(
      `<text x="${centerX}" y="${centerY}" font-family="Arial, sans-serif" font-size="14" text-anchor="middle" dominant-baseline="middle" fill="#333333">${escapedText}</text>`,
    );
  }

  // Draw edges
  for (const edge of edges) {
    const fromNode = nodes.find((n) => n.label === edge.from);
    const toNode = nodes.find((n) => n.label === edge.to);
    if (fromNode && toNode) {
      const startX = fromNode.x + fromNode.width / 2;
      const startY = fromNode.y + fromNode.height / 2;
      const endX = toNode.x + toNode.width / 2;
      const endY = toNode.y + toNode.height / 2;

      // Draw arrow line
      svgParts.push(
        `<line x1="${startX}" y1="${startY}" x2="${endX}" y2="${endY}" stroke="#6c8ebf" stroke-width="2" marker-end="url(#arrowhead)"/>`,
      );

      // Draw edge label if present
      if (edge.label) {
        const midX = (startX + endX) / 2;
        const midY = (startY + endY) / 2;
        const escapedLabel = escapeXml(edge.label);
        // White background for label
        svgParts.push(
          `<rect x="${midX - escapedLabel.length * 5 - 4}" y="${midY - 12}" width="${escapedLabel.length * 10 + 8}" height="20" fill="white" stroke="none"/>`,
        );
        svgParts.push(
          `<text x="${midX}" y="${midY}" font-family="Arial, sans-serif" font-size="12" text-anchor="middle" dominant-baseline="middle" fill="#666666">${escapedLabel}</text>`,
        );
      }
    }
  }

  // Define arrowhead marker
  svgParts.push(
    `<defs><marker id="arrowhead" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto"><polygon points="0 0, 10 3.5, 0 7" fill="#6c8ebf"/></marker></defs>`,
  );

  svgParts.push("</svg>");
  return svgParts.join("\n");
}

/**
 * Convert SVG string to PNG base64 using canvas
 */
function svgToPng(
  svgContent: string,
  width: number,
  height: number,
): Promise<string> {
  return new Promise((resolve, reject) => {
    console.log(
      "[svgToPng] Starting conversion, dimensions:",
      width,
      "x",
      height,
    );
    console.log(
      "[svgToPng] SVG content (first 200 chars):",
      svgContent.substring(0, 200),
    );

    // Validate dimensions
    if (!width || !height || width <= 0 || height <= 0) {
      reject(new Error(`Invalid dimensions: ${width}x${height}`));
      return;
    }

    // Validate SVG content
    if (!svgContent || svgContent.length < 50) {
      reject(
        new Error(`Invalid SVG content, length: ${svgContent?.length ?? 0}`),
      );
      return;
    }

    const svgBlob = new Blob([svgContent], {
      type: "image/svg+xml;charset=utf-8",
    });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();

    // Set a timeout to catch hanging image loads
    const timeout = setTimeout(() => {
      URL.revokeObjectURL(url);
      reject(new Error("SVG to PNG conversion timed out after 5 seconds"));
    }, 5000);

    img.onload = () => {
      clearTimeout(timeout);
      console.log("[svgToPng] Image loaded, drawing to canvas");

      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        URL.revokeObjectURL(url);
        reject(new Error("Could not get canvas context"));
        return;
      }
      // Fill white background
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, width, height);
      ctx.drawImage(img, 0, 0);
      URL.revokeObjectURL(url);

      const dataUrl = canvas.toDataURL("image/png");
      const base64 = dataUrl.split(",")[1];
      console.log(
        "[svgToPng] PNG generated, base64 length:",
        base64?.length ?? 0,
      );
      resolve(base64);
    };

    img.onerror = (err) => {
      clearTimeout(timeout);
      URL.revokeObjectURL(url);
      console.error("[svgToPng] Image load error:", err);
      reject(new Error("Failed to load SVG for PNG conversion"));
    };

    img.src = url;
  });
}

/**
 * Generate diagram from description
 */
function generateDiagram(description: string): {
  svg: string;
  drawioXml: string;
  width: number;
  height: number;
} {
  const { nodes, edges } = parseDiagramDescription(description);

  // Calculate canvas bounds
  const canvasPadding = 50;
  const maxX =
    Math.max(...nodes.map((n) => n.x + n.width), 400) + canvasPadding;
  const maxY =
    Math.max(...nodes.map((n) => n.y + n.height), 300) + canvasPadding;

  const svg = exportToSvg(nodes, edges, maxX, maxY);
  const drawioXml = exportToDrawio(nodes, edges);
  return { svg, drawioXml, width: maxX, height: maxY };
}

/**
 * Insert Draw.io diagram tool - generates a visual diagram from text description
 */
export const insertDrawioTool = defineTool({
  name: "insert_drawio",
  label: "Insert Draw.io Diagram",
  description:
    "Generate and insert a visual diagram/flowchart from a text description using Draw.io (diagrams.net). " +
    "Creates professional diagrams perfect for workflows, system architecture, or process flows. " +
    "Use 'node: Label' to create nodes and 'Label1 -> Label2' to create connections. " +
    "Example: 'node: Start\\nnode: Process\\nnode: End\\nStart -> Process\\nProcess -> End'",
  parameters: Type.Object({
    description: Type.String({
      description:
        "Diagram description using simple syntax:\n" +
        "- 'node: Label' creates a node box\n" +
        "- 'A -> B' creates an arrow from node A to node B\n" +
        "- 'A -> B: label' creates an arrow with a label",
    }),
    sheetId: Type.Optional(
      Type.Number({
        description: "Required for Excel: The worksheet ID (1-based index)",
      }),
    ),
    anchor: Type.Optional(
      Type.String({
        description:
          "Required for Excel: Top-left cell where the diagram should be placed (e.g., 'A1', 'B5')",
      }),
    ),
    width: Type.Optional(
      Type.Number({
        description:
          "Optional: Diagram width in pixels. Auto-calculated if not specified",
      }),
    ),
    height: Type.Optional(
      Type.Number({
        description:
          "Optional: Diagram height in pixels. Auto-calculated if not specified",
      }),
    ),
    location: Type.Optional(
      Type.Union([
        Type.Literal("end"),
        Type.Literal("start"),
        Type.Literal("selection"),
      ]),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the diagram (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  dirtyTracking: {
    getRanges: (p) => [
      {
        sheetId: p.sheetId,
        range: p.anchor,
      },
    ],
  },
  execute: async (_toolCallId, params) => {
    try {
      console.log("[drawio] Generating diagram...", {
        description: params.description.substring(0, 50),
      });

      // Generate the diagram
      const { svg, drawioXml, width, height } = generateDiagram(
        params.description,
      );
      console.log("[drawio] Generated diagram:", {
        width,
        height,
        svgLength: svg.length,
        xmlLength: drawioXml.length,
      });

      // Save SVG to VFS
      const timestamp = Date.now();
      const svgFileName = `drawio-${timestamp}.svg`;
      await writeFile(svgFileName, svg);
      const svgFilePath = `/home/user/uploads/${svgFileName}`;
      console.log("[drawio] Saved SVG to:", svgFilePath);

      // Save .drawio XML to VFS for manual editing
      const xmlFileName = `drawio-${timestamp}.drawio`;
      await writeFile(xmlFileName, drawioXml);
      const xmlFilePath = `/home/user/uploads/${xmlFileName}`;
      console.log("[drawio] Saved .drawio XML to:", xmlFilePath);

      // Convert SVG to PNG for Excel compatibility
      console.log("[drawio] Converting SVG to PNG...");
      const pngBase64 = await svgToPng(svg, width, height);
      console.log("[drawio] PNG conversion, base64 length:", pngBase64.length);

      const isExcel = typeof Excel !== "undefined";
      const isWord = typeof Word !== "undefined";
      console.log("[drawio] Host detected:", { isExcel, isWord });

      // Validate: if Excel params provided but not in Excel, error
      if (params.sheetId && !isExcel) {
        return toolError(
          "Parameters 'sheetId' and 'anchor' are for Excel only. " +
            `You are currently in ${isWord ? "Word" : "an unsupported application"}. ` +
            "Please use 'location' parameter instead (e.g., 'end', 'start', 'selection').",
        );
      }

      if (isExcel) {
        if (!params.sheetId || !params.anchor) {
          return toolError("Excel requires sheetId and anchor parameters");
        }

        if (!pngBase64 || pngBase64.length < 100) {
          throw new Error(
            `PNG conversion failed or produced invalid image (base64 length: ${pngBase64?.length ?? 0})`,
          );
        }

        // Excel: use raw base64 PNG
        console.log("[drawio] Starting Excel insertion...");
        const result = await Excel.run(async (context) => {
          console.log("[drawio] Excel.run started");
          const { preloadSheetIds } = await import("../excel/sheet-id-map");
          const sheets = context.workbook.worksheets;
          sheets.load("items");
          await context.sync();
          console.log("[drawio] Sheets loaded:", sheets.items.length);

          for (const sheet of sheets.items) {
            sheet.load("id");
          }
          await context.sync();

          const idMap = await preloadSheetIds(sheets.items);
          let targetSheet: Excel.Worksheet | null = null;

          for (const sheet of sheets.items) {
            const sheetId = idMap.get(sheet.id);
            console.log("[drawio] Checking sheet:", sheet.name, "ID:", sheetId);
            if (sheetId === params.sheetId) {
              targetSheet = sheet;
              console.log("[drawio] Found target sheet:", sheet.name);
              break;
            }
          }

          if (!targetSheet) {
            throw new Error(`Worksheet with ID ${params.sheetId} not found`);
          }

          console.log("[drawio] Getting anchor cell:", params.anchor);
          const anchorCell = targetSheet.getRange(params.anchor);
          anchorCell.load("left, top");
          await context.sync();
          console.log(
            "[drawio] Anchor cell position:",
            anchorCell.left,
            anchorCell.top,
          );

          const shapes = targetSheet.shapes;
          console.log(
            "[drawio] Adding image with base64 length:",
            pngBase64.length,
          );
          const imageShape = shapes.addImage(pngBase64);
          console.log("[drawio] Image shape added");

          imageShape.left = anchorCell.left ?? 0;
          imageShape.top = anchorCell.top ?? 0;

          if (params.width) imageShape.width = params.width;
          if (params.height) imageShape.height = params.height;

          await context.sync();
          console.log("[drawio] Shape positioned");

          imageShape.load("id, left, top, width, height");
          await context.sync();
          console.log("[drawio] Shape loaded with ID:", imageShape.id);

          return {
            success: true,
            filePath: svgFilePath,
            drawioFilePath: xmlFilePath,
            shapeId: imageShape.id,
            anchor: params.anchor,
            width: imageShape.width,
            height: imageShape.height,
          };
        });
        console.log("[drawio] Excel.run completed successfully");

        return toolSuccess(result);
      }

      if (isWord) {
        // Word: use PNG base64 with insertInlinePictureFromBase64
        console.log("[drawio] Starting Word insertion with PNG...");
        console.log("[drawio] PNG base64 length:", pngBase64.length);

        // Validate PNG header (first 4 bytes should be PNG signature)
        if (!pngBase64.startsWith("iVBORw0K")) {
          console.error(
            "[drawio] Invalid PNG format, base64 prefix:",
            pngBase64.substring(0, 20),
          );
          return toolError("Generated image is not a valid PNG format");
        }
        console.log("[drawio] PNG signature verified");

        const result = await Word.run(async (context) => {
          console.log("[drawio] Word.run started");
          return withTemporaryChangeTracking(
            context,
            true,
            async () => {
              const body = context.document.body;
              const location = params.location ?? "end";
              console.log("[drawio] Location:", location);

              let paragraph: Word.Paragraph;

              if (location === "selection") {
                console.log("[drawio] Inserting at selection");
                const selection = context.document.getSelection();
                paragraph = selection.insertParagraph(
                  "",
                  Word.InsertLocation.after,
                );
              } else if (location === "start") {
                console.log("[drawio] Inserting at start");
                paragraph = body.insertParagraph("", Word.InsertLocation.start);
              } else {
                console.log("[drawio] Inserting at end");
                paragraph = body.insertParagraph("", Word.InsertLocation.end);
              }

              await context.sync();
              console.log("[drawio] Paragraph inserted");

              console.log(
                "[drawio] Inserting inline picture, base64 length:",
                pngBase64.length,
              );
              const picture = paragraph.insertInlinePictureFromBase64(
                pngBase64,
                Word.InsertLocation.replace,
              );
              console.log("[drawio] Picture inserted, loading properties...");

              picture.load("width, height, altText");

              if (params.width || params.height) {
                if (params.width) picture.width = params.width;
                if (params.height) picture.height = params.height;
                console.log(
                  "[drawio] Set dimensions:",
                  params.width,
                  "x",
                  params.height,
                );
              }

              await context.sync();
              console.log(
                "[drawio] Sync completed, picture dimensions:",
                picture.width,
                "x",
                picture.height,
              );

              return {
                success: true,
                filePath: svgFilePath,
                drawioFilePath: xmlFilePath,
                location,
                width: picture.width ?? width,
                height: picture.height ?? height,
              };
            },
          );
        });
        console.log("[drawio] Word.run completed successfully");

        return toolSuccess(result);
      }

      return toolError(
        "Draw.io tool requires Excel or Word API to be available",
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error creating diagram";
      return toolError(message);
    }
  },
});
